window.__Q=window.__Q||{};window.__Q["prev/7/A2"]=[{"q":"患者，男，46岁，因患有下肢深静脉血栓，用华法林治疗4个月，近期因失眠加用苯巴比妥。结果患者的凝血酶原时间比未用苯巴比妥时缩短，其主要原因是","o":["苯巴比妥可诱导肝药酶活性，使华法林代谢加速","苯巴比妥可抑制肝药酶活性，使华法林代谢加速","苯巴比妥可诱导肝药酶活性，使华法林代谢减慢","患者对华法林产生了耐药性","苯巴比妥抑制凝血酶"],"a":0,"e":"苯巴比妥是肝药酶诱导剂，能加速华法林的肝脏代谢，使其血药浓度下降、抗凝作用减弱，故凝血酶原时间缩短。诱导肝药酶却抑制代谢在逻辑上自相矛盾，B项不成立；C项把诱导说成代谢减慢亦错误；耐药性并非机制，D项错；苯巴比妥不抑制凝血酶，E项无据"},{"q":"患者，男，50岁，因血尿、黑便、关节肿痛3天入院。医院给予氨甲苯酸治疗，并及时输注血浆，治疗药物氨甲苯酸的作用机制是","o":["竞争性阻止纤溶酶","促进血小板聚集","促进凝血酶原合成","抑制二氢叶酸合成酶","减少血栓素的生成"],"a":0,"e":"氨甲苯酸为抗纤溶药，能竞争性抑制纤溶酶原激活因子，阻止纤溶酶形成，从而抑制纤维蛋白溶解而止血，适用于纤溶亢进所致出血。促进血小板聚集是酚磺乙胺等的作用，B项不符；促进凝血酶原合成实为维生素K，C项错；抑制二氢叶酸合成酶为磺胺类机制，D项错"},{"q":"患者，女，53岁。视物模糊、眼胀、头痛半月，经检测左眼压为45mmHg，右眼压为35mmHg（正常眼压范围：10～21mmHg），诊断为青光眼。下列治疗青光眼的药物中，属于肾上腺素受体阻断药的是","o":["毛果芸香碱","毒扁豆碱","噻吗洛尔","乙酰唑胺","拉坦前列素"],"a":2,"e":"噻吗洛尔为非选择性β受体阻断药，可减少房水生成、降低眼压，是治疗青光眼的β受体阻断药代表。毛果芸香碱为M胆碱受体激动药，A项属拟胆碱药，通过缩瞳促进房水回流；毒扁豆碱为胆碱酯酶抑制剂，B项亦属拟胆碱；乙酰唑胺为碳酸酐酶抑制剂，D项非β阻断；拉坦前列素为前列腺素类，E项属另类降眼压药"},{"q":"患者，男，70岁，1周前出现发热、咳嗽、咳痰、喘息等症状，诊断为支气管感染，医生给予抗生素和祛痰药联合治疗。患者应用祛痰药的目的，错误的是","o":["可以使痰液变稀或溶解，使痰易于咳出","可以作为镇咳药的辅助药使用","促进痰液的排出，减少刺激性，间接镇咳平喘","促进支气管腺体分泌，有控制继发性感染的作用","有弱的防腐消毒作用，可减轻痰液恶臭"],"a":4,"e":"祛痰药通过稀释或溶解痰液、促进排出，减少刺激而间接镇咳平喘，部分药物促进支气管腺体分泌，有助于控制继发感染。具有弱防腐消毒、减轻痰液恶臭并非祛痰药作用，E项无此用途。使痰变稀易咳出、作镇咳辅助药、促进排出减少刺激、促进腺体分泌控制感染分属A～D项，均属祛痰目的"},{"q":"患者，男，58岁。患高血压性心脏病数年，有时因激动或过劳而发生心绞痛，最初经休息后尚可自行缓解，几天之后心绞痛加重并有心律失常，此时合理的治疗方案是","o":["维拉帕米＋硝苯地平","硝酸甘油＋硝酸异山梨酯","地尔硫䓬＋普萘洛尔","普萘洛尔＋维拉帕米","硝酸甘油＋普萘洛尔"],"a":4,"e":"硝酸甘油扩张静脉、降低前负荷并扩张冠脉，普萘洛尔减慢心率、降低心肌耗氧，二者互为补充，是稳定型心绞痛合并心律失常的合理联用，且β受体阻断药可纠正心律失常。维拉帕米与普萘洛尔（D项）或维拉帕米与地尔硫䓬（A、C项）合用均严重抑制心脏传导与收缩，属禁忌；两种硝酸酯类（B项）合用只增不良反应"},{"q":"因脑出血颅内高压行开颅手术，以下最不适合使用的麻醉药是","o":["七氟烷","异氟烷","丙泊酚","氟烷","依托咪酯"],"a":3,"e":"氟烷可扩张脑血管、增加脑血流量和颅内压，颅内高压患者使用可加重病情，故最不宜。七氟烷、异氟烷虽也轻度扩张脑血管，但可控性较好，A、B项相对可用；丙泊酚（C项）降低脑代谢和颅内压，常用于神经外科；依托咪酯（E项）对颅内压影响小，亦可用于麻醉诱导"},{"q":"一位患有足癣的患者需要局部应用抗真菌药，下列哪种药物不宜应用","o":["制霉菌素","氟康唑","克霉唑","咪康唑","益康唑"],"a":1,"e":"氟康唑为三唑类全身用抗真菌药，口服或静脉给药治疗深部真菌感染，一般不用于皮肤局部涂布，局部应用易致耐药。制霉菌素、克霉唑、咪康唑、益康唑（A、C、D、E项）均为外用抗真菌药，可直接涂于患处治疗足癣，故B项氟康唑不宜局部应用"},{"q":"患者，男，70岁，因上呼吸道感染，出现咳嗽、咳痰等症状，医生给予祛痰药进行治疗。直接作用于支气管腺体，促进黏液分泌细胞的溶酶体释出，裂解黏痰中的粘多糖纤维的药物是","o":["N-乙酰半胱氨酸","氯化铵","溴己新","喷托维林","氯哌斯汀"],"a":2,"e":"溴己新直接作用于支气管腺体，促使黏液分泌细胞溶酶体释出，裂解痰中黏多糖纤维，使痰液变稀易于咳出。N-乙酰半胱氨酸（A项）通过断裂黏蛋白二硫键降低黏度，机制不同；氯化铵（B项）为反射性祛痰药；喷托维林、氯哌斯汀（D、E项）为中枢性镇咳药，无祛痰作用"},{"q":"患者，男，55岁。近日因充血性心力衰竭入院治疗，服用地高辛后出现心率过缓，心电图显示频发室性期前收缩。请问下列哪项措施是错误的","o":["停药","给氯化钾","给苯妥英钠","加用呋塞米促进其排出","给地高辛特异性抗体"],"a":3,"e":"呋塞米为排钾利尿药，可致低血钾，低钾增强地高辛对心肌的毒性并加重心律失常，故中毒时不宜用其促进排出。立即停药、补钾、苯妥英钠（A、B、C项）及地高辛特异性抗体（E项）均为正确救治措施，其中苯妥英钠专治强心苷所致室性心律失常"},{"q":"患者，女，32岁，近半月来明显消瘦、怕热、多汗、心悸、烦躁，经检测T3、T4均明显增高，诊断为甲状腺功能亢进。除给予甲巯咪唑治疗外，为对抗激动不安、心动过速等症状，还可加用","o":["阿托品","普萘洛尔","酚妥拉明","哌唑嗪","育亨宾"],"a":1,"e":"普萘洛尔为β受体阻断药，可阻断交感神经对心脏的兴奋，减慢心率、抑制心悸与激动不安，并能抑制外周T4向T3转化，适合甲亢辅助治疗。阿托品（A项）阻断M受体，会加快心率，方向相反；酚妥拉明、哌唑嗪（C、D项）为α受体阻断药，主要扩血管降压；育亨宾（E项）为α2受体阻断药，均不能控制甲亢症状"},{"q":"当皮肤撕裂伤需要缝合，通过浸润方式给予局麻药时，常在局麻药溶液中加入少量肾上腺素，其原因为","o":["拮抗局麻药强烈而常见的血管收缩和高血压作用","对抗局麻药引起的心脏抑制","防止对局麻药过敏的病人发生过敏反应","延缓局麻药的吸收，延长其作用时间","增强局麻药作用强度"],"a":3,"e":"肾上腺素收缩局部血管，延缓局麻药吸收入血，既延长局麻作用时间，又降低全身吸收中毒风险，并减少术区出血。肾上腺素本身不拮抗高血压，A项说法相反；局麻药并无明显心脏抑制需对抗，B项不成立；肾上腺素不能防止过敏反应，C项错误；增强作用强度（E项）非其主要目的"},{"q":"患者，女，26岁，患AIDS因患隐球菌性脑膜炎需要应用抗真菌药，但她拒绝接受静脉给药治疗。下述哪种药物口服时对脑膜炎疗效最好","o":["两性霉素B","氟康唑","酮康唑","制霉菌素","甲硝唑"],"a":1,"e":"氟康唑口服吸收好、生物利用度高，能透过血脑屏障，在脑脊液中浓度高，是隐球菌性脑膜炎口服治疗首选。两性霉素B（A项）需静脉给药且毒性大；酮康唑（C项）口服吸收差、不易入脑；制霉菌素（D项）口服不吸收，仅用于肠道或局部；甲硝唑（E项）为抗厌氧菌和抗阿米巴药，对隐球菌无效"},{"q":"患者，女，19岁，心境低落，兴趣减退，有自杀观念，给予三环类药（TCAs）治疗，其最常见的不良反应是","o":["心律失常","粒细胞减少","过敏反应","锥体外系反应","抗胆碱作用"],"a":4,"e":"三环类抗抑郁药阻断M胆碱受体，抗胆碱作用最常见，表现为口干、便秘、视力模糊、尿潴留等。心律失常（A项）虽是其重要毒性但不是最常见；粒细胞减少（B项）多见于氯氮平；过敏反应（C项）少见；锥体外系反应（D项）主要见于抗精神病药，TCAs极少引起"},{"q":"患者，女，46岁，患三叉神经痛，长期服用卡马西平。现患牙周炎需服用抗生素控制感染，7天后出现卡马西平的神经毒性反应：头晕，头痛，共济失调。请问患者前面服用的抗生素最可能是","o":["青霉素","头孢噻肟","阿莫西林","红霉素","庆大霉素"],"a":3,"e":"红霉素抑制肝药酶CYP3A4，减慢卡马西平代谢，使其血药浓度升高而出现头晕、共济失调等神经毒性。青霉素、头孢噻肟、阿莫西林（A、B、C项）基本不经肝药酶代谢，不影响卡马西平浓度；庆大霉素（E项）主要经肾排泄，亦无此相互作用"},{"q":"患者，男，59岁，因入睡困难就诊。查体正常，诊断为失眠，使用t1/2为1小时的镇静催眠药，给予100mg剂量后，患者在体内药物只剩12.5mg时便清醒过来，该患者睡了多长时间","o":["0.5小时","2小时","3小时","4小时","5小时"],"a":2,"e":"按一级动力学，每过一个半衰期药量减半，100mg降至12.5mg需经100→50→25→12.5三次减半，即3个半衰期；t1/2为1小时，故睡眠时间为3小时。0.5小时（A项）只减半一次，2小时（B项）仅剩25mg，4小时（D项）和5小时（E项）剩余量远低于12.5mg，均不符"},{"q":"患者，男，59岁，因右背肿物就诊。查体正常，B超显示右侧肩胛骨下脂肪瘤5cm×7cm大小，拟采用局麻手术切除。用普鲁卡因加入少量肾上腺素的目的是","o":["预防局麻药过敏","延长局麻药作用时间","预防心脏骤停","预防手术中出血","防止低血压"],"a":1,"e":"肾上腺素收缩局部血管，延缓普鲁卡因吸收，使局麻作用时间延长并减少全身毒性。预防过敏（A项）靠皮试而非肾上腺素；普鲁卡因无明显心脏抑制，预防心脏骤停（C项）不成立；局麻手术范围小、出血可控，D项非主要目的；防止低血压（E项）与局麻药无关"},{"q":"患者，女，35岁，因“孕足月待产”，拟在连续硬膜外麻醉下行剖宫产术，下列可用于首选的药物是","o":["罗哌卡因","布比卡因","利多卡因","丁卡因","普鲁卡因"],"a":0,"e":"罗哌卡因是新型长效酰胺类局麻药，感觉与运动阻滞分离明显，对子宫胎盘血流影响小、毒性低，适合产科硬膜外麻醉。布比卡因（B项）心脏毒性大；利多卡因（C项）时效短；丁卡因（D项）毒性大、多用于蛛网膜下腔；普鲁卡因（E项）为短效酯类，均非剖宫产首选"},{"q":"患者，男，30岁，草绿色链球菌引起感染性心内膜炎，拟用青霉素G和下列其中一药合用，宜选","o":["氯霉素","庆大霉素","四环素","红霉素","氨苄西林"],"a":1,"e":"青霉素G与庆大霉素合用对草绿色链球菌有协同杀菌作用，用于感染性心内膜炎。氯霉素、四环素、红霉素（A、C、D项）为抑菌药，与青霉素合用可产生拮抗；氨苄西林（E项）与青霉素G同属β-内酰胺类，作用机制重叠，无协同意义"},{"q":"患者，女，32岁。铜绿假单胞菌感染，高热、畏冷、寒颤、咳嗽。给予头孢菌素治疗，宜选","o":["头孢氨苄","头孢拉定","头孢孟多","头孢克洛","头孢他啶"],"a":4,"e":"头孢他啶为第三代头孢菌素，对铜绿假单胞菌抗菌活性强，是治疗该菌感染的头孢类首选。头孢氨苄、头孢拉定、头孢克洛（A、B、D项）分别为一、二代头孢，对铜绿假单胞菌无效；头孢孟多（C项）为二代头孢，亦无抗铜绿假单胞菌作用"},{"q":"患儿，男，9岁，因误食林中色彩鲜艳的蘑菇出现中毒症状，采用阿托品进行治疗。阿托品对乙酰胆碱量效曲线的影响是","o":["平行右移，最大效应不变","右移，最大效应降低","平行左移，最大效应不变","左移，最大效应降低","不变"],"a":0,"e":"阿托品是M受体竞争性阻断药，与乙酰胆碱竞争同一受体，增大乙酰胆碱浓度可克服其阻断，故量效曲线平行右移而最大效应不变。右移伴最大效应降低（B项）属非竞争性拮抗表现；左移（C、D项）为激动药或增敏的表现；曲线不变（E项）不符合拮抗规律"},{"q":"患者，男，65岁。因前列腺肥大导致膀胱颈梗阻，排尿困难，行前列腺切除术。对手术后的出血宜选用的止血药是","o":["维生素K","鱼精蛋白","氨甲苯酸","右旋糖酐","垂体后叶素"],"a":2,"e":"前列腺切除术后出血多因纤溶亢进，氨甲苯酸抑制纤溶酶原激活、阻止纤维蛋白溶解而止血，是此类手术出血的常用药。维生素K（A项）用于凝血因子缺乏性出血；鱼精蛋白（B项）拮抗肝素；右旋糖酐（D项）为血浆代用品；垂体后叶素（E项）主要用于肺咯血及门脉高压出血"},{"q":"患者，男，67岁。患尿毒症半年，近10天来无诱因发热，体温38.6～39.8℃，收住院。相关检查显示：肾功能丧失，血液透析维持正常生理功能。血液透析导管处分泌液培养：金黄色葡萄球菌（＋＋＋）；药敏：头孢哌酮-舒巴坦S、万古霉素S、阿莫西林/克拉维酸钾S。下面哪种药不宜使用","o":["头孢哌酮","舒巴坦","万古霉素","阿莫西林","克拉维酸钾"],"a":2,"e":"万古霉素具有明显肾毒性，主要经肾排泄，尿毒症患者肾功已丧失，使用易蓄积并加重肾损害，且该菌对多种药物敏感，无需选用，故不宜使用。头孢哌酮、舒巴坦、阿莫西林、克拉维酸钾（A、B、D、E项）药敏均敏感，其中舒巴坦与克拉维酸为β-内酰胺酶抑制剂，可选用"},{"q":"患者，女，36岁，感冒后出现喘息、咳嗽、胸闷等症状。入院后诊断为支气管哮喘急性发作，医生推荐使用β2受体激动药控制哮喘症状，下列药物符合要求的是","o":["肾上腺素","异丙肾上腺素","沙丁胺醇","多巴酚丁胺","色甘酸钠"],"a":2,"e":"沙丁胺醇为选择性β2受体激动药，激动支气管平滑肌β2受体，舒张支气管、迅速缓解哮喘症状，是控制急性发作的首选。肾上腺素、异丙肾上腺素（A、B项）对β1、β2选择性低，心脏兴奋作用强；多巴酚丁胺（D项）主要兴奋β1用于强心；色甘酸钠（E项）为肥大细胞膜稳定药，仅用于预防"},{"q":"患者，女，29岁。左眼下方视物遮挡2个月，否认眼痛及眼球转动痛。查视力：右眼1.0，左眼0.8。为明确诊断，排除视网膜病变，需散瞳进行眼底检查，因此给予","o":["毛果芸香碱","东莨菪碱","阿托品","毒扁豆碱","山莨菪碱"],"a":2,"e":"阿托品阻断M胆碱受体，松弛瞳孔括约肌和睫状肌，产生扩瞳和调节麻痹，作用强而持久，适合散瞳行眼底检查。毛果芸香碱（A项）为M激动药，缩瞳；毒扁豆碱（D项）为胆碱酯酶抑制剂，亦缩瞳；东莨菪碱、山莨菪碱（B、E项）虽为M阻断药，但扩瞳作用弱、多用于中枢或解痉，不作散瞳首选"},{"q":"患儿，3岁，近来经常在玩耍中突然停顿、两眼直视、面无表情，几秒钟即止，每天发作几十次，查体正常，脑电图显示发作性棘波、尖波，应使用下列哪种药物治疗","o":["苯妥英钠","苯巴比妥","卡马西平","乙琥胺","氯丙嗪"],"a":3,"e":"患儿表现为短暂意识丧失、两眼直视、每日多次发作，脑电图棘波、尖波，符合癫痫失神发作，乙琥胺是治疗小发作的首选药，可抑制丘脑T型钙通道。苯妥英钠、卡马西平（A、C项）对失神发作无效甚至加重；苯巴比妥（B项）主要用于大发作；氯丙嗪（E项）为抗精神病药，不用于癫痫"},{"q":"患者，男，25岁，反复出现上腹部疼痛、反酸、嗳气等症状，诊断为胃消化性溃疡，医生给予控酸药进行治疗。胃酸和胃蛋白酶分泌过程受神经-体液机制调控，在这个过程中能抑制胃酸形成的最后环节，发挥治疗消化性溃疡作用的药物是","o":["西咪替丁","哌仑西平","丙谷胺","奥美拉唑","米索前列醇"],"a":3,"e":"奥美拉唑为质子泵抑制剂，不可逆抑制胃壁细胞H+-K+-ATP酶，阻断胃酸分泌的最后共同环节，抑酸作用强而持久，是消化性溃疡首选。西咪替丁（A项）阻断H2受体，哌仑西平（B项）阻断M1受体，丙谷胺（C项）阻断胃泌素受体，均作用于上游环节；米索前列醇（E项）为前列腺素类，主要保护黏膜"},{"q":"患者，女，54岁，糖尿病史10余年，左心室肥厚伴血压高（150/110mmHg），首选药物为","o":["氢氯噻嗪","硝苯地平","依那普利","普萘洛尔","吲达帕胺"],"a":2,"e":"依那普利为ACE抑制剂，降压同时能逆转左室肥厚、改善胰岛素敏感性并保护肾脏，适合糖尿病合并高血压及左室肥厚者。氢氯噻嗪、吲达帕胺（A、E项）为利尿剂，可能影响糖代谢；硝苯地平（B项）为钙拮抗药，逆转肥厚作用弱；普萘洛尔（D项）可掩盖低血糖症状，均非首选"},{"q":"患者，男，70岁，高热，体温39.5℃，排尿不适，尿频、尿急，尿常规示白细胞增高，送检中段尿培养，结果显示铜绿假单胞菌阳性，考虑诊断为铜绿假单胞菌性尿路感染，以下药物不适合用于该患者治疗的是","o":["环丙沙星","头孢曲松","庆大霉素","哌拉西林","甲氧苄啶"],"a":4,"e":"甲氧苄啶为二氢叶酸还原酶抑制剂，单用抗菌谱窄，对铜绿假单胞菌无可靠抗菌活性，不适合该菌所致尿路感染。环丙沙星（A项）为喹诺酮类、庆大霉素（C项）为氨基糖苷类、哌拉西林（D项）为抗铜绿假单胞菌青霉素，对该菌均有良好活性，是常用治疗药物"},{"q":"一位霍奇金淋巴瘤的病人接受氮芥作为其治疗计划的一部分。下列哪个选项正确描述了氮芥的抗肿瘤作用机制","o":["烷化剂，使DNA交叉联结发生断裂","抑制微管聚合，抑制细胞有丝分裂","抑制拓扑异构酶","嵌入DNA碱基对中，阻止mRNA的合成","干扰核酸的生物合成"],"a":0,"e":"氮芥属烷化剂，其活泼基团与DNA碱基形成共价结合，造成DNA链内或链间交叉联结，使DNA断裂、复制受阻，从而杀伤肿瘤细胞。抑制微管聚合（B项）是长春碱类机制；抑制拓扑异构酶（C项）是依托泊苷机制；嵌入DNA抑制mRNA（D项）为放线菌素D机制；干扰核酸合成（E项）为抗代谢药机制"},{"q":"患者，男，68岁。夜间突发鼻出血，经冷敷处理后仍无法止血，入院后可采用的紧急措施是","o":["多巴胺滴鼻","去甲肾上腺素滴鼻","去甲肾上腺素注射","肾上腺素纱条填塞","异丙肾上腺素纱条填塞"],"a":3,"e":"肾上腺素激动α受体，使鼻黏膜血管强烈收缩，用纱条局部填塞可直接压迫并收缩血管止血，是鼻出血的紧急局部处理。多巴胺滴鼻（A项）无局部止血作用；去甲肾上腺素滴鼻（B项）或注射（C项）不如局部填塞直接有效；异丙肾上腺素（E项）扩张血管，反而加重出血"},{"q":"患者，女，42岁，主诉近日以来常觉头痛，测量血压为165/100mmHg。根据患者情况，应选择下列何种钙拮抗药进行治疗最为适合","o":["维拉帕米","硝苯地平","尼莫地平","尼群地平","地尔硫䓬"],"a":2,"e":"尼莫地平为二氢吡啶类钙拮抗药，脂溶性高、易透过血脑屏障，能扩张脑血管、改善脑供血并缓解血管痉挛，适合高血压伴头痛者。维拉帕米、地尔硫䓬（A、E项）非二氢吡啶类，主要抑制心脏；硝苯地平（B项）扩张外周血管，对脑血管选择性差；尼群地平（D项）亦以降压为主"},{"q":"患者，女，28岁，大面积烧伤并铜绿假单胞菌感染，选用羧苄西林治疗。羧苄西林属于","o":["耐酸青霉素","耐酶青霉素","广谱青霉素","抗铜绿假单胞菌广谱青霉素","抗G－杆菌青霉素"],"a":3,"e":"羧苄西林为羧基青霉素，抗菌谱广，对铜绿假单胞菌有较强活性，属抗铜绿假单胞菌广谱青霉素。耐酸青霉素（A项）如青霉素V可口服；耐酶青霉素（B项）如氯唑西林用于耐药金葡菌；广谱青霉素（C项）如氨苄西林对铜绿假单胞菌无效；抗G－杆菌青霉素（E项）如美西林主要针对肠杆菌"},{"q":"患者，女，60岁。给予一种治疗药物，按一级动力学消除，上午9时测得血药浓度为100μg/ml，晚6时测得的血药浓度为12.5μg/ml。则此药的t1/2为","o":["1小时","2小时","3小时","6小时","9小时"],"a":2,"e":"上午9时至晚6时共9小时，血药浓度由100μg/ml降至12.5μg/ml，经历100→50→25→12.5三次减半，即3个半衰期，故t1/2为9÷3＝3小时。1小时（A项）和2小时（B项）经9小时将衰减更多；6小时（D项）、9小时（E项）减半次数不足，均不能得到12.5μg/ml"},{"q":"患者，女，15岁，行颈部皮下皮脂腺瘤切除术，使用局麻药利多卡因，该药的pKa是7.9，在pH为6.9时，其解离型药物所占比例约为","o":["0.01","0.1","0.5","0.9","0.99"],"a":3,"e":"利多卡因为弱碱性药物，解离型比例＝1/(1＋10^(pH－pKa))＝1/(1＋10^(6.9－7.9))＝1/(1＋0.1)≈0.91，约0.9。0.01、0.1（A、B项）为酸性环境或非离子型比例的计算结果；0.5（C项）出现在pH＝pKa时；0.99（E项）对应pH比pKa低2个单位以上，均不符"},{"q":"患儿，女，6岁，因“咳嗽3周，发热3天”就诊。患儿3周前无明显诱因出现刺激性干咳，每次10余声，频繁。体温最高39、4℃。血常规显示：白细胞数7×109/L，淋巴细胞比率增高，中性粒细胞比率下降。胸片显示：左肺下叶条索状阴影。支原体抗体阳性。诊断为支原体肺炎，应首选下列哪种药物治疗","o":["青霉素G","红霉素","磺胺嘧啶","氯霉素","四环素"],"a":1,"e":"支原体无细胞壁，青霉素G、头孢类无效；红霉素为大环内酯类，能抑制支原体蛋白合成，是支原体肺炎首选，尤其适用于儿童。青霉素G（A项）作用于细胞壁，对支原体无效；磺胺嘧啶、氯霉素（C、D项）疗效差且毒性较大；四环素（E项）虽有效，但8岁以下儿童禁用，以免影响牙齿骨骼发育"},{"q":"患者，女，30岁。家人发现其神志不清2小时，皮肤湿冷，双侧瞳孔缩小，呼气有大蒜味，双肺可闻及散在湿啰音。患者病因最可能是","o":["吗啡中毒","有机磷农药中毒","安眠药中毒","脑出血","阿托品中毒"],"a":1,"e":"患者神志不清、皮肤湿冷、瞳孔缩小、呼气大蒜味、双肺湿啰音，为有机磷农药中毒的典型毒蕈碱样表现，因胆碱酯酶被抑制、乙酰胆碱蓄积所致。吗啡中毒（A项）虽有瞳孔缩小和呼吸抑制，但无大蒜味与明显湿啰音；安眠药中毒（C项）以中枢抑制为主；脑出血（D项）多有偏瘫；阿托品中毒（E项）表现为瞳孔扩大、皮肤潮红"},{"q":"患者，女，25岁。因感冒后3天出现全身水肿，呈中度凹陷性，全天性质一样，伴尿频、尿急，尿液呈淡茶色，入院就诊。患者尿量减少，无明显肉眼血尿，无双侧腰痛，无乏力，无食欲缺乏，无咳嗽、咳痰，无恶心、呕吐，无腹痛、腹泻，无头晕、头痛。尿检：红细胞585个/μl，白细胞416个/μl，上皮细胞225个/μl，细菌8642个/μl，BLD（＋＋），PRO（＋＋）。诊断为急性肾小球肾炎。给予注射用盐酸克林霉素1.2g，用0、9%氯化钠注射液150ml溶解并稀释后静脉滴注。滴注完毕后上肢疼痛明显，伴肿胀，无瘙痒。请问引起上述症状的原因可能是","o":["不宜使用克林霉素","克林霉素用量过大","使用克林霉素出现过敏","克林霉素静脉滴注浓度过高","未合并使用抗过敏药物"],"a":3,"e":"1.2g克林霉素溶于150ml液体，浓度达8mg/ml，超过静脉滴注推荐浓度，可刺激血管引起上肢疼痛、肿胀等血栓性静脉炎表现。克林霉素可用于敏感菌感染（A项错）；1.2g为常用剂量，非过量（B项错）；无瘙痒支持非过敏（C项错）；是否合用抗过敏药与局部刺激无关（E项错）"},{"q":"患者，男，30岁，主诉周期性上腹疼痛、嗳气、反酸、胸骨后烧灼感等症状。给予奥美拉唑治疗，其属于下述哪类药物","o":["H1受体阻断药","M受体阻断药","抗酸类药","H＋-K＋-ATP酶抑制药","胆碱能受体阻断药"],"a":3,"e":"奥美拉唑为质子泵抑制剂，特异性抑制胃壁细胞H+-K+-ATP酶，阻断胃酸分泌最后环节，抑酸强而持久。H1受体阻断药（A项）如苯海拉明用于抗过敏；M受体阻断药（B、E项）如哌仑西平、阿托品抑制迷走神经抑酸；抗酸类药（C项）如氢氧化铝为中和胃酸，均非奥美拉唑机制"},{"q":"患者，男，55岁。确诊稳定性心绞痛，经一个时期的治疗，效果欠佳，拟采用联合用药，请问下述哪一种较为合理","o":["硝酸甘油＋硝苯地平","硝酸甘油＋硝酸异山梨酯","维拉帕米＋普萘洛尔","硝酸甘油＋美托洛尔","维拉帕米＋地尔硫䓬"],"a":3,"e":"硝酸甘油扩张血管、降低前负荷并扩张冠脉，美托洛尔为β1受体阻断药，减慢心率、降低心肌耗氧，二者机制互补且可相互抵消心率增快等不良反应，是稳定型心绞痛合理联用。维拉帕米与普萘洛尔（C项）或维拉帕米与地尔硫䓬（E项）合用严重抑制心脏；两种硝酸酯（B项）或硝酸甘油与硝苯地平（A项）易致低血压与反射性心率加快"},{"q":"患儿，女，14岁。车祸入院手术，用吗啡止痛。使用吗啡时不会出现下列哪项作用","o":["镇痛、镇静","瞳孔缩小","镇咳","呼吸抑制","增加肠道蠕动"],"a":4,"e":"吗啡兴奋胃肠平滑肌、提高张力但抑制蠕动，使肠内容物通过减慢，引起便秘，故不会出现肠蠕动增加。镇痛镇静（A项）、瞳孔缩小（B项，针尖样瞳孔）、镇咳（C项）、呼吸抑制（D项）均为吗啡的典型作用，其中呼吸抑制是其致死的主要原因"},{"q":"患者，男，20岁，咳嗽、咳痰3日，加重1日来院，诊断为呼吸道感染，选用阿莫西林治疗，其抗菌作用机制是","o":["影响细菌叶酸代谢","改变胞质膜的通透性","抑制细菌蛋白质的合成","抑制细菌细胞壁的合成","影响核酸代谢"],"a":3,"e":"阿莫西林为β-内酰胺类抗生素，与青霉素结合蛋白结合，抑制肽聚糖交联，阻碍细菌细胞壁合成，使细菌膨胀破裂死亡，属繁殖期杀菌药。影响叶酸代谢（A项）为磺胺类机制；改变胞质膜通透性（B项）为多黏菌素机制；抑制蛋白质合成（C项）为氨基糖苷类、大环内酯类机制；影响核酸代谢（E项）为喹诺酮类机制"},{"q":"患者，男，68岁，有胃溃疡病史30余年。近日复发，医生给予M受体阻断剂进行治疗。能选择性阻断胃壁细胞上的M1胆碱受体、抑制胃酸分泌，尚有胃肠道解痉作用的药物是","o":["阿托品","哌仑西平","后马托品","东莨菪碱","异丙托溴铵"],"a":1,"e":"哌仑西平为选择性M1胆碱受体阻断药，可抑制胃壁细胞胃酸分泌，并有胃肠道解痉作用，用于消化性溃疡。阿托品、后马托品、东莨菪碱（A、C、D项）为非选择性M受体阻断药，抑酸作用弱且不良反应多；异丙托溴铵（E项）主要吸入用于平喘，不用于溃疡治疗"},{"q":"患者，女，23岁。因为智齿经常发炎，医生建议拔除。拔牙之前医生先给予局麻药，为了延长局麻药的局麻作用时间和减少不良反应，可加用","o":["肾上腺素","去甲肾上腺素","异丙肾上腺素","麻黄碱","多巴胺"],"a":0,"e":"肾上腺素收缩局部血管，延缓局麻药吸收，延长麻醉时间并减少出血和全身中毒，是局麻药常用的配伍添加剂。去甲肾上腺素（B项）收缩血管过强、易致组织缺血坏死；异丙肾上腺素（C项）扩张血管，加快吸收；麻黄碱（D项）作用温和但升高血压明显；多巴胺（E项）为升压药，均不作局麻配伍首选"},{"q":"患者，女，46岁，近期出现头痛、头晕，血压升高。查体：BP 165/90mmHg，P 140次/min。按医嘱服用降压药2周后，出现颜面潮红、头疼、腹胀及便秘，该患者最可能使用的降压药是","o":["氢氯噻嗪","维拉帕米","缬沙坦","普萘洛尔","卡托普利"],"a":1,"e":"维拉帕米为非二氢吡啶类钙拮抗药，扩张血管可引起颜面潮红、头痛，同时抑制胃肠平滑肌蠕动导致腹胀、便秘，符合该患者表现。氢氯噻嗪（A项）主要致电解质紊乱；缬沙坦（C项）、卡托普利（E项）常见干咳或高血钾；普萘洛尔（D项）可致心动过缓、支气管痉挛，均不以便秘为特征"},{"q":"患者，女，22岁，居住于东北，受寒后手指会突然变白、局部发凉、麻木，有针刺感，持续几分钟后皮肤会变潮红，饮用热饮后发作减缓。诊断为雷诺病，该患者可服用的治疗药物是","o":["地塞米松","维生素E","维拉帕米","硝苯地平","氟桂利嗪"],"a":3,"e":"硝苯地平为二氢吡啶类钙拮抗药，扩张外周血管和指端小动脉，改善肢端血液循环，是雷诺病首选。地塞米松（A项）为糖皮质激素，不用于雷诺病；维生素E（B项）无扩血管作用；维拉帕米（C项）对血管选择性弱、更抑制心脏；氟桂利嗪（E项）主要用于脑血管痉挛和前庭症状，均非首选"},{"q":"患者，女，患有糖尿病合并肺浸润性肺结核，以甲苯磺丁脲控制血糖，以利福平、链霉素控制结核病。服用抗结核药物2个月后，发现糖尿病加重，而且出现肝功能损害，其原因是","o":["患者感染了肝炎","链霉素损害了肝","甲苯磺丁脲有毒性","利福平诱导肝药酶","出现了耐药性"],"a":3,"e":"利福平是强肝药酶诱导剂，加速甲苯磺丁脲等降糖药的代谢灭活，使其血药浓度下降、降糖作用减弱，导致糖尿病加重，并可引发肝损害。链霉素（B项）主要损害听神经和肾；甲苯磺丁脲（C项）本身无肝毒性蓄积问题；耐药性（E项）不能解释血糖突然升高与肝损害并存"},{"q":"患者，男，48岁，感冒发热2天，长期工作压力大，饮食不规律，有胃溃疡病史，宜选用下列哪种解热药物","o":["阿司匹林","吲哚美辛","吡罗昔康","对乙酰氨基酚","布洛芬"],"a":3,"e":"对乙酰氨基酚通过抑制中枢前列腺素合成发挥解热镇痛作用，对胃黏膜刺激小，不抑制外周血小板聚集，是胃溃疡患者较安全的退热选择。阿司匹林、吲哚美辛、吡罗昔康、布洛芬（A、B、C、E项）均抑制外周环氧化酶、减少胃黏膜前列腺素保护，可加重胃溃疡甚至诱发出血，故不宜"},{"q":"患者，男，85岁。诊断为前列腺癌，采取内分泌治疗。宜选用的药物是","o":["苯丙酸诺龙","丙酸睾酮","黄体酮","炔雌醇","氯米芬"],"a":3,"e":"炔雌醇为雌激素类，可抑制下丘脑-垂体-性腺轴，减少雄激素分泌并拮抗其作用，用于前列腺癌的内分泌治疗。苯丙酸诺龙、丙酸睾酮（A、B项）为雄激素类，会促进前列腺癌发展；黄体酮（C项）为孕激素，不用于此；氯米芬（E项）为促排卵药，亦不适用"},{"q":"患者，女，25岁，因“晚间发作性四肢抽搐、口吐白沫、短暂意识障碍”就诊。由睡眠不足和劳累诱发，查体正常，脑电图图显示发作性棘波、尖波，诊断为癫痫大发作。需要使用兼有镇静、催眠、抗惊厥和抗癫痫的药物，应选用下面哪种药物","o":["苯巴比妥","苯妥英钠","唑吡坦","水合氯醛","卡马西平"],"a":0,"e":"苯巴比妥为巴比妥类中效药，具有镇静、催眠、抗惊厥和抗癫痫作用，能增强GABA能抑制、抑制中枢，用于癫痫大发作及惊厥。苯妥英钠（B项）无镇静催眠作用；唑吡坦（C项）仅镇静催眠；水合氯醛（D项）用于催眠抗惊厥但无抗癫痫；卡马西平（E项）抗癫痫但不作催眠用"},{"q":"快速静脉注射给某个抗菌药物后，患者出现寒战、高热，面、头颈部出现红斑样皮疹，诊断为红人综合征。该药物是","o":["多黏菌素B","阿奇霉素","红霉素","万古霉素","林可霉素"],"a":3,"e":"快速静脉滴注万古霉素可致组胺释放，出现寒战、高热及面、颈、胸部红斑样皮疹，称红人综合征，故需慢速滴注。多黏菌素B（A项）主要肾毒性和神经毒性；阿奇霉素、红霉素（B、C项）为大环内酯类，无此反应；林可霉素（E项）主要有胃肠道反应和伪膜性肠炎"},{"q":"患者，男，25岁，因骑车摔伤右侧胫骨皮肤，伤口长约6cm。外伤清创需要局麻，为减少局麻药吸收、延长局麻药作用时间，常用方法是","o":["增加局麻药溶液的用量","增加局麻药浓度","调节药物溶液pH至微碱性","加入少量肾上腺素","注射麻黄碱"],"a":3,"e":"肾上腺素收缩局部小动脉，减少局麻药吸收入血，从而延长局麻作用时间并降低全身毒性反应，是外伤清创局麻的常规配伍。增加用量或浓度（A、B项）会加大毒性；调pH至微碱性（C项）虽可加快起效但不延长作用；注射麻黄碱（E项）升压明显，不作局部配伍"},{"q":"患者，男，45岁。因患有胃消化性溃疡，长期服药治疗。近日出现勃起功能障碍，可引起男性阳痿的抗消化性溃疡药是","o":["氢氧化铝","西咪替丁","哌仑西平","米索前列醇","硫糖铝"],"a":1,"e":"西咪替丁具有抗雄激素作用，可抑制睾酮代谢、升高催乳素，长期应用可引起男性乳房发育、阳痿及性欲减退。氢氧化铝、硫糖铝（A、E项）为黏膜保护或抗酸药，无此作用；哌仑西平（C项）为M1阻断药；米索前列醇（D项）为前列腺素类，主要致腹泻和子宫收缩，均不引起阳痿"},{"q":"患者，男，65岁，患高血压性心脏病数年，有时因激动或过劳而发生心绞痛，最初经休息后尚可自行缓解，近3天心绞痛加重并伴有心律失常，此时合理的治疗方案是","o":["普萘洛尔+硝苯地平","硝苯地平+硝酸甘油","硝酸甘油+硝酸异山梨酯","维拉帕米+地尔硫䓬","硝酸甘油+普萘洛尔"],"a":4,"e":"硝酸甘油扩张静脉与冠脉、降低前负荷，普萘洛尔阻断β受体、减慢心率并降低心肌耗氧，两者联用既增强抗心绞痛效果，又各自抵消心率加快等不利影响，适合心绞痛伴心律失常。普萘洛尔与硝苯地平（A项）虽也可用，但钙拮抗药反射性加快心率不利于心律失常；维拉帕米与地尔硫䓬（D项）合用抑制心脏，属禁忌"},{"q":"一位非霍奇金淋巴瘤患者正在接受联合化疗方案，主要有环磷酰胺、多柔比星、长春碱、地塞米松和甲氨蝶呤。以上药物中无明显骨髓抑制的是","o":["环磷酰胺","多柔比星","长春碱","地塞米松","甲氨蝶呤"],"a":3,"e":"地塞米松为糖皮质激素，无明显骨髓抑制作用，反而可刺激骨髓造血，常用于化疗止吐及淋巴瘤治疗。环磷酰胺（A项）为烷化剂、多柔比星（B项）为蒽环类、甲氨蝶呤（E项）为抗叶酸药，均明显抑制骨髓；长春碱（C项）主要神经毒性但也有骨髓抑制，故地塞米松最符合"},{"q":"患者，男，40岁，诊断为梅毒感染，治疗药物首选","o":["四环素","红霉素","庆大霉素","氨苄西林","青霉素G"],"a":4,"e":"青霉素G对梅毒螺旋体高度敏感，是各期梅毒的首选药物，杀菌彻底。四环素、红霉素（A、B项）为抑菌药，仅用于青霉素过敏者，疗效较差；庆大霉素（C项）为氨基糖苷类，对梅毒螺旋体无效；氨苄西林（D项）虽属青霉素类，但梅毒治疗首选仍是青霉素G"},{"q":"患者，男，44岁，上腹部疼痛急诊入院，超声显示胆囊多发结石，此时患者止痛应选用","o":["可待因＋美沙酮","哌替啶＋阿托品","吗啡＋纳洛酮","二氢埃托啡＋吗啡","阿司匹林＋哌替啶"],"a":1,"e":"哌替啶为阿片类镇痛药，可有效缓解胆绞痛，但会引起Oddi括约肌痉挛；配伍阿托品松弛平滑肌、解除痉挛，可增强止痛并减轻不良反应。吗啡（C项）同样收缩Oddi括约肌，单用加重绞痛；可待因、二氢埃托啡（A、D项）镇痛较弱或配伍不当；阿司匹林（E项）对内脏绞痛无效"},{"q":"患者，女，39岁，长期伏案工作，睡眠差，近1个月出现旋转性头晕，伴有恶心、呕吐、耳鸣等症状，头部有麻木感和持续胀痛，诊断为脑血管痉挛，该患者宜服用的药物是","o":["硝苯地平","地尔硫䓬","维拉帕米","氨氯地平","氟桂利嗪"],"a":4,"e":"氟桂利嗪为钙通道阻滞药，能透过血脑屏障，抑制钙离子内流、扩张脑血管并缓解血管痉挛，适用于脑血管痉挛、眩晕及偏头痛预防。硝苯地平、氨氯地平（A、D项）主要扩张外周血管降压；地尔硫䓬、维拉帕米（B、C项）非二氢吡啶类，对脑血管作用弱且抑制心脏，均非首选"},{"q":"患者，男，45岁，电工。在一次工作中不慎被电击昏迷，并出现心搏骤停。可用于急救的药物是","o":["去甲肾上腺素","肾上腺素","麻黄碱","多巴胺","多巴酚丁胺"],"a":1,"e":"肾上腺素激动β1受体，增强心肌收缩力、加快心率并改善心脏传导，是心搏骤停心肺复苏的首选药物，可恢复自主循环。去甲肾上腺素（A项）主要用于休克升压；麻黄碱（C项）作用温和、用于轻症；多巴胺（D项）用于休克；多巴酚丁胺（E项）为强心药，均非心搏骤停首选"},{"q":"患者，女，58岁。出现腹痛、高热、寒战、黄疸症状，确诊急性胆囊炎。治疗药物选择氨苄西林，其抗菌作用机制为","o":["改变胞浆膜的通透性","抑制细菌DNA的复制","抑制细菌叶酸的合成","抑制细菌蛋白质的合成","抑制细菌细胞壁的合成"],"a":4,"e":"氨苄西林为β-内酰胺类抗生素，与青霉素结合蛋白结合，抑制肽聚糖交联，阻碍细菌细胞壁合成，属繁殖期杀菌药。改变胞浆膜通透性（A项）为多黏菌素机制；抑制DNA复制（B项）为喹诺酮类；抑制叶酸合成（C项）为磺胺类；抑制蛋白质合成（D项）为氨基糖苷类、四环素类机制"},{"q":"患者，男，56岁，因“上腹痛、恶心”入院。血常规提示大细胞高色素性贫血，胃镜检查患者有“慢性萎缩性胃炎”，贫血原因推测可能是由于缺乏","o":["维生素C","维生素K","维生素A","转铁蛋白","内因子"],"a":4,"e":"慢性萎缩性胃炎时胃壁细胞受损，内因子分泌减少，维生素B12吸收障碍，导致巨幼细胞性贫血，即大细胞高色素性贫血。维生素C、A、K（A、B、C项）缺乏不引起此贫血；转铁蛋白（D项）参与铁运输，其缺乏或铁缺乏导致小细胞低色素性贫血，与大细胞贫血不符"},{"q":"患者，男，58岁。近几个月来感觉四肢无力，下肢水肿，尿中泡沫增多，遂去医院就诊。实验室检查：尿蛋白50mg/dl，血浆蛋白25g/L，总胆固醇8、46mmol/L，甘油三酯4、30mmol/L。结合其他的检查，诊断为肾病综合征。除采用氢氯噻嗪进行利尿消肿、卡托普利减少尿蛋白外，该患者最主要应进行抗免疫与抗炎治疗，宜选用的药物是","o":["泼尼松","阿司匹林","二甲双胍","丙硫氧嘧啶","丙酸睾酮"],"a":0,"e":"泼尼松为糖皮质激素，具有强大抗炎和免疫抑制作用，可抑制免疫复合物形成与炎症反应、减少蛋白尿，是肾病综合征首选的抗免疫抗炎药。阿司匹林（B项）为解热镇痛抗炎药，无免疫抑制；二甲双胍（C项）为降糖药；丙硫氧嘧啶（D项）抗甲状腺；丙酸睾酮（E项）为雄激素，均不适用"},{"q":"患者，男，18岁，由于高考压力大，近日出现食欲缺乏、恶心、反酸、进食后上腹部疼痛加重的症状。给予硫糖铝治疗，其作用机制是","o":["中和胃酸","抑制胃酸分泌","保护胃肠黏膜","抗幽门螺杆菌","促进胃肠动力"],"a":2,"e":"硫糖铝在酸性环境中解离为硫酸蔗糖复合阴离子，与溃疡面带正电的蛋白质结合形成保护膜，隔绝胃酸和胃蛋白酶，促进溃疡愈合，属黏膜保护药。中和胃酸（A项）为抗酸药作用；抑制胃酸分泌（B项）为H2阻断药或PPI；抗幽门螺杆菌（D项）需抗生素；促进动力（E项）为促胃肠动力药，均非硫糖铝机制"},{"q":"患者，男，30岁，患有胃消化性溃疡5年。近日由于工作压力大病情复发。给予奥美拉唑联合枸橼酸铋钾胶囊治疗。下列哪项不是枸橼酸铋钾治疗溃疡病的作用","o":["中和胃酸","保护胃黏膜","促进溃疡愈合","对幽门螺杆菌有抑制作用","抑制胃蛋白酶活性"],"a":0,"e":"枸橼酸铋钾在酸性环境下形成胶体沉淀，覆盖溃疡面保护胃黏膜，促进溃疡愈合，并能抑制胃蛋白酶活性、抑制幽门螺杆菌，但不中和胃酸。保护黏膜、促进愈合、抑制幽门螺杆菌、抑制胃蛋白酶活性分属B～E项作用，中和胃酸（A项）并非其机制，故为错误描述"},{"q":"患儿，男，10岁，戴眼镜1个月，莫名出现眼睛疼痛、头晕恶心，经脑CT、核磁共振检查未找到原因。眼部检查裸眼视力：两只眼均为0.4，原镜视力：两只眼均为0.8，原镜度数：右眼 -2.00D，左眼 -2.25D，验光时发现调节功能异常。为进一步明确该患者病情和治疗，宜使用的药物是","o":["后马托品","托吡卡胺","阿托品","尤卡托品","环喷托酯"],"a":2,"e":"阿托品阻断M受体，使睫状肌麻痹、调节麻痹，可准确测定屈光不正度数，是儿童验光散瞳的常用药，尤其适用于调节功能异常者。后马托品、托吡卡胺（A、B项）作用时间短，调节麻痹不充分；尤卡托品、环喷托酯（D、E项）亦为短效散瞳药，均不如阿托品可靠"},{"q":"患者，男，37岁，诊断为梅毒感染。注射药物10小时后，症状突然加剧，表现为寒战、发热、头痛、咽痛、肌痛、全身不适。查体：体温39.2℃，脉搏120次/min。患者出现此种情况，可能与注射下列哪种药物有关","o":["氯霉素","四环素","多西环素","罗红霉素","青霉素"],"a":4,"e":"青霉素治疗梅毒时，大量螺旋体被杀死释放毒素，引起寒战、发热、头痛、肌痛等赫氏反应，多在注射后数小时发生。氯霉素、四环素、多西环素、罗红霉素（A～D项）为抑菌药，杀菌作用弱，一般不引起大量菌体崩解释毒，故本反应与青霉素相关"},{"q":"患者，男，50岁，全身大面积烧伤，给予创面清创植皮术治疗，手术后出现黄绿色分泌物，采集分泌物作细菌培养，结果显示为铜绿假单胞菌感染。宜选用外用药物","o":["磺胺嘧啶","磺胺嘧啶银","氧氟沙星","呋喃唑酮","头孢氨苄"],"a":1,"e":"磺胺嘧啶银兼具磺胺类抗菌与银离子收敛、促进创面愈合作用，对铜绿假单胞菌有效，是烧伤创面感染的常用外用药。磺胺嘧啶（A项）外用刺激性大；氧氟沙星（C项）外用制剂少用于大面积烧伤；呋喃唑酮（D项）主要用于肠道；头孢氨苄（E项）为口服一代头孢，均非烧伤外用首选"},{"q":"患者，男，25岁。寒战、高热、胸痛、咳嗽、咳铁锈样痰，胸透显示右上肺有片状致密阴影，诊断为大叶性肺炎，首选的治疗药物为","o":["庆大霉素","青霉素G","红霉素","氯霉素","四环素"],"a":1,"e":"大叶性肺炎多由肺炎链球菌引起，青霉素G对肺炎链球菌高度敏感，是首选药物，可迅速控制感染。庆大霉素（A项）为氨基糖苷类，对肺炎链球菌作用差；红霉素（C项）主要用于支原体、军团菌；氯霉素（D项）毒性大、不作首选；四环素（E项）耐药率高，均非首选"},{"q":"患者，男，46岁，主诉手指以及脚底麻木入院。4周前，患者诊断为急性淋巴细胞白血病并进行了化疗药物治疗。体格检查显示跟腱反射消失和深部肌腱反射抑制。以下哪种药物最有可能造成该不良反应","o":["环磷酰胺","多柔比星","长春新碱","泼尼松","巯嘌呤"],"a":2,"e":"长春新碱为长春碱类抗肿瘤药，主要不良反应是外周神经毒性，可致肢体麻木、腱反射消失、肌无力等，与该患者表现相符。环磷酰胺（A项）主要骨髓抑制和出血性膀胱炎；多柔比星（B项）心脏毒性；泼尼松（D项）无周围神经毒性；巯嘌呤（E项）主要骨髓抑制，均不符"},{"q":"患儿，男，2岁。因发热及频繁腹泻在乡村医院诊治。处方为庆大霉素注射液120mg，5%碳酸氢钠注射液40ml，5%葡萄糖注射液120ml，静脉滴注1次/日，共3天。用药后第2天患儿仍发高烧，腹泻。第3日患儿尿液呈酱油色并尿量减少。尿常规检查：尿蛋白（＋＋），红细胞（＋），潜血（＋＋＋）。下列说法中不正确的是","o":["庆大霉素具有耳毒性和肾毒性，不应用于幼儿","庆大霉素用量过大导致肾毒性","改用大环内酯类抗菌药物可避免肾毒性","碳酸氢钠可碱化尿液，提高庆大霉素的抗菌疗效","碳酸氢钠可碱化尿液，降低庆大霉素肾毒性"],"a":4,"e":"碳酸氢钠碱化尿液并不能降低庆大霉素的肾毒性，该说法不成立；庆大霉素肾毒性源于其在肾皮质蓄积损伤肾小管，处理关键是停药。庆大霉素有耳、肾毒性，幼儿不宜用（A项对）；120mg剂量过大可致肾毒性（B项对）；改用大环内酯类可避开肾毒性（C项对）；碱性环境可增强其抗菌活性（D项对）"},{"q":"患者，男，50岁。高血压病史20年，伴有支气管哮喘病史20年以上。近日哮喘发作，主诉气短、胸闷，伴有咳嗽、咳痰，无咯血，查体血压168/108mmHg。下列哪个药物不宜使用","o":["硝苯地平","普萘洛尔","氯沙坦","氨氯地平","哌唑嗪"],"a":1,"e":"普萘洛尔为非选择性β受体阻断药，阻断支气管β2受体，可诱发支气管平滑肌收缩、加重哮喘发作，故哮喘患者禁用。硝苯地平、氨氯地平（A、D项）为钙拮抗药，氯沙坦（C项）为ARB，哌唑嗪（E项）为α受体阻断药，均不收缩支气管，可用于高血压合并哮喘"},{"q":"患者，女，25岁，情绪不稳定2年。时而易激惹、睡眠增加、注意力不集中、有自杀观念和行为；时而心境高涨、思潮汹涌、言语增多、有显著的自我感觉良好、轻度挥霍、社交活动增多、睡眠需要减少。诊断为双向情感障碍，给予抗躁狂症药和抗癫痫药、以及合并抗精神病药物治疗，其中最需要进行血药浓度监测的药物是","o":["碳酸锂","氯丙嗪","舒必利","氯普噻吨","卡马西平"],"a":0,"e":"碳酸锂治疗窗窄，有效血药浓度与中毒浓度接近，过量可致共济失调、意识障碍甚至危及生命，且需达到有效浓度才起效，故必须监测血药浓度。氯丙嗪、舒必利、氯普噻吨（B、C、D项）为抗精神病药；卡马西平（E项）为抗癫痫药，虽也可监测，但本题以碳酸锂最典型"},{"q":"患者，女，36岁，诊断为家族性混合型高脂蛋白血症，血总胆固醇水平为10.7mmol/L（正常值为2.9～6.0mmol/L），甘油三酯为5.3mmol/L（正常值<1.7mmol/L），医生建议服用洛伐他汀和吉非贝齐，为了预防肌肉不良反应的发生，需要定期监测的指标是","o":["HMG-CoA还原酶","胆固醇酰基转移酶","碱性磷酸酶","环氧酶","肌酸磷酸激酶"],"a":4,"e":"他汀类与贝特类合用可增加肌病和横纹肌溶解风险，需定期监测肌酸磷酸激酶（CK），若显著升高应警惕肌损伤。HMG-CoA还原酶（A项）是他汀作用靶点而非监测指标；胆固醇酰基转移酶（B项）、碱性磷酸酶（C项，反映胆汁淤积）、环氧酶（D项，与阿司匹林相关）均非肌毒性监测项目"},{"q":"患者，女，24岁，表现为面部表情肌无力，眼睑闭合力弱，吹气无力，说话吐词不清，左右交替出现眼睑下垂、眼球运动障碍。诊断为重症肌无力，宜选用的治疗药物是","o":["毛果芸香碱","东莨菪碱","阿托品","新斯的明","解磷定"],"a":3,"e":"新斯的明为胆碱酯酶抑制剂，抑制乙酰胆碱水解、增加神经肌肉接头处乙酰胆碱浓度，并直接激动N2受体，显著改善重症肌无力的肌无力症状。毛果芸香碱（A项）为M激动药，主要缩瞳；东莨菪碱、阿托品（B、C项）为M阻断药，会加重病情；解磷定（E项）为胆碱酯酶复活药，用于有机磷中毒"},{"q":"患者，男，53岁，因胸痛就诊。心电图示胸前导联ST段明显抬高，心脏彩超示：左室内附壁血栓。遂给予华法林抗凝，该药物的作用机制涉及对凝血因子活化过程的抑制，下列不受华法林影响的凝血因子是","o":["凝血因子Ⅶ","凝血因子Ⅱ","凝血因子Ⅹ","凝血因子Ⅸ","凝血因子Ⅺ"],"a":4,"e":"华法林通过抑制维生素K环氧化物还原酶，阻断维生素K依赖凝血因子的活化，受影响的是因子Ⅱ、Ⅶ、Ⅸ、Ⅹ；因子Ⅺ不依赖维生素K，故不受华法林影响。凝血因子Ⅶ（A项）、Ⅱ（B项）、Ⅹ（C项）、Ⅸ（D项）均为维生素K依赖因子，可被华法林抑制，唯E项例外"},{"q":"患者，女，28岁。有支气管哮喘病史20余年。近日病情复发，出现呼吸困难、喘息、咳嗽、胸闷等症状。医生给予某种β受体强选择性拟肾上腺素药物，通过激动支气管平滑肌上β2受体迅速控制哮喘症状，则该药物可能是","o":["肾上腺素","异丙肾上腺素","沙丁胺醇","多巴酚丁胺","色甘酸钠"],"a":2,"e":"沙丁胺醇对β2受体有高度选择性，激动支气管平滑肌β2受体使支气管迅速舒张，用于哮喘急性发作控制。肾上腺素、异丙肾上腺素（A、B项）对β1、β2无选择性，心脏兴奋作用明显；多巴酚丁胺（D项）主要激动β1；色甘酸钠（E项）为肥大细胞膜稳定药，仅用于预防、不能快速平喘"},{"q":"患者，女，29岁。半年前确诊为甲亢，采用药物治疗，近日出现乏力、咽痛、牙龈肿痛、发热等症状，体温37、1℃，血常规：白细胞计数2.3×109/L［正常（4～10）×109/L］，中性粒细胞绝对值1.0×109/L（正常＞1.5×109/L），血红蛋白和血小板正常。该患者可能服用的药物是","o":["丙硫氧嘧啶","大剂量碘","小剂量碘","普萘洛尔","左甲状腺素"],"a":0,"e":"丙硫氧嘧啶为硫脲类抗甲状腺药，严重不良反应是粒细胞缺乏，表现为发热、咽痛、感染等，该患者白细胞及中性粒细胞明显降低，符合此反应。大剂量碘（B项）主要用于术前准备；小剂量碘（C项）用于单纯甲状腺肿；普萘洛尔（D项）控制症状；左甲状腺素（E项）补充激素，均不引起粒缺"},{"q":"患者，男，25岁，主诉腹痛、腹泻、大便黏稠带血12小时入院，粪便检查发现该患者有阿米巴及贾第鞭毛虫感染，可选用以下哪种药物进行治疗","o":["青蒿琥酯","甲硝唑","二氯尼特","吡喹酮","氯喹"],"a":1,"e":"甲硝唑对阿米巴原虫和贾第鞭毛虫均有强大杀灭作用，是肠阿米巴病、阿米巴痢疾及贾第虫病的首选药。青蒿琥酯（A项）抗疟；二氯尼特（C项）主要用于阿米巴无症状带虫者；吡喹酮（D项）抗血吸虫和绦虫；氯喹（E项）抗疟并用于肠外阿米巴，但对贾第鞭毛虫无效"},{"q":"某患者用辛伐他汀治疗高胆固醇血症，但用到最大量时其血浆胆固醇水平仍然高于要降到的目的水平，如果加用考来烯胺，下列说法正确的是","o":["两者合用会引起VLDL升高","两者合用较单用任何一种降胆固醇效果差","考来烯胺抑制辛伐他汀的肠道吸收","辛伐他汀延长考来烯胺的代谢失活","辛伐他汀代谢延长"],"a":2,"e":"考来烯胺为胆汁酸螯合剂，在肠道内也可吸附辛伐他汀等药物，抑制其吸收，降低他汀的血药浓度和疗效，故两药应间隔服用。两药合用并不引起VLDL升高（A项错），降胆固醇作用应强于单用（B项错）；辛伐他汀不延长考来烯胺代谢（D项错），也不改变自身代谢（E项错）"},{"q":"患者，女，55岁，诊断为卵巢癌，采用紫杉醇、顺铂和环磷酰胺的联合治疗。以下哪种药物可以联合使用以减轻环磷酰胺带来的不良反应","o":["促红细胞生成素","四氢叶酸","美司钠","波尼松","维生素K"],"a":2,"e":"美司钠可与环磷酰胺代谢产物丙烯醛结合，形成无毒化合物随尿排出，从而预防出血性膀胱炎，减轻环磷酰胺的泌尿系统毒性。促红细胞生成素（A项）用于贫血；四氢叶酸（B项）解救甲氨蝶呤；波尼松（D项）为糖皮质激素；维生素K（E项）用于华法林过量，均非针对环磷酰胺"},{"q":"患者，女，56岁，有高血压病史10年，今日因劳累出现心悸、气促等症状，临床诊断为高血压心脏病及心功能衰竭，医生应用毛花苷C治疗后出现频发快速性心律失常。应选择的最佳治疗药物是","o":["奎尼丁","胺碘酮","普罗帕酮","苯妥英钠","阿托品"],"a":3,"e":"苯妥英钠能与强心苷竞争Na+-K+-ATP酶，抑制洋地黄中毒所致的快速性心律失常，是洋地黄中毒室性心律失常的首选。奎尼丁、普罗帕酮（A、C项）可加重传导抑制；胺碘酮（B项）延长QT、作用复杂；阿托品（E项）仅用于缓慢型心律失常，对快速型无效"},{"q":"患者，女，41岁。因严重肺部感染出现休克症状，尿量每小时仅为15ml，此时应禁用","o":["山莨菪碱","异丙肾上腺素","多巴胺","阿托品","去甲肾上腺素"],"a":4,"e":"去甲肾上腺素强烈收缩血管，进一步减少肾血流量和尿量，加重休克时的肾缺血，故休克伴少尿时禁用。山莨菪碱、阿托品（A、D项）解除微血管痉挛，改善微循环；异丙肾上腺素（B项）兴奋心脏、扩张血管；多巴胺（C项）在休克时扩张肾血管、增加尿量，均可用于休克"},{"q":"患者，女，68岁，因类风湿性关节炎长期服用非甾体类抗炎药布洛芬，近来发生胃部疼痛，餐后腹胀，内镜检查显示胃溃疡，下列药物中最适宜的是","o":["西咪替丁","碳酸氢钠","奥美拉唑","米索前列醇","硫糖铝"],"a":3,"e":"米索前列醇为前列腺素E1衍生物，抑制胃酸分泌并增加胃黏膜血流量和黏液分泌，能预防和治疗NSAID所致胃溃疡，是针对病因的优选。西咪替丁（A项）、奥美拉唑（C项）虽可抑酸，但对NSAID溃疡的预防以米索前列醇更具针对性；碳酸氢钠（B项）、硫糖铝（E项）作用较弱或对症"},{"q":"患者，男，58岁，因“突发晕厥30分钟”急诊入院。既往有高血压病史10余年。心电图提示急性广泛前壁心肌梗死：V1～V4呈QS型，V5～V6呈qR型，V1～V6 ST段呈弓背型抬高0.05～0.3mV。急转ICU途中又发生室性心动过速。下列可作为首选治疗其心律失常的药物是","o":["奎尼丁","利多卡因","维拉帕米","普罗帕酮","地高辛"],"a":1,"e":"利多卡因为IB类抗心律失常药，抑制心室肌钠内流、降低自律性并改善传导，对室性心律失常疗效好，是急性心肌梗死并发室性心动过速的首选。奎尼丁（A项）为IA类，不良反应多；维拉帕米（C项）为钙拮抗药，主要用于室上性；普罗帕酮（D项）和地高辛（E项）均非急性心梗室速首选"},{"q":"患者，女，30岁，停经45天，1天前少量阴道流血，无腹痛，未引起重视。经过1天，阴道流血无缓解，但量亦未增多，无组织块排出，来院就诊。经检查诊断为先兆流产，建议给予药物","o":["黄体酮","丙酸睾酮","己烯雌酚","炔雌醇","复方炔诺酮"],"a":0,"e":"黄体酮为孕激素，可补充黄体功能不足、抑制子宫收缩、维持妊娠，用于先兆流产的保胎治疗。丙酸睾酮（B项）为雄激素，可致胎儿男性化；己烯雌酚、炔雌醇（C、D项）为雌激素，不用于保胎；复方炔诺酮（E项）为避孕药，均不适用"},{"q":"患者，男，59岁，患有风湿性心脏病，伴发房颤，用地高辛治疗后，房颤变成正常心律，最可能的作用机理是","o":["缩短心肌不应期","降低心房肌最大舒张电位","降低浦氏纤维的自律性","降低房室结的传导速度","缩短心肌收缩速率"],"a":3,"e":"地高辛兴奋迷走神经、抑制Na+-K+-ATP酶，可减慢房室结传导并延长其有效不应期，使心室率减慢、心律趋于规整，这是其治疗房颤的主要机制。缩短心肌不应期（A项）会促发心律失常；降低最大舒张电位（B项）与自律性关系不直接；降低浦氏纤维自律性（C项）主要抗室性心律失常；缩短收缩速率（E项）非其抗心律失常机制"},{"q":"患者，男，62岁。患高血压多年，体检心电图显示三度房室传导阻滞，应禁用的降压药是","o":["氯沙坦","卡托普利","硝苯地平","普萘洛尔","氢氯噻嗪"],"a":3,"e":"普萘洛尔阻断β受体，抑制房室结传导并减慢心率，三度房室传导阻滞患者使用可加重传导阻滞、导致心室率过慢甚至停搏，故禁用。氯沙坦、卡托普利（A、B项）为RAAS抑制剂，硝苯地平（C项）为钙拮抗药，氢氯噻嗪（E项）为利尿剂，均不抑制房室传导"},{"q":"患者，男，52岁，因慢性胃炎急性发作入院。主诉反酸、胃灼热症状明显，给予氢氧化铝片治疗。护士在向患者嘱咐服药注意事项时，错误的是","o":["多运动以防便秘","不宜与四环素同时服用","宜在饭前或睡前服用","宜整片吞服","可能干扰地高辛、华法林等药物的疗效"],"a":3,"e":"氢氧化铝片应嚼碎后服用，使药物充分分散以中和胃酸，整片吞服不利于发挥作用，故该嘱咐错误。多运动防便秘（A项）正确，因铝剂易致便秘；不宜与四环素同服（B项）正确，因可形成络合物影响吸收；饭前或睡前服（C项）正确；可干扰地高辛、华法林吸收（E项）正确"},{"q":"患者，女，52岁。诊断为胶质母细胞瘤。手术后接受放疗联合化疗药物治疗，其中包括烷化剂类环磷酰胺。以下哪项特征是环磷酰胺能用于胶质母细胞瘤化疗药物的主要原因","o":["只杀伤胶质母细胞瘤细胞","通过血脑屏障入脑达到有效治疗浓度","无明显神经毒性","半衰期长","增强机体免疫"],"a":1,"e":"环磷酰胺脂溶性较好，能透过血脑屏障进入中枢神经系统，在脑组织达到有效治疗浓度，故可用于胶质母细胞瘤化疗。它并非只杀伤肿瘤细胞（A项错），也有神经毒性等（C项错）；半衰期长（D项）和增强免疫（E项）均非其用于脑瘤的关键原因"},{"q":"患者，男，面部红润结节，皮肤感觉轻微麻木，背、腰部位出现大面积褐色大小不等疹子高出皮肤，无痒无痛，双手及小腿有轻触痛和闭汗3个月。就诊后病理组织学检查：背部皮损组织液查菌AFB阳性。诊断：多菌型（LL）麻风病。宜选用下列哪个药物治疗","o":["对乙酰氨基酚","氨苯砜","异烟肼","乙胺丁醇","对氨基水杨酸"],"a":1,"e":"氨苯砜为砜类抗麻风药，抑制麻风分枝杆菌叶酸合成，是治疗各型麻风的首选药，多菌型需联合利福平、氯法齐明。对乙酰氨基酚（A项）为解热镇痛药；异烟肼、乙胺丁醇、对氨基水杨酸（C、D、E项）均为抗结核药，其中异烟肼对麻风杆菌作用弱，不作首选"},{"q":"患者，男，56岁，患慢性肝炎合并肝硬化。1小时前突感腹胀不适，继而呕鲜红色血，可采用的止血方式是","o":["去甲肾上腺素稀释后口服","肾上腺素肌内注射","肾上腺素皮下注射","肾上腺素静脉滴注","异丙肾上腺素气雾吸入"],"a":0,"e":"去甲肾上腺素稀释后口服，可作用于食管、胃黏膜血管α受体，使局部血管收缩而止血，用于上消化道出血，口服不易吸收、全身作用小。肾上腺素肌注、皮下、静滴（B、C、D项）全身作用强、升高血压，不适合；异丙肾上腺素气雾吸入（E项）扩张血管，不用于止血"},{"q":"患者，45岁，行肾脏移植术后使用他克莫司抑制免疫排异反应。以下哪种细胞是该药物的主要抑制靶点","o":["巨噬细胞","T细胞","自然杀伤细胞","树突状细胞","B细胞"],"a":1,"e":"他克莫司为钙调神经磷酸酶抑制剂，与FK506结合蛋白结合，抑制T细胞活化与白细胞介素-2产生，主要抑制T细胞介导的免疫反应，用于器官移植抗排异。巨噬细胞、NK细胞、树突状细胞（A、C、D项）非其主要靶点；B细胞（E项）介导体液免疫，亦非他克莫司主要作用对象"},{"q":"患者，男，被老鼠咬伤后出现高热、淋巴结肿痛和肺部炎症，临床诊断为鼠疫。下列哪种抗生素可以作为首选药使用","o":["氯霉素","青霉素","红霉素","庆大霉素","链霉素"],"a":4,"e":"链霉素为氨基糖苷类抗生素，对鼠疫耶尔森菌高度敏感，是治疗鼠疫的首选药，常与四环素或氯霉素合用。青霉素（B项）对鼠疫杆菌无效；红霉素（C项）为大环内酯类，疗效差；氯霉素（A项）、庆大霉素（D项）虽可用于鼠疫，但首选仍为链霉素"},{"q":"患者，男，50岁，鼻咽癌放射性治疗后，口干咽干，喝水没有缓解，可选用","o":["阿托品","新斯的明","毒扁豆碱","烟碱","毛果芸香碱"],"a":4,"e":"毛果芸香碱为M胆碱受体激动药，可刺激唾液腺、汗腺等外分泌腺分泌，缓解放疗后口干症状。阿托品（A项）为M阻断药，抑制腺体分泌、加重口干；新斯的明、毒扁豆碱（B、C项）为胆碱酯酶抑制剂，对唾液腺分泌作用弱且不良反应多；烟碱（D项）为N受体激动药，不适用"},{"q":"某中度肝硬化患者，男，54岁，应用某药物治疗其他疾病后出现了严重不良反应，经检测，该药物半衰期比正常增加了4倍，主要原因是","o":["由于肝功能障碍，抑制了肝糖原的合成","由于肝功能障碍，使得身体排泄能力下降","由于肝功能障碍，使得药物消化遇到障碍","由于肝功能障碍，使得药物代谢能力下降","由于肝功能障碍，使得药物吸收能力下降"],"a":3,"e":"肝脏是药物代谢的主要器官，肝硬化时肝细胞受损、肝药酶活性下降，药物代谢清除减慢，导致半衰期延长，故该患者半衰期增加源于代谢能力下降。肝糖原合成（A项）与药物半衰期无关；排泄能力（B项）主要指肾；消化（C项）和吸收（E项）障碍不改变已吸收药物的消除半衰期"},{"q":"患者，女，38岁，吸食海洛因3年，一旦停止吸食就会出现不安、焦虑、忽冷忽热、起鸡皮疙瘩、流泪、流涕、出汗、恶心、呕吐、腹痛及腹泻等症状，可用于脱毒治疗的药物是","o":["丁丙诺啡","吗啡","可待因","喷他佐辛","曲马多"],"a":0,"e":"丁丙诺啡为阿片受体部分激动药，可替代海洛因与μ受体结合，缓解戒断症状且依赖性和呼吸抑制较轻，用于阿片类依赖的脱毒治疗。吗啡、可待因（B、C项）本身为阿片类，易维持依赖；喷他佐辛（D项）为部分激动药但戒断治疗不首选；曲马多（E项）亦为阿片类镇痛药，不作脱毒用"},{"q":"患者，女，20岁。咳嗽半年，尤以早晨更显著，医生考虑为气道高反应性，使用布地奈德和孟鲁司特进行治疗。其中，孟鲁司特属于","o":["肥大细胞脱颗粒抑制剂","糖皮质激素类药物","白三烯受体拮抗剂","肾上腺素受体激动药","组胺H1受体阻断药"],"a":2,"e":"孟鲁司特为白三烯受体拮抗剂，选择性阻断半胱氨酰白三烯受体，抑制白三烯介导的气道炎症和痉挛，用于哮喘的长期控制。肥大细胞脱颗粒抑制剂（A项）如色甘酸钠；糖皮质激素（B项）如布地奈德；β受体激动药（D项）如沙丁胺醇；H1受体阻断药（E项）如氯雷他定，均非孟鲁司特类别"},{"q":"患者，男，40岁，患高血压。可分别单用利尿剂A和B进行治疗，达相同效应时A药剂量是50mg而B药是15mg。下述哪种说法正确","o":["B药疗效比A药差","B药效价强度比A药高","A药毒性比B药小","需要达最大效能时A药优于B药","A药作用持续时间比B药短"],"a":1,"e":"效价强度指达到相同效应所需的剂量，剂量越小效价强度越高。达相同效应时B药仅需15mg而A药需50mg，故B药效价强度高于A药。效价强度与疗效（A项）、毒性（C项）、持续时间（E项）无关；最大效能（D项）反映药物固有最大效应，不能由等效剂量推断A药更优"},{"q":"患者，男，34岁，口服敌敌畏30ml入院。经反复、大量注射阿托品后，原有症状消失，出现兴奋、心动过速、皮肤潮红、瞳孔极度扩大、视力模糊、排尿困难等症状。此时应该采用的治疗药物为","o":["加大阿托品剂量","新斯的明","毛果芸香碱","解磷定","烟碱"],"a":2,"e":"大量注射阿托品后出现兴奋、心动过速、皮肤潮红、瞳孔极度散大、排尿困难，为阿托品中毒表现，应停药并用毛果芸香碱等拟胆碱药拮抗其外周作用。加大阿托品剂量（A项）会加重中毒；新斯的明（B项）不易透过血脑屏障、对中枢症状无效；解磷定（D项）用于胆碱酯酶复活，对阿托品中毒无效；烟碱（E项）不适用"},{"q":"患者，男，40岁，1周前出现剧烈的刺激性干咳，无痰，并伴有胸痛，可选用下列哪个药物止咳、镇痛","o":["可待因","奈多罗米","异丙嗪","右美沙芬","盐酸那可汀"],"a":0,"e":"可待因为阿片类中枢性镇咳药，镇咳作用强，同时具有镇痛作用，适合剧烈干咳伴胸痛者。奈多罗米（B项）为肥大细胞膜稳定药，用于哮喘预防；异丙嗪（C项）为抗组胺药；右美沙芬、盐酸那可汀（D、E项）虽为镇咳药，但无镇痛作用，不能缓解胸痛"},{"q":"患儿，男，12岁。主诉反复发作性气喘1年，近10天发作频繁，除胸闷、喘息、咳嗽外，伴少量白黏痰。为减轻该患儿支气管黏膜水肿，应选用下列哪种药物","o":["异丙肾上腺素","肾上腺素","色甘酸钠","异丙基阿托品","氨茶碱"],"a":1,"e":"肾上腺素激动α受体收缩支气管黏膜血管、减轻充血水肿，并激动β2受体舒张支气管，缓解哮喘时的气道水肿与痉挛。异丙肾上腺素（A项）无α缩血管作用；色甘酸钠（C项）仅用于预防；异丙基阿托品（D项）为M阻断药，不减轻黏膜水肿；氨茶碱（E项）平喘但无缩血管消肿作用"},{"q":"患者，女，59岁，反复咳脓痰、咯血10余年。3天前，前述症状复发加重，每天咯血量在200ml以上。该患者宜使用的药物是","o":["垂体后叶素","麦角胺","前列腺素","利托君","硫酸镁"],"a":0,"e":"垂体后叶素含加压素，能强烈收缩肺小动脉、减少肺血流量，使肺血管压力下降而止血，是肺结核等所致大咯血的首选药。麦角胺（B项）主要用于偏头痛；前列腺素（C项）扩张血管；利托君（D项）为β2激动药、用于抑制宫缩；硫酸镁（E项）用于子痫和导泻，均不用于咯血"},{"q":"患者，男，60岁，慢性支气管炎病史10余年。1周前患感冒后，出现咳嗽、咳痰、咽喉疼痛和发热等症状。给予抗生素和祛痰药(N-乙酰半胱氨酸)联合治疗，该祛痰药的作用机制是","o":["抑制碱性糖蛋白合成","反射性增加呼吸道腺体分泌","使痰中黏蛋白多肽链中的-S-S-键断裂，降低痰黏度","裂解痰中黏多糖","抑制局部黏痰分泌"],"a":2,"e":"N-乙酰半胱氨酸分子中的巯基可与痰液黏蛋白的二硫键（-S-S-）反应，使其断裂，降低痰液黏稠度，使痰易于咳出。抑制碱性糖蛋白合成（A项）非其机制；反射性增加腺体分泌（B项）为氯化铵等作用；裂解黏多糖（D项）为溴己新机制；抑制黏痰分泌（E项）与之相反"},{"q":"患者，女，20岁，因学习压力过大，近2周出现入睡困难，无中途易醒及早醒，该患者适合服用下列哪种镇静催眠药物","o":["地西泮","异戊巴比妥","唑吡坦","水合氯醛","丁螺环酮"],"a":2,"e":"唑吡坦为新型非苯二氮䓬类催眠药，选择性激动GABA_A受体ω1亚型，起效快、作用时间短，主要缩短入睡潜伏期，适合入睡困难且无早醒者。地西泮（A项）半衰期长、易蓄积；异戊巴比妥、水合氯醛（B、D项）不良反应多；丁螺环酮（E项）为抗焦虑药，无催眠作用"},{"q":"患者，男，63岁，因胸骨后压榨性疼痛、舌下含服3片硝酸甘油无效拨打120求救。初步诊断为急性心肌梗死。测血压为110/70mmHg，心率为70次/min，伴偶发性期前收缩。经初步处理后，发现患者目前有严重的低血压（70/40mmHg），心功能减退，左室射血分数减少，伴尿少和精神恍惚。对该状态下患者的正确处理药物是","o":["阿替洛尔","地高辛","多巴胺","去甲肾上腺素","异丙肾上腺素"],"a":2,"e":"多巴胺在低血压、心功能减退时，可激动β1受体增强心肌收缩力，并于低剂量时激动多巴胺受体扩张肾血管、改善尿量，适合心源性休克伴低血压。去甲肾上腺素（D项）虽升压但强烈收缩血管、加重心脏后负荷；异丙肾上腺素（E项）易致心律失常；阿替洛尔（A项）抑制心肌；地高辛（B项）不适用急性心梗"},{"q":"患者，男，47岁，近1周每日清晨醒来时自觉心前区不适、胸骨后阵发性闷痛，遂来医院就诊，查心电图无异常，有哮喘病史，拟用抗心绞痛药物进行治疗，下列何种药物不宜选用","o":["普萘洛尔","硝苯地平","硝酸甘油","维拉帕米","硝酸异山梨酯"],"a":0,"e":"普萘洛尔为非选择性β受体阻断药，阻断支气管β2受体可诱发支气管痉挛、加重哮喘，故哮喘患者不宜选用。硝苯地平、维拉帕米（B、D项）为钙拮抗药，硝酸甘油、硝酸异山梨酯（C、E项）为硝酸酯类，均不收缩支气管，可用于伴哮喘的心绞痛"},{"q":"患者，男，57岁。因急性肾衰竭入院，除了给予常规的抗炎、激素、抗凝治疗外，医生还联合应用呋塞米和多巴胺治疗。应用多巴胺的作用是","o":["激动多巴胺受体，扩张肾血管","激动β1受体，兴奋心脏","激动β2受体，扩张血管","激动α1受体，收缩外周血管","中枢作用扩张血管"],"a":0,"e":"小剂量多巴胺激动肾血管D1受体，扩张肾动脉、增加肾血流量和肾小球滤过率，改善肾功能，故急性肾衰竭时联合呋塞米使用。激动β1兴奋心脏（B项）为较大剂量作用；激动β2扩血管（C项）非肾保护主要机制；激动α1收缩血管（D项）会减少肾血流；中枢扩血管（E项）不成立"},{"q":"患者，女，35岁，妊娠6周，患者自感疲惫、嗜睡、乏力，孕检血清铁蛋白＜12μg/L（正常值12～150μg/L），血红蛋白＜110g/L（正常值110～160g/L），需要的治疗药物是","o":["维生素B12","硫酸亚铁","叶酸","维生素C","右旋糖酐"],"a":1,"e":"孕妇血清铁蛋白和血红蛋白降低，为缺铁性贫血，需补充铁剂，硫酸亚铁为口服补铁首选，是合成血红蛋白的原料。维生素B12（A项）和叶酸（C项）用于巨幼细胞性贫血；维生素C（D项）可促进铁吸收但非补铁本身；右旋糖酐（E项）为血浆代用品，均不能纠正缺铁"},{"q":"患者，女，因下腹疼痛，且伴有阴道分泌异常，诊断为厌氧菌引起的盆腔炎，可使用下列哪类药物","o":["大环内酯类","氨基糖苷类","β-内酰胺类","林可霉素类","万古霉素类"],"a":3,"e":"林可霉素类（如克林霉素）对厌氧菌有强大抗菌活性，在骨、软组织及盆腔等组织浓度高，是厌氧菌感染常用药。大环内酯类（A项）主要覆盖需氧菌和非典型病原；氨基糖苷类（B项）对厌氧菌无效；β-内酰胺类（C项）部分对厌氧菌有效但非本题所指；万古霉素类（E项）主要针对革兰阳性球菌"},{"q":"患者，男，59岁，3天前无明显诱因出现低热，全身无力，在当地诊所按感冒治疗，疗效欠佳。1天前自觉右侧腰部和季肋区皮肤瘙痒、疼痛，呈跳动性的刺痛，疼痛部位不固定，无反射痛。继而局部皮肤出现大小不一的红斑，在红斑上出现簇集水疱。疱壁紧张，内容清亮透明。疱间皮肤颜色正常。于当地县医院诊断为“带状疱疹”。对于该患者的首选治疗药物是","o":["利巴韦林","干扰素","阿昔洛韦","拉米夫定","金刚烷胺"],"a":2,"e":"阿昔洛韦为嘌呤核苷类似物，在病毒感染细胞内被磷酸化，抑制病毒DNA聚合酶、阻断病毒DNA复制，是单纯疱疹和带状疱疹的首选抗病毒药。利巴韦林（A项）为广谱抗病毒药但非首选；干扰素（B项）用于乙肝等；拉米夫定（D项）用于乙肝、艾滋病；金刚烷胺（E项）用于甲型流感"},{"q":"患者，男，57岁，因声音沙哑就诊，查体正常，经喉镜检查诊断为声带息肉，行喉镜下切除术，最宜选用的麻醉药是","o":["普鲁卡因","罗哌卡因","丁卡因","丁哌卡因","可卡因"],"a":2,"e":"丁卡因为酯类局麻药，麻醉作用强、穿透力好，常用于黏膜表面麻醉，适合喉镜下行声带息肉切除的表面麻醉。普鲁卡因（A项）穿透力差、不适于表麻；罗哌卡因、丁哌卡因（B、D项）多用于浸润或阻滞麻醉；可卡因（E项）因成瘾性和毒性，现已少用"},{"q":"患者，男，34岁，皮肤大面积烧伤，现出现铜绿假单胞菌感染，可以选择的外用药物是","o":["磺胺嘧啶","磺胺嘧啶银","肾上腺皮质激素","呋喃唑酮","头孢氨苄"],"a":1,"e":"磺胺嘧啶银兼具抗菌与银离子作用，对铜绿假单胞菌有效，可促进烧伤创面愈合，是烧伤感染外用药首选。磺胺嘧啶（A项）外用刺激性大；肾上腺皮质激素（C项）抑制免疫、不利感染控制；呋喃唑酮（D项）用于肠道感染；头孢氨苄（E项）为口服药，均非烧伤外用"},{"q":"患者，男，46岁，半年来面部色素沉着、厌食、乏力，时有恶心呕吐，呼吸、心率正常，血压110/70mmHg。血皮质醇、24小时尿17-羟、17-酮类固醇和24小时尿游离皮质醇低于正常，血浆ACTH升高，低血钠、高血钾。应选用的治疗药是","o":["丙酸睾酮","泼尼松","胰岛素","呋塞米","美替拉酮"],"a":1,"e":"患者皮质醇及尿17-羟、17-酮降低而ACTH升高，伴色素沉着、低钠高钾，为慢性肾上腺皮质功能减退（艾迪生病），需补充糖皮质激素，泼尼松为首选。丙酸睾酮（A项）为雄激素；胰岛素（C项）降血糖；呋塞米（D项）为排钾利尿药，不能替代激素；美替拉酮（E项）抑制皮质醇合成，会加重病情"},{"q":"患者，男，46岁，使用哌替啶进行静脉复合麻醉，术后呼吸抑制仍比较明显，以下可逆转呼吸抑制的药物是","o":["肾上腺素","地西泮","芬太尼","喷他佐辛","纳洛酮"],"a":4,"e":"纳洛酮为阿片受体拮抗药，可竞争性阻断μ、κ、σ受体，迅速逆转哌替啶等阿片类所致的呼吸抑制和镇静，是阿片类药物过量的特效解毒药。肾上腺素（A项）用于过敏休克；地西泮（B项）加重呼吸抑制；芬太尼、喷他佐辛（C、D项）为阿片类，会加重呼吸抑制"},{"q":"患者，女，52岁，服用阿司匹林（pKa为3.5）和苯巴比妥（pKa为 7.4）。关于这两种药在胃中的吸收情况，下列哪种说法是正确的","o":["均不吸收","均完全吸收","吸收程度相同","前者大于后者","后者大于前者"],"a":4,"e":"按Henderson-Hasselbalch方程，弱酸在胃内酸性环境中非离子型比例随pKa升高而增大。苯巴比妥pKa 7.4远高于阿司匹林的3.5，胃中非离子型比例更高、吸收更好，故后者大于前者。两者均不吸收或均完全吸收（A、B项）不符实际；吸收相同（C项）忽略pKa差异；前者大于后者（D项）与规律相反"},{"q":"患者，男，62岁，最近1年表现为记性差，出门经常忘记回家的路，讲话絮叨，情绪变化快、容易波动。该患者确诊为阿尔茨海默病，应首先考虑使用哪类药物进行治疗","o":["NMDA受体拮抗剂","胆碱酯酶抑制剂","胆碱受体阻断剂","多巴胺受体激动剂","5-羟色胺再摄取抑制剂"],"a":1,"e":"阿尔茨海默病存在中枢胆碱能神经元功能减退，胆碱酯酶抑制剂可抑制乙酰胆碱降解、提高脑内乙酰胆碱水平，改善认知功能，是首选药物，如多奈哌齐。NMDA受体拮抗剂（A项，如美金刚）用于中重度；胆碱受体阻断剂（C项）会加重认知障碍；多巴胺受体激动剂（D项）用于帕金森病；SSRI（E项）为抗抑郁药"},{"q":"患者，女，48岁，反复发作性支气管哮喘2年。近10天发作频繁，出现喘息、呼吸困难、胸痛等症状。给予异丙肾上腺素治疗，需叮嘱患者不宜剂量过大或频繁给药，否则可能出现","o":["中枢兴奋症状","直立性低血压","舒张压升高","心悸或心动过速","急性肾衰竭"],"a":3,"e":"异丙肾上腺素为β受体激动药，兴奋心脏β1受体，剂量过大或频繁给药可致心率加快、心悸甚至心律失常，故需控制剂量。中枢兴奋（A项）非其主要不良反应；直立性低血压（B项）多见于α阻断药；舒张压升高（C项）与β2扩血管、舒张压下降相反；急性肾衰竭（E项）无直接关联"},{"q":"一高血压患者，常年服用硝苯地平进行降压，近日发现踝部水肿，不见缓解。请问原因是","o":["尿量减少","血浆晶体渗透压降低","血浆胶体渗透压降低","水钠潴留","毛细血管扩张"],"a":4,"e":"硝苯地平扩张外周小动脉和毛细血管前括约肌，使毛细血管内压力升高、液体渗出增加，形成踝部水肿，而非水钠潴留所致。尿量减少（A项）不是主要原因；血浆晶体渗透压（B项）与胶体渗透压（C项）降低均无依据；水钠潴留（D项）为利尿剂可纠正的机制，与钙拮抗药水肿不同"},{"q":"患者，男，26岁，因上呼吸道感染，医生给予青霉素静脉滴注治疗。在滴注过程中，患者出现面色苍白、冷汗、发绀等症状，检测血压为60/30mmHg，脉搏细弱。此时应首选的急救药物是","o":["多巴胺","去甲肾上腺素","肾上腺素","葡萄糖酸钙","间羟胺"],"a":2,"e":"青霉素过敏性休克首选肾上腺素，其激动α受体收缩血管、升高血压，激动β1受体增强心功能，并激动β2受体舒张支气管，迅速逆转休克与喉头水肿。多巴胺、间羟胺（A、E项）为升压药但无β2平喘作用；去甲肾上腺素（B项）缺β2效应；葡萄糖酸钙（D项）用于过敏辅助，均非首选"},{"q":"患者，女，40岁。因风湿性心脏病出现心衰，心功能Ⅱ级，并有下肢水肿；经地高辛治疗后，心功能有改善，但水肿不见好转。检查发现血浆醛固酮水平高，此时最好选用","o":["呋塞米","氢氯噻嗪","螺内酯","吲达帕胺","卡托普利"],"a":2,"e":"螺内酯为醛固酮受体拮抗药，可拮抗醛固酮的保钠排钾作用，利尿消肿，并能抑制心肌纤维化，适合醛固酮水平升高、地高辛疗效不佳的心衰水肿。呋塞米、氢氯噻嗪、吲达帕胺（A、B、D项）为排钾利尿药，长期用可致低钾并激活RAAS；卡托普利（E项）虽抑制RAAS，但本题针对醛固酮升高首选螺内酯"},{"q":"患者，男，29岁。因败血症休克接受静脉滴注去甲肾上腺素治疗时不慎出现药液外漏，引起皮肤苍白和疼痛。为防止局部组织缺血坏死，应皮下浸润注射","o":["酚妥拉明","阿托品","育亨宾","普萘洛尔","美卡拉明"],"a":0,"e":"酚妥拉明为α受体阻断药，可拮抗去甲肾上腺素的α缩血管作用，扩张局部血管、改善缺血，防止外漏所致组织缺血坏死。阿托品（B项）为M阻断药；育亨宾（C项）为α2受体阻断药，对突触后α1作用弱；普萘洛尔（D项）为β阻断药；美卡拉明（E项）为神经节阻断药，均不适用"},{"q":"患者，男，73岁，心脏病史20年，左心肥厚伴肺水肿，近日加重入院治疗。诊断为心源性哮喘，可选用下列哪种药物","o":["肾上腺素","异丙肾上腺素","氢化可的松","吗啡","克伦特罗"],"a":3,"e":"吗啡可扩张外周血管、降低心脏前后负荷，减轻肺淤血；同时镇静、缓解焦虑并抑制呼吸中枢对CO2的敏感性，减慢呼吸，是心源性哮喘的辅助治疗。肾上腺素、异丙肾上腺素（A、B项）兴奋心脏、加重肺淤血；氢化可的松（C项）不直接缓解；克伦特罗（E项）为β2激动药，均非首选"},{"q":"患者，男，35岁，口服乐果20ml后入院。查体：神清，瞳孔缩小，皮肤湿冷，双肺可闻及散在湿啰音。应采用的治疗药物是","o":["阿托品","氯解磷定","毛果芸香碱","毒扁豆碱","新斯的明"],"a":0,"e":"乐果为有机磷农药，抑制胆碱酯酶、使乙酰胆碱蓄积，出现瞳孔缩小、皮肤湿冷、湿啰音等毒蕈碱样症状，阿托品可阻断M受体、迅速缓解这些症状，是首选药。氯解磷定（B项）为胆碱酯酶复活药，对乐果效果差且需与阿托品合用；毛果芸香碱、毒扁豆碱、新斯的明（C、D、E项）为拟胆碱药，会加重中毒"},{"q":"患者，男，25岁，有肾功能不良病史，本次因大面积烧伤后并发铜绿假单胞菌感染，应选用的抗菌药物是","o":["庆大霉素","氨苄西林","氯霉素","头孢哌酮","林可霉素"],"a":3,"e":"头孢哌酮为第三代头孢菌素，对铜绿假单胞菌抗菌活性强，主要经胆汁排泄，肾功能不良时不易蓄积、无需大幅调整剂量，适合该患者。庆大霉素（A项）有肾毒性，肾功能不良者禁用；氨苄西林、氯霉素、林可霉素（B、C、E项）对铜绿假单胞菌无效或疗效差"},{"q":"患者，女，56岁。经常自觉心慌气短，诊断为慢性心功能不全、风湿性心脏病。建议使用哪种药物改善心力衰竭","o":["普萘洛尔","地高辛","硝酸甘油","哌唑嗪","氢氯噻嗪"],"a":1,"e":"地高辛为强心苷，可增强心肌收缩力、减慢心率并抑制房室传导，改善慢性心衰患者的血流动力学和症状，是慢性心功能不全的常用药。普萘洛尔（A项）抑制心肌、禁用于急性失代偿心衰；硝酸甘油（C项）主要扩血管减轻前负荷；哌唑嗪（D项）、氢氯噻嗪（E项）为辅助用药，非改善心衰收缩功能首选"},{"q":"患者，女，30岁，1型糖尿病4年余，一直使用胰岛素治疗。近两日出现恶性、呕吐、不能正常进食，今晨突发昏迷，测得即刻血糖3.4mmol/L。考虑为低血糖昏迷。该患者应","o":["加用一次胰岛素","口服糖水","静脉注射糖皮质激素","心内注射肾上腺素","静脉注射50%葡萄糖"],"a":4,"e":"低血糖昏迷需迅速提高血糖，静脉注射50%葡萄糖可直接、快速补充血糖，是昏迷患者的首选抢救措施。口服糖水（B项）仅用于清醒者，昏迷时有误吸风险；加用胰岛素（A项）会加重低血糖；糖皮质激素（C项）升糖慢；心内注射肾上腺素（E项）用于心搏骤停，均不适用"},{"q":"患者，女，25岁。因面色苍白、头晕、乏力1年余，加重伴心慌1个月来诊。实验室检查：Hb 60g/L（正常值110～160g/L），RBC 3.0×1012/L［正常值(3.5～5.5)×1012/L］，MCV 70fl（正常值80～100fl），MCH 25pg（正常值27～31pg），MCHC 298g/L（正常值320～360g/L），血清铁46μg/dl（正常值50～150μg/dl）。考虑以何种药物治疗","o":["叶酸","硫酸亚铁","维生素B12","维生素K","枸橼酸钠"],"a":1,"e":"患者Hb、RBC降低，MCV、MCH、MCHC均偏低，血清铁降低，为小细胞低色素性贫血，最常见于缺铁性贫血，需补充铁剂，硫酸亚铁为首选。叶酸、维生素B12（A、C项）用于巨幼细胞性贫血；维生素K（D项）促凝血；枸橼酸钠（E项）为抗凝剂，均不能纠正缺铁"},{"q":"患者，男，53岁。6天前高烧，寒战，排痢疾样便，伴呼吸困难及心慌、胸痛，痰中带血，伴有肝脾肿大。以下哪种病原虫感染及其对应治疗药物最符合该患者的诊断和治疗","o":["阿米巴——甲硝唑","疟疾——青蒿素","血吸虫——吡喹酮","疟疾——二氯尼特","血吸虫——甲硝唑"],"a":2,"e":"患者有痢疾样便、呼吸困难、胸痛、痰中带血及肝脾肿大，符合血吸虫病急性期表现，吡喹酮是治疗血吸虫病的首选药，对多种血吸虫高效。阿米巴——甲硝唑（A项）虽有痢疾样便，但无肝脾肿大与肺部表现；疟疾（B、D项）以寒战高热交替为特征；血吸虫——甲硝唑（E项）药物错误"},{"q":"患者，男，41岁，患有慢性肾衰竭。患者于40分钟前睡眠时突然发作呼吸困难，程度剧烈，不能平卧，伴大汗淋漓，并伴有咳嗽，咳粉红色泡沫痰，自服“速效救心丸”症状无缓解，就近社区医生查血压190/120mmHg，给予硝酸甘油静脉滴注，并经急诊入院。宜选用下列何药降压","o":["氢氯噻嗪","呋塞米","可乐定","螺内酯","硝苯地平"],"a":1,"e":"患者慢性肾衰竭合并急性肺水肿，血压显著升高，呋塞米为强效袢利尿药，静脉给药可迅速利尿、减轻容量负荷和肺淤血，兼有降压作用，是首选。氢氯噻嗪（A项）利尿弱且肾功能差时疗效下降；可乐定（C项）为中枢性降压药；螺内酯（D项）利尿弱、起效慢；硝苯地平（E项）起效快但不利肺水肿"},{"q":"患者，男，65岁，因心前区痛就诊。心电图显示ST段抬高，诊断为心绞痛发作，需要用硝酸甘油，但此药肝首过效应较大，可选用的适宜剂型是","o":["肠溶片剂","口服液体制剂","舌下片剂","颗粒剂","胶囊剂"],"a":2,"e":"硝酸甘油口服肝首过效应大、生物利用度低，舌下含服可经口腔黏膜直接吸收入血，避开首过消除，起效迅速，适合心绞痛急性发作。肠溶片剂、口服液、颗粒剂、胶囊剂（A、B、D、E项）均经胃肠道吸收，不可避免首过效应，不能满足快速起效需求"},{"q":"患者，男，55岁，因车祸骨折手术，麻醉前给予异戊巴比妥，其pKa＞7.5，在胃肠道pH范围内基本都是","o":["离子型，吸收快而完全","非离子型，吸收快而完全","离子型，吸收慢而不完全","非离子型，吸收慢而不完全","离子型和非离子型相等"],"a":1,"e":"异戊巴比妥为弱酸性药物，pKa＞7.5，而胃肠道pH多在1～7.5之间，低于其pKa，按Henderson-Hasselbalch方程主要以非离子型存在，脂溶性大、吸收快而完全。离子型（A、C、E项）主要在pH高于pKa时占优，吸收慢；非离子型吸收慢而不完全（D项）与弱酸在酸性环境易吸收的规律矛盾"},{"q":"患者，男，56岁。有急性心肌梗死病史，经治疗好转后，停药月余。昨夜突发剧咳而憋醒，不能平卧，咳粉红色泡沫样痰，烦躁不安，心率130次/min，血压160/95mmHg，两肺有小水泡音。诊断为急性左心衰竭、心源性哮喘，用哪组药物治疗最适宜","o":["吗啡＋毒毛花苷K","氢氯噻嗪＋地高辛","氢氯噻嗪＋卡托普利","氢氯噻嗪＋硝普钠","氢氯噻嗪＋氨茶碱"],"a":0,"e":"吗啡扩张血管、镇静并抑制呼吸中枢对CO2敏感性，缓解心源性哮喘的呼吸困难与焦虑；毒毛花苷K为速效强心苷，增强心肌收缩力，两者联合迅速改善急性左心衰。氢氯噻嗪为基础利尿（B～E项），但与地高辛、卡托普利、硝普钠或氨茶碱的组合在缓解急性心源性哮喘方面不如吗啡＋速效强心苷直接"},{"q":"患者，女，43岁，因肌肉酸痛、无力就诊。既往病史及治疗：十二指肠溃疡病史2年，使用法莫替丁和硫糖铝；家族性高胆固醇血症5年，使用洛伐他汀和依折麦布；开角型青光眼1年，使用噻吗洛尔。尿液分析结果示肌红蛋白尿，请分析患者目前出现的情况最可能源于哪种治疗药物","o":["法莫替丁","硫糖铝","洛伐他汀","依折麦布","噻吗洛尔"],"a":2,"e":"洛伐他汀为他汀类降脂药，可抑制肌细胞辅酶Q10合成、损伤肌细胞膜，引起肌痛、肌无力甚至横纹肌溶解和肌红蛋白尿，与该患者表现相符。法莫替丁、硫糖铝（A、B项）用于溃疡；依折麦布（D项）抑制胆固醇吸收，肌毒性罕见；噻吗洛尔（E项）为β阻断药滴眼，均无此反应"},{"q":"患者，女，28岁，大面积烧伤并铜绿假单胞菌感染，选用羧苄西林治疗，应注意不能与下列何药置于同一容器中","o":["头孢拉定","阿米卡星","磺胺嘧啶","青霉素G","红霉素"],"a":1,"e":"羧苄西林为β-内酰胺类，与阿米卡星等氨基糖苷类在同一容器中混合可发生理化配伍反应，使两药失活，故应分开给药。头孢拉定、青霉素G（A、D项）同属β-内酰胺类，磺胺嘧啶（C项）、红霉素（E项）与羧苄西林无此明确配伍禁忌，阿米卡星是典型不宜同容器者"},{"q":"患者，男，30岁，反复上腹部疼痛3年，服药后短时间缓解。近来因工作劳累，疼痛发作，进食后缓解。经X线钡餐检查：胃部可见溃疡病灶。该患者首选治疗药物是","o":["氢氧化铝","丙谷胺","阿托品","雷尼替丁","米索前列醇"],"a":3,"e":"雷尼替丁为H2受体阻断药，可选择性阻断胃壁细胞H2受体、抑制胃酸分泌，促进溃疡愈合，是消化性溃疡常用药，作用较西咪替丁强且不良反应少。氢氧化铝（A项）仅中和胃酸；丙谷胺（C项）阻断胃泌素受体、疗效弱；阿托品（D项）为非选择性M阻断药；米索前列醇（E项）主要用于NSAID溃疡"},{"q":"患者，女。甲状腺肿大，血清TSH升高，疑似单纯甲状腺肿。可选用的治疗是","o":["TSH静脉灌注","丙硫氧嘧啶","左旋甲状腺素","131I治疗","甲巯咪唑"],"a":2,"e":"单纯性甲状腺肿伴TSH升高，多因甲状腺激素合成不足致代偿性TSH分泌增多，补充左旋甲状腺素可抑制TSH、缩小甲状腺，是首选治疗。TSH静脉灌注（A项）无治疗意义；丙硫氧嘧啶、甲巯咪唑（B、E项）为抗甲状腺药，会加重甲减；131I治疗（D项）破坏甲状腺，均不适用"},{"q":"患者，女，49岁，有高血压和痛风病史，实验室检查示胆固醇为9.1mmol/L（正常值2.9～6.0mmol/L），尿酸为416μmol/L（正常值为178.4～297.4μmol/L），其他指标均在正常范围内。以下药物中不适于该患者的是","o":["考来烯胺","烟酸","依折麦布","洛伐他汀","甲亚油酰胺"],"a":1,"e":"烟酸可升高血尿酸、诱发或加重痛风，并引起面部潮红，故高血压合并痛风患者不宜使用。考来烯胺（A项）为胆汁酸螯合剂；依折麦布（C项）抑制胆固醇吸收；洛伐他汀（D项）为他汀类；甲亚油酰胺（E项）为降脂药，均不升高尿酸，相对可用，烟酸最不适合"},{"q":"患者，女，57岁。诊断为肺部感染。处方：0.9%氯化钠250ml＋克林霉素0.9g，1次/d，静脉滴注，4天；口服阿奇霉素0.5g，1次/d。该处方存在的问题是","o":["克林霉素不适宜用于肺部感染","阿奇霉素不适宜用于肺部感染","克林霉素剂量过高","阿奇霉素剂量过高","克林霉素和阿奇霉素不宜合用"],"a":4,"e":"克林霉素与阿奇霉素均作用于细菌核糖体50S亚基，作用位点相同或相近，合用可产生竞争性拮抗、降低疗效，且均延长QT间期，故不宜联用。克林霉素、阿奇霉素均可用于肺部感染（A、B项错）；0.9g克林霉素、0.5g阿奇霉素均在常用剂量范围（C、D项错），故选E"},{"q":"患者，女，49岁，胸闷、气短反复发作3个月余，休息时突发胸骨后压榨性疼痛。心电图检查显示ST段抬高，诊断为变异型心绞痛。应首选的药物是","o":["普萘洛尔","硝苯地平","硝酸甘油","维拉帕米","硝酸异山梨酯"],"a":1,"e":"变异型心绞痛由冠状动脉痉挛所致，硝苯地平为钙拮抗药，可扩张冠状动脉、解除冠脉痉挛，是变异型心绞痛首选。普萘洛尔（A项）阻断β受体后α缩血管作用占优，可加重痉挛，禁用；硝酸甘油、硝酸异山梨酯（C、E项）和维拉帕米（D项）虽可扩血管，但对冠脉痉挛的首选是硝苯地平"},{"q":"患者，女，44岁。最近感觉疲劳，皮肤发干。血压和脉搏正常，甲状腺肿大，无触痛、无结节。血细胞计数正常，血糖和电解质含量正常，TSH水平增高，T4水平降低。诊断为甲状腺功能减退。应用以下什么药物治疗","o":["左甲状腺素钠","丙硫氧嘧啶","甲巯咪唑","卡比马唑","碘化钾"],"a":0,"e":"患者TSH升高、T4降低，为甲状腺功能减退，需补充甲状腺激素，左甲状腺素钠半衰期长、作用稳定，是替代治疗首选。丙硫氧嘧啶、甲巯咪唑、卡比马唑（B、C、D项）为抗甲状腺药，用于甲亢；碘化钾（E项）用于单纯甲状腺肿或甲亢术前准备，均不用于甲减"},{"q":"患者，女，57岁，诊断为神经性休克早期，给予去甲肾上腺素静脉滴注。治疗中发现点滴局部皮肤苍白、发凉，并自述疼痛。此时除更换注射部位、局部外敷外，还应局部浸润注射酚妥拉明扩张血管，其作用机制是","o":["阻断M受体","阻断N受体","阻断α受体","阻断β受体","抑制胆碱酯酶"],"a":2,"e":"酚妥拉明为α受体阻断药，可竞争性阻断血管平滑肌α1受体，拮抗去甲肾上腺素的缩血管作用，使血管扩张、改善局部缺血，用于外漏处理。阻断M受体（A项）为阿托品作用；阻断N受体（B项）为神经节阻断药；阻断β受体（D项）为普萘洛尔；抑制胆碱酯酶（E项）为新斯的明作用"},{"q":"患者，女，35岁，近三个月常有幻听，感觉思维情感不由自己支配。神经系统检查未见异常。医生诊断为急性精神分裂症，服用氯丙嗪治疗1周后出现颈背部肌肉痉挛，斜颈等症状。请问以下哪个药物可以缓解氯丙嗪引起的这种不良反应","o":["苯海索","金刚烷胺","左旋多巴","溴隐亭","卡比多巴"],"a":0,"e":"氯丙嗪阻断黑质-纹状体多巴胺受体，引起肌张力增高、斜颈等锥体外系反应，苯海索为中枢性抗胆碱药，可恢复纹状体多巴胺与乙酰胆碱平衡，缓解该反应。金刚烷胺（B项）、左旋多巴（C项）、卡比多巴（D项）主要用于帕金森病，对氯丙嗪所致急性肌张力障碍效果差；溴隐亭（E项）为多巴胺受体激动药，亦非首选"},{"q":"患者，男，45岁，因心前区痛1小时就诊，诊断为心肌缺血，使用某药治疗，其t1/2是12小时，给药1g后血浆最高浓度为4mg/L；如果每12小时用药1g，多长时间后可达到10mg/L","o":["12小时","1天","3天","6天","不可能"],"a":4,"e":"每次给药间隔等于半衰期（12小时）时，稳态血药浓度为单次给药峰值的约2倍，即最高约8mg/L，永远达不到10mg/L，故答案为不可能。12小时（A项）或1天（B项）尚未达稳态；3天、6天（C、D项）虽可蓄积至稳态，但稳态峰值仅约8mg/L，仍不足10mg/L"},{"q":"一充血性心力衰竭患者使用了洋地黄和氢氯噻嗪治疗后出现快速型心律失常，以下处理措施正确的是","o":["停用氢氯噻嗪加服氯化钾","停用氢氯噻嗪加阿托品","将氢氯噻嗪换成呋塞米","将氢氯噻嗪换成吲达帕胺","将氢氯噻嗪换成甘露醇"],"a":0,"e":"氢氯噻嗪为排钾利尿药，致低血钾后增强洋地黄毒性、诱发快速型心律失常，处理应停利尿药并补钾，以稳定心肌、纠正心律失常。加阿托品（B项）用于缓慢型心律失常；换成呋塞米（C项）、吲达帕胺（D项）仍排钾，加重低钾；甘露醇（E项）为渗透性利尿药，亦致电解质紊乱，均不当"},{"q":"患者，男，40岁，因慢性痔疮伴出血，导致血红蛋白100g/L（正常120～160g/L），此患者需要的治疗药物是","o":["右旋糖酐","硫酸亚铁","叶酸","维生素B12","维生素B6"],"a":1,"e":"患者慢性失血导致血红蛋白降低，为缺铁性贫血，需补铁治疗，硫酸亚铁为口服补铁首选，是合成血红蛋白的原料。右旋糖酐（A项）为血浆代用品；叶酸、维生素B12（C、D项）用于巨幼细胞性贫血；维生素B6（E项）参与氨基酸代谢，均不能纠正缺铁性贫血"},{"q":"患者，女，75岁，因咳嗽、胸痛和咯血1个月就诊。X线检查左肺门有个3cm×4cm×3cm肿物，边界不清；痰液中可找到脱落的癌细胞，诊断为肺癌。拟采取全麻手术切除，肌松作用较完全的全麻药是","o":["氧化亚氮","麻醉乙醚","氟烷","恩氟烷","七氟烷"],"a":1,"e":"麻醉乙醚镇痛和肌松作用较强，能阻滞神经肌肉接头，可提供较完全的肌肉松弛，适合需要肌松的手术，但现已少用。氧化亚氮（A项）镇痛强、肌松差；氟烷、恩氟烷、七氟烷（C、D、E项）肌松作用较弱，常需合用肌松药，故乙醚肌松最完全"},{"q":"某患者诊断为铜绿假单胞菌感染，治疗药物选择头孢他啶，其抗菌作用机制为","o":["抑制细菌叶酸的合成","抑制细菌DNA的复制","抑制细菌蛋白质的合成","抑制细菌细胞壁的合成","改变胞浆膜的通透性"],"a":3,"e":"头孢他啶为第三代头孢菌素，属β-内酰胺类，与青霉素结合蛋白结合，抑制肽聚糖交联、阻碍细菌细胞壁合成，属繁殖期杀菌药。抑制叶酸合成（A项）为磺胺类；抑制DNA复制（B项）为喹诺酮类；抑制蛋白质合成（C项）为氨基糖苷类、大环内酯类；改变胞浆膜通透性（E项）为多黏菌素类机制"},{"q":"患者，男，20岁。主诉周期性、节律性上腹部疼痛，伴有嗳气、反酸、胸骨后烧灼感、恶心、呕吐和便秘等症状。给予西咪替丁抑制胃酸分泌，其作用机制是","o":["阻断M胆碱受体","中和胃酸","阻断H2受体","保护胃黏膜","阻断胃泌素受体"],"a":2,"e":"西咪替丁为H2受体阻断药，可竞争性阻断胃壁细胞H2受体，抑制组胺刺激的胃酸分泌，用于消化性溃疡。阻断M胆碱受体（A项）为哌仑西平等；中和胃酸（B项）为抗酸药；保护胃黏膜（D项）为硫糖铝、铋剂；阻断胃泌素受体（E项）为丙谷胺，均非西咪替丁机制"},{"q":"患儿，女，8岁，突然出现寒战高热、头痛、喷射状呕吐、颈项强直。实验室检查：脑脊液混浊，细菌培养阳性。诊断为流行性脑脊髓膜炎，除对症治疗外，应首选","o":["磺胺嘧啶","万古霉素","头孢氨苄","庆大霉素","复方磺胺甲噁唑"],"a":0,"e":"磺胺嘧啶易透过血脑屏障，在脑脊液中浓度高，对脑膜炎奈瑟菌敏感，是流行性脑脊髓膜炎的首选药之一。万古霉素（B项）不易透过血脑屏障且主要针对革兰阳性菌；头孢氨苄（C项）为一代头孢，不入脑；庆大霉素（D项）对脑膜炎球菌无效；复方磺胺甲噁唑（E项）非流脑首选"},{"q":"患者，女，55岁。高血压、糖尿病病史20年。长期应用厄贝沙坦进行治疗，疗效欠佳。近1周血压维持在170/90mmHg左右，下肢轻度凹陷性水肿，考虑采用联合用药，以提高降压效果。下列药物中可选用的是","o":["呋塞米","氢氯噻嗪","螺内酯","吲达帕胺","阿米洛利"],"a":3,"e":"厄贝沙坦为ARB，疗效欠佳伴水肿时可联合利尿剂，吲达帕胺为噻嗪样利尿剂，降压平稳、作用时间长，与ARB合用可增强降压并减轻水肿，适合糖尿病高血压患者。呋塞米、氢氯噻嗪（A、B项）作用时间短；螺内酯、阿米洛利（C、E项）为保钾利尿药，与ARB合用高钾风险大，故首选吲达帕胺"},{"q":"患者，女，47岁，诊断为绒毛膜上皮癌，采用大剂量甲氨蝶呤（MTX）治疗。大剂量甲氨蝶呤会对正常组织产生毒性作用。下列哪个药物能减轻甲氨蝶呤对正常组织尤其是骨髓的毒性作用","o":["去铁胺","亚叶酸钙","N-乙酰半胱氨酸","青霉胺","维生素K"],"a":1,"e":"亚叶酸钙为甲酰四氢叶酸，是叶酸的活性形式，可绕过被甲氨蝶呤抑制的二氢叶酸还原酶，补充四氢叶酸、解救正常细胞，减轻甲氨蝶呤对骨髓等组织的毒性，称解救疗法。去铁胺（A项）解救铁过载；N-乙酰半胱氨酸（C项）用于对乙酰氨基酚中毒；青霉胺（D项）驱铜；维生素K（E项）拮抗华法林，均不适用"},{"q":"患者，男，23岁。患过敏性哮喘6年。2天前，出现喘息、咳嗽、打喷嚏和胸痛等哮喘复发症状。医生给予沙丁胺醇和丙酸倍氯米松联合治疗。该病例选用沙丁胺醇的理由不包括","o":["对β2受体的选择性比异丙肾上腺素高","心脏反应性比异丙肾上腺素轻微","可收缩支气管黏膜血管","用于控制支气管哮喘发作","可气雾吸入给药"],"a":2,"e":"沙丁胺醇为选择性β2受体激动药，激动支气管平滑肌β2受体使cAMP升高而松弛平滑肌，用于缓解哮喘发作，心脏兴奋作用弱于异丙肾上腺素，且可气雾吸入局部起效。收缩支气管黏膜血管属α受体激动效应，C项实为α受体激动药的作用；A、B、D、E均为选用沙丁胺醇的依据"},{"q":"患者，女，55岁，体重76kg，身高160cm。因多饮、多尿确诊为2型糖尿病，经饮食治疗和运动锻炼，2个月后空腹血糖为8.8mmol/L，餐后2小时血糖13mmol/L。进一步治疗应选择","o":["加用磺脲类降血糖药","加双胍类降血糖药","加胰岛素治疗","加口服降血糖药和胰岛素","维持原饮食治疗和运动"],"a":1,"e":"该患者体重指数约29.7，属肥胖的2型糖尿病，空腹及餐后血糖均明显升高，饮食运动控制不佳，首选双胍类。双胍类减少肝糖输出、改善外周胰岛素抵抗并减轻体重，适合肥胖者。A项磺脲类促胰岛素分泌，易致低血糖和体重增加；C项胰岛素用于1型或口服药失效；E项单靠饮食运动已不足"},{"q":"患者，男，34岁，4年前饮食不当后出现上腹胀痛，伴恶心、嗳气，无呕吐，此后常于秋冬、冬春交际时出现餐后上腹胀痛，无反酸、胃灼热，空腹减轻，食欲可，进食减少。1周因劳累，少量喝酒后再次出现上述症状，大小便正常。吸烟史10年。常规体检、血常规和腹部B超检查无明显异常。初步考虑为消化性溃疡，可选用的治疗药物为","o":["阿托品","山莨菪碱","哌仑西平","东莨菪碱","后马托品"],"a":2,"e":"哌仑西平选择性阻断胃壁细胞M1受体，抑制胃酸和胃蛋白酶分泌，用于消化性溃疡且少有口干、视力模糊等副作用。A项阿托品、B项山莨菪碱、D项东莨菪碱、E项后马托品均为非选择性M受体阻断药，作用广泛、抗溃疡弱而副作用多；其中东莨菪碱还易致中枢抑制"},{"q":"患儿，男，12岁，近期饮水多，尿多，口干易渴，食量增加，体重下降，血压正常，但心跳过速。尿糖升高，血糖测试显著升高。诊断1型糖尿病。治疗首选哪种药物","o":["米格列醇","胰岛素","罗格列酮","阿卡波糖","氯磺丙脲"],"a":1,"e":"1型糖尿病因胰岛β细胞破坏致胰岛素绝对缺乏，必须终身外源性补充胰岛素控制血糖并维持生命。A项米格列醇、D项阿卡波糖为α葡萄糖苷酶抑制剂，仅延缓糖吸收；C项罗格列酮为胰岛素增敏剂；E项氯磺丙脲促胰岛素分泌，均依赖残存β细胞功能，不适用于1型"},{"q":"患者，男，68岁。有糖尿病史多年，长期服用磺酰脲类降糖药，近日因血压明显升高自行服用卡托普利，经一段时间后心慌、手抖、出冷汗、面色苍白、四肢冰冷、麻木和无力。经查血糖2.5mmol/L，其原因是","o":["卡托普利竞争性拮抗磺酰脲类药物","卡托普利使磺酰脲类药物降解减少","卡托普利减少了醛固酮的分泌","卡托普利减少糖分的吸收","卡托普利增加机体对胰岛素的敏感性"],"a":4,"e":"卡托普利抑制血管紧张素转换酶，减少血管紧张素Ⅱ并抑制缓激肽降解，可提高外周组织对胰岛素的敏感性，与磺酰脲类合用易诱发低血糖，故出现心慌、出汗、血糖2.5mmol/L。A项卡托普利不拮抗磺酰脲类；B项不影响其降解；C项减少醛固酮分泌与低血糖无关；D项不减少糖吸收"},{"q":"患儿，男，4岁，因发热1天出现全身强直性抽搐紧急送医，给予药物治疗后发现肌腱反射消失，请问患者注射的是以下哪种药物","o":["苯巴比妥","苯妥英钠","水合氯醛","硫酸镁","地西泮"],"a":3,"e":"硫酸镁注射过量时Mg2＋抑制神经肌肉接头传递，先出现膝腱反射消失、肌无力，继而呼吸抑制，故肌腱反射消失提示镁中毒，可用于破伤风等惊厥。A项苯巴比妥、C项水合氯醛、E项地西泮过量多为中枢抑制而非腱反射消失；B项苯妥英钠过量致眼球震颤、共济失调"},{"q":"患者，女，58岁，头晕1年，加重2周。入院主诉无诱因头晕、头痛，近期加重。查体：T 36、5℃，P 54次/分，R 17次/min，BP 170/90mmHg，神志清醒，自主体位，双肺呼吸音清，心界正常，心率54次/min，无杂音，腹部查体正常。辅助检查：心电图显示窦性心动过缓，血、尿常规正常，肝功正常，血脂高，血浆离子正常，双肾及肾上腺彩超未见异常，心脏超声心动检查未见异常。诊断为高血压。该患者最宜使用的药物是","o":["利舍平","氢氯噻嗪","依那普利","非洛地平","可乐定"],"a":2,"e":"依那普利为ACE抑制药，扩张动静脉降低外周阻力，降压同时不反射性加快心率，且改善胰岛素抵抗、对血脂无不良影响，适合伴窦性心动过缓及高脂血症的高血压。A项利舍平、E项可乐定抑制中枢交感，可加重心动过缓；B项氢氯噻嗪升高血脂血糖；D项非洛地平反射性加快心率"},{"q":"患者，男，40岁。当晚洗完凉水澡后进食冰淇淋，约半小时后出现中上腹痛，并逐渐加重呈剧烈绞痛难忍，伴恶心、气促、手足麻木，体检无明显异常。诊断为胃绞痛，给予山莨菪碱治疗，山莨菪碱的作用为","o":["抑制胃肠道腺体分泌","松弛胃肠道平滑肌","镇痛","镇静","扩张血管"],"a":1,"e":"山莨菪碱为M受体阻断药，解除平滑肌痉挛尤其是胃肠道平滑肌，故用于胃绞痛。A项抑制腺体分泌是阿托品较突出的作用，山莨菪碱此作用弱；C项镇痛、D项镇静非其直接作用，疼痛缓解源于解痉；E项扩张血管虽为其作用，但与治疗胃绞痛无关，且不易透过血脑屏障，中枢镇静弱"},{"q":"患者，男，53岁，主诉经常头痛、头晕、手脚麻木近2年，近期经常出现劳累后心前区疼痛并向左肩部放射。就诊时，血压180/108mmHg，心电图表现为弓背向下型ST段抬高。此患者最宜选择的降压药是","o":["神经节阻断药","利尿药","α受体阻断药","血管紧张素转换酶抑制药","中枢降压药"],"a":3,"e":"ACE抑制药扩张血管、降低外周阻力和心脏前后负荷，兼具靶器官保护，适合高血压伴心肌缺血及ST段改变者。A项神经节阻断药、C项α受体阻断药易致体位性低血压和反射性心动过速；B项利尿药单用对伴心脏损害者保护不足；E项中枢降压药降压同时抑制心率，不利于心输出量"},{"q":"患者，女，35岁，因长期失眠就医，给予某催眠药的消除常数为0、35hr-1。设静脉注射后患者入睡时血药浓度为1mg/L，当患者醒转时血药浓度为0.125mg/L，请问患者大约睡了多久","o":["4小时","6小时","8小时","9小时","10小时"],"a":1,"e":"消除速率常数k为0.35h⁻¹，半衰期t1/2＝0.693/k≈2小时。血药浓度由1mg/L降至0.125mg/L为原来的1/8，需经3个半衰期，故睡眠约6小时。A项4小时仅2个半衰期，浓度为0.25mg/L；C项8小时、D项9小时、E项10小时对应浓度已远低于0.125mg/L，均不符"},{"q":"患者，女，22岁，肺结核服用利福平后发现手掌、泪液呈橘色，紧张求医，请问医生应如何处理","o":["维持原有用药，不予处理","加用乙胺丁醇","停用利福平","减小利福平用量","加用维生素B6"],"a":0,"e":"利福平及其代谢物呈橘红色，经泪液、尿液、汗液等排泄可使分泌物着色，属无害的药理现象，停药后可恢复，无需处理。C项停药会中断抗结核治疗、诱发耐药；D项减量影响疗效；B项加乙胺丁醇、E项加维生素B6均非针对着色，乙胺丁醇用于联合抗结核，维生素B6用于异烟肼周围神经炎"},{"q":"患儿，男，8岁，因出生时难产导致癫痫，时有发作。今天阵发性大发作已2小时，尚未缓解，到急诊，查体时再次发作，口吐白沫、全身抽搐、意识障碍，诊断为癫痫持续状态，最宜选用的是","o":["水合氯醛静脉注射","苯巴比妥静脉注射","硫喷妥钠静脉注射","地西泮静脉注射","苯妥英钠静脉注射"],"a":3,"e":"癫痫持续状态需迅速终止发作，地西泮静脉注射脂溶性高、起效快，能增强GABA能抑制，为首选。A项水合氯醛、B项苯巴比妥、C项硫喷妥钠、E项苯妥英钠均可抗惊厥，但起效较慢或需负荷量，多在地西泮无效后序贯使用；硫喷妥钠为麻醉药，呼吸抑制明显"},{"q":"患者，男，65岁，因肺部感染每天静脉滴注头孢哌酮和氧氟沙星。第10天咽部出现白色薄膜，第14天出现腹泻症状，诊断为“白色念珠菌病”，宜选用的药物是","o":["灰黄霉素","克霉唑","制霉菌素","咪康唑","益康唑"],"a":2,"e":"制霉菌素为多烯类抗真菌药，口服不吸收，在肠道和黏膜局部发挥抗白色念珠菌作用，适合鹅口疮及消化道念珠菌病。A项灰黄霉素仅抗浅表皮肤真菌；B项克霉唑、D项咪康唑、E项益康唑多为外用，口服吸收差且毒性大；本例为广谱抗菌药后咽部及肠道念珠菌感染，不宜用抗浅表真菌药"},{"q":"患者，女，75岁，股骨颈骨折手术，曾用吗啡镇痛，以下哪种不良反应与应用吗啡无关","o":["引起颅内压力的增高","胆囊内压力明显增高","可抑制消化液的分泌","可引起较严重的腹泻","能够产生恶心、呕吐"],"a":3,"e":"吗啡兴奋平滑肌，使胃肠蠕动减慢、消化液分泌减少，故引起便秘而非腹泻，腹泻与吗啡无关。A项吗啡扩张脑血管致颅内压升高；B项兴奋Oddi括约肌使胆囊内压升高；C项抑制消化液分泌；E项刺激延髓催吐化学感受区致恶心呕吐，均属其不良反应"},{"q":"患者，60岁，女性，有慢性支气管炎病史。2周前曾患感冒，咳嗽1周，X线检查未见明显异常。医生建议给予外周镇咳药物治疗1周。下列药物中属于外周性镇咳药的是","o":["喷托维林","可待因","盐酸那可汀","愈创甘油醚","氨茶碱"],"a":2,"e":"盐酸那可汀为外周性镇咳药，抑制咳嗽感受器及传入神经而镇咳，不抑制呼吸中枢，也无成瘾性。A项喷托维林、B项可待因为中枢性镇咳药，可待因还有成瘾性；D项愈创甘油醚为祛痰药，稀释痰液；E项氨茶碱为支气管舒张药，兼有强心利尿作用"},{"q":"某患者不遵医嘱，将两次的地高辛一次服用，宣称“首次剂量加倍”，结果造成地高辛用量过大，引起室性心动过速。此时首先应如何治疗","o":["服用呋塞米","服用氯化钾","吸氧","减量服用","注射地高辛抗体"],"a":1,"e":"地高辛中毒致快速性心律失常多与低血钾有关，补钾可竞争性抑制强心苷与Na＋-K＋-ATP酶结合，故首先服用氯化钾。E项地高辛抗体用于危及生命的严重中毒，非首选；A项呋塞米排钾，可加重中毒；C项吸氧仅为辅助；D项单纯减量不能迅速纠正室性心动过速"},{"q":"患者，女，72岁。因高血压长期服用利血平降压，近期出现肢体颤抖，肌肉僵硬，流涎等症状。除了停用利血平外，以下哪个药物最可能缓解该患者的症状","o":["多巴丝肼","氯丙嗪","苯海索","多奈哌齐","地西泮"],"a":0,"e":"利血平耗竭中枢及外周多巴胺，引起药源性帕金森综合征，表现为震颤、肌强直、流涎，补充左旋多巴可透过血脑屏障转为多巴胺，故用多巴丝肼。C项苯海索为抗胆碱药，对多巴胺耗竭所致者疗效较差；B项氯丙嗪阻断多巴胺受体，可加重症状；D项多奈哌齐用于阿尔茨海默病；E项地西泮仅镇静"},{"q":"患者，女，52岁。新近诊断为高血压，服用某药数月后因血压控制较好自行停药，2日后血压骤升至160/100mmHg。该患者服用的降压药物很可能是","o":["普萘洛尔","卡托普利","氢氯噻嗪","氯沙坦","莫索尼定"],"a":0,"e":"普萘洛尔为非选择性β受体阻断药，长期服用突然停药可出现反跳现象，交感活性反跳性增高致血压骤升、心率加快甚至心绞痛。B项卡托普利、D项氯沙坦停药无此明显反跳；C项氢氯噻嗪停药仅水钠潴留；E项莫索尼定虽激动咪唑啉受体，停药反跳较可乐定轻"},{"q":"患儿，男，7岁，因食用在树林中自采的新鲜蘑菇导致中毒，采用阿托品进行治疗。阿托品为胆碱受体的阻断药，反映其对受体拮抗作用的参数pA2是指","o":["激动药解离常数的定量表示","激动药亲和力的定量表示","激动药内在活性的定量表示","竞争性拮抗药与受体亲和力定量表示","竞争性拮抗药与受体最大效能定量表示"],"a":3,"e":"pA2为使激动药浓度-效应曲线右移两倍所需竞争性拮抗药浓度的负对数，定量反映竞争性拮抗药与受体的亲和力，值越大拮抗越强。A项解离常数、B项亲和力、C项内在活性均为激动药的参数；E项最大效能反映药物内在活性，非pA2含义"},{"q":"患儿，10岁，高热，扁桃体充血，有假膜，有咽干、异物感、发痒等症状，诊断为急性扁桃体炎。治疗首选药物是","o":["阿莫西林","庆大霉素","红霉素","青霉素G","头孢拉定"],"a":3,"e":"急性扁桃体炎多由A组β溶血性链球菌引起，青霉素G为繁殖期杀菌药，对链球菌作用强，可退热并预防风湿热，故首选。B项庆大霉素为氨基糖苷类，对链球菌作用差且有耳肾毒性；C项红霉素用于青霉素过敏者；A项阿莫西林、E项头孢拉定虽有效，但非经典首选"},{"q":"患者，男，70岁。重复语言、近记忆力下降5年，精神行为异常2年。查体：时间、空间定向力障碍，近记忆力、计算力下降，四肢肌力正常，病理征阴性。诊断为阿尔茨海默病。可选用的治疗药物为","o":["毛果芸香碱","醋甲胆碱","新斯的明","毒扁豆碱","占诺美林"],"a":4,"e":"占诺美林为选择性M1受体激动药，可改善阿尔茨海默病患者的认知和胆碱能功能，故可用。A项毛果芸香碱、B项醋甲胆碱、C项新斯的明、D项毒扁豆碱虽增强胆碱能，但选择性差、外周作用明显，剂量受限，且不能延缓病程，不作为治疗药物"},{"q":"患儿，男，5岁，2个月前发烧后开始出现无明显诱因的短暂意识丧失，活动停止，双目凝视，面目呆板，呼之不应，持续10～15s，而后继续活动，对之前的症状无记忆，该情况每天发生数次，请问该患者最适合使用下列哪种药物进行治疗","o":["苯妥英钠","卡马西平","乙琥胺","丙戊酸钠","地西泮"],"a":2,"e":"发作时活动停止、双目凝视、呼之不应、持续10～15秒、事后无记忆，符合癫痫失神小发作，乙琥胺抑制丘脑T型钙通道，为首选且不易致大发作。A项苯妥英钠、B项卡马西平对失神无效甚至加重；D项丙戊酸钠为广谱药但非小发作首选；E项地西泮用于持续状态"},{"q":"患者，男，35岁，反复发作性支气管哮喘病史10年。1周前复发，出现呼吸困难、胸闷、喘息等症状。下列哪个药物可诱发或加重其发生支气管哮喘","o":["酚妥拉明","妥拉唑林","酚苄明","普萘洛尔","哌唑嗪"],"a":3,"e":"普萘洛尔阻断β2受体，使支气管平滑肌收缩、气道阻力增加，并可加重哮喘，哮喘患者禁用。A项酚妥拉明、B项妥拉唑林、C项酚苄明为α受体阻断药，对气道β2无明显影响；E项哌唑嗪选择性阻断α1，主要扩血管降压，不诱发支气管痉挛"},{"q":"患儿，男，13岁，因发热、咽痛就诊。体温39、5℃，咽部红肿，诊断为上呼吸道感染，给予对乙酰氨基酚片降体温，此药的半衰期为4小时，静脉注射给药后约经多长时间血药浓度可降至初始浓度的5%以下","o":["4小时","8小时","20小时","24小时","40小时"],"a":2,"e":"半衰期4小时，血药浓度降至初始5%以下需(1/2)的n次方＜0.05，n≥5，即5个半衰期约20小时。B项8小时仅2个半衰期，剩余25%；A项4小时剩余50%；D项24小时、E项40小时均已远超初次低于5%的时间点"},{"q":"患者，女，54岁。原发性高血压10余年，服用某种抗高血压药物控制血压，由于血压控制效果好便擅自停药2天，患者突然出现胸疼、心动过速、焦虑紧张等症状，血压240/140mmHg。该患者服用的抗高血压药物是","o":["普萘洛尔","硝苯地平","卡托普利","氯沙坦","呋塞米"],"a":0,"e":"普萘洛尔长期应用突然停药产生反跳，β受体向上调节、交感张力反跳性增高，致血压骤升至240/140mmHg并伴心动过速、胸痛。B项硝苯地平、C项卡托普利、D项氯沙坦、E项呋塞米停药均无如此显著的交感反跳现象"},{"q":"患者，女，24岁，患有家族性高脂血症，检查结果显示尿酸为378μmol/L（正常值为178.4～297.4μmol/L），总胆固醇为5.2mmol/L（正常值2.9～6.0mmol/L），甘油三酯为8、3mmol/L（正常值＜1.7mmol/L），给予调血脂药吉非贝齐治疗，该药的作用机制是","o":["抑制HMG-CoA，减少内源性胆固醇的合成","激活PPARα，增加脂蛋白酯酶合成","减少外源性胆固醇吸收","下调肝细胞LDL受体","促进脂肪细胞摄取脂肪酸"],"a":1,"e":"吉非贝齐为贝特类调血脂药，激活过氧化物酶体增殖物激活受体α，增加脂蛋白脂酶合成，加速富含甘油三酯脂蛋白水解，主降甘油三酯。A项抑制HMG-CoA还原酶为他汀类机制；C项减少外源性胆固醇吸收为依折麦布；D项他汀上调LDL受体；E项非贝特类主要作用"},{"q":"患者，女，48岁。因患糖尿病足合并感染住院，入院后给予口服格列本脲2.5mg，po，qd，血糖控制在6mmol/L以下。入院时检查肾功能：BUN 2.56mmol/L，Cr 58μmol/L。给予0、4g阿米卡星（＋）0、9%氯化钠注射液100ml，qd，ivgtt，连续用药2周后，患者出现耳鸣。由于感染尚未完全控制，继续用药6天，患者复查肾功能：BUN 6.5mmol/L，Cr 125μmol/L。药师查房时发现此现象后，应当采取的应对措施是","o":["停用格列本脲","停用阿米卡星","停用阿米卡星，改用庆大霉素","改阿米卡星ivgtt为po","同时停用格列本脲和阿米卡星"],"a":1,"e":"阿米卡星为氨基糖苷类，连续用药出现耳鸣、血肌酐升高，提示耳毒性和肾毒性，应立即停药。C项改用庆大霉素同属氨基糖苷类，交叉耳肾毒性，不可取；D项口服不吸收，不能替代全身抗感染；A项格列本脲引起的是低血糖，与耳鸣、肾损害无关；E项无需停格列本脲"},{"q":"患者，男，28岁，因呼吸困难急诊，需要做气管插管救治，用硫喷妥钠麻醉，其作用时间短的原因是","o":["生物利用度低","迅速经肾脏排泄","迅速被肝脏代谢","与血浆蛋白迅速结合","在体内迅速重新分布"],"a":4,"e":"硫喷妥钠脂溶性极高，静脉注射后迅速进入脑组织发挥麻醉，随后很快再分布至肌肉和脂肪组织，血药浓度骤降，故作用时间短。A项生物利用度低与其静脉给药无关；B项主要经肝代谢而非肾排泄；C项肝代谢非短效主因；D项血浆蛋白结合高反而延长作用"},{"q":"患者，男，53岁。门诊诊断为Hp（＋），医生处方：胃必治2包，po，tid。Hp根除治疗：阿莫西林0.5g，po，tid；奥美拉唑20mg，po，bid。患者用药1周不见好转。该治疗方案应考虑加入下面哪种药物","o":["克拉霉素","头孢噻肟","阿奇霉素","林可霉素","埃索美拉唑"],"a":0,"e":"根除幽门螺杆菌标准三联为质子泵抑制剂加两种抗菌药，现用奥美拉唑＋阿莫西林，应加克拉霉素构成标准方案。B项头孢噻肟、D项林可霉素不用于Hp根除；C项阿奇霉素非标准Hp方案；E项埃索美拉唑与奥美拉唑同类，重复抑酸而无抗菌作用"},{"q":"患者，男，35岁，塔吊司机，近日诊断为原发性高血压，不可选用下列哪种药物降压治疗","o":["可乐定","氨氯地平","卡维地洛","普萘洛尔","氢氯噻嗪"],"a":0,"e":"可乐定激动中枢α2及咪唑啉受体，抑制交感神经传出，常见嗜睡、镇静、头晕，塔吊司机需高度警觉，故不宜使用。B项氨氯地平为二氢吡啶类CCB；C项卡维地洛兼有α、β阻断；D项普萘洛尔为β阻断药；E项氢氯噻嗪为利尿药，均无明显镇静作用"},{"q":"患者，男，20岁。因溺水导致心脏骤停，速来医院急救。进行心肺复苏时医生使用的是心脏新三联针，其组成成分是","o":["肾上腺素，阿托品，利多卡因","去甲肾上腺素，阿托品，利多卡因","异丙肾上腺素，阿托品，利多卡因","肾上腺素，多巴胺，异丙肾上腺素","肾上腺素，阿托品，异丙肾上腺素"],"a":0,"e":"心脏新三联针由肾上腺素、阿托品、利多卡因组成，分别兴奋心脏、解除迷走抑制和抗室性心律失常，用于心肺复苏。B项去甲肾上腺素、C项异丙肾上腺素、D项多巴胺均非三联组成；E项以异丙肾上腺素替代利多卡因，属错误配伍"},{"q":"患者，男，39岁，近1周频于清晨睡梦中出现心前区疼痛，患者经常疼醒，持续3～5分钟后缓解，劳累和情绪激动时并不出现该症状，心电图检查显示ST段抬高，患者宜选用的治疗药物是","o":["硝苯地平","地尔硫䓬","维拉帕米","普萘洛尔","地高辛"],"a":0,"e":"静息时心前区疼痛、劳累时不发作、ST段抬高，符合变异型心绞痛，系冠脉痉挛所致，硝苯地平扩张冠脉、解除痉挛为首选。B项地尔硫䓬、C项维拉帕米也有效，但本例以硝苯地平为代表；D项普萘洛尔阻断β2后α收缩占优，可加重痉挛，禁用；E项地高辛无抗心绞痛作用"},{"q":"患者，女，43岁，有哮喘病史，服用阿司匹林后诱发哮喘，治疗时不宜选用的药物是","o":["肾上腺素","抗组胺药","抗白三烯药物","糖皮质激素","氨茶碱"],"a":0,"e":"阿司匹林哮喘由COX受抑、白三烯合成增加引起，属非IgE介导的假性过敏反应，肾上腺素主要用于过敏休克的α、β激动，对此类哮喘无效且因α缩血管不利，不宜选用。C项抗白三烯药针对其机制，D项糖皮质激素、E项氨茶碱均可缓解症状，B项抗组胺药亦可配合使用"},{"q":"患者，女，26岁。与人激烈争吵后手指突然出现苍白，继而变为青紫，伴有局部发凉、刺痛和酸胀不适，当地医院诊断为雷诺综合征。可选用的治疗药物为","o":["间羟胺","酚妥拉明","去甲肾上腺素","阿替洛尔","拉贝洛尔"],"a":1,"e":"雷诺综合征为肢端小动脉痉挛，酚妥拉明阻断α受体、扩张血管，改善肢端血流。A项间羟胺、C项去甲肾上腺素为α激动药，收缩血管加重缺血；D项阿替洛尔为β1阻断药；E项拉贝洛尔兼阻断α、β，但α阻断作用弱，非首选"},{"q":"患者，男，30岁。因患系统性红斑狼疮采用糖皮质激素进行治疗，但诱发了十二指肠溃疡。药物作用的两重性指","o":["既有对因治疗作用，又有对症治疗作用","既有副作用，又有毒性作用","既有治疗作用，又有不良反应","既有局部作用，又有全身作用","既有原发作用，又有继发作用"],"a":2,"e":"药物作用两重性指同一药物既有治疗作用，又有与治疗目的无关的不良反应，如糖皮质激素抗炎同时诱发溃疡。A项对因与对症属治疗作用分类；B项副作用与毒性反应均属不良反应；D项局部与全身作用、E项原发与继发作用均非两重性含义"},{"q":"患者，男，65岁。高血压病史20年，近日出现上腹部疼痛，经钡餐检查诊断为胃溃疡。除应用抗消化性溃疡药外，控制血压药物最好选用","o":["甲基多巴","利舍平","可乐定","普萘洛尔","硝苯地平"],"a":2,"e":"可乐定抑制胃肠分泌和运动，不增加胃酸，适合高血压伴胃溃疡者。B项利舍平耗竭儿茶酚胺同时使胃肠动力和胃酸分泌增加，可诱发或加重溃疡，禁用；A项甲基多巴、D项普萘洛尔、E项硝苯地平对胃酸分泌无此保护作用"},{"q":"患者，男，50岁。持续高热，剧烈头痛入院，用青霉素、链霉素治疗3天，无明显效果。发病第5日于胸、肩、背等处发现直径2～4mm的圆形鲜红色丘疹，经进一步检查诊断为斑疹伤寒，宜选用","o":["庆大霉素","磺胺嘧啶","头孢拉定","林可霉素","四环素"],"a":4,"e":"斑疹伤寒由立克次体引起，四环素类为首选，可抑制立克次体蛋白合成，早期足量应用退热快。A项庆大霉素、C项头孢拉定对立克次体无效；B项磺胺嘧啶可促进立克次体生长，反可加重病情；D项林可霉素针对革兰阳性菌和厌氧菌，无效"},{"q":"患者，女，35岁，因入睡困难、早醒5年多就诊。查体正常，医生给予地西泮治疗。地西泮对睡眠时相的影响是","o":["明显缩短慢波睡眠","明显延长慢波睡眠","延长快波睡眠","缩短快波睡眠","缩短快波睡眠和慢波睡眠"],"a":1,"e":"地西泮主要延长非快动眼睡眠第2期，使总慢波睡眠时程延长、觉醒次数减少，催眠作用近似生理睡眠，故为延长慢波睡眠；对快波睡眠影响小，停药后反跳性多梦较巴比妥类轻。E项缩短快波和慢波睡眠是巴比妥类特点；C项延长快波睡眠不符合苯二氮䓬类对REM影响轻微的事实"},{"q":"患者，女，17岁。有支气管哮喘病史5年。2天前，出现打喷嚏、喘息、咳嗽、胸闷等症状，诊断为支气管哮喘复发。给予抗过敏药、糖皮质激素和支气管平滑肌舒张剂等联合治疗。该患给予糖皮质激素治疗首选的给药途径是","o":["口服","吸入","肌内注射","皮下注射","静脉注射"],"a":1,"e":"吸入给药使糖皮质激素直接作用于气道黏膜，局部抗炎浓度高、全身吸收少，可避免口咽念珠菌感染和声嘶等不良反应，为哮喘长期控制首选。A项口服、C项肌注、E项静脉给药全身副作用大；D项皮下注射不用于糖皮质激素平喘"},{"q":"某患者诊断为铜绿假单胞菌感染，治疗药物选择第三代头孢菌素头孢他啶。有关第三代头孢菌素的特点，叙述错误的是","o":["对β内酰胺酶有较高的稳定性","对铜绿假单胞菌作用强","对G－菌作用不如第一、二代","体内分布较广","基本无肾毒性"],"a":2,"e":"第三代头孢菌素对β内酰胺酶稳定性高、对革兰阴性菌包括铜绿假单胞菌作用强、体内分布广、基本无肾毒性，但对革兰阳性菌作用较第一代弱，故对G－菌作用不如第一、二代的说法错误。A、B、D、E均符合三代头孢特点，其对G－菌作用是增强而非减弱"},{"q":"患者，男，28岁，突发心悸无缓解来诊，BP 100/70mmHg，心电图示阵发性室上性心动过速，P 186次/min，应首选的治疗药物是","o":["奎尼丁","维拉帕米","普罗帕酮","利多卡因","阿托品"],"a":1,"e":"阵发性室上性心动过速首选维拉帕米，其阻断心肌慢钙通道，延长房室结有效不应期，减慢传导而终止折返。A项奎尼丁、C项普罗帕酮为广谱抗心律失常药，不良反应较多；D项利多卡因主要用于室性心律失常；E项阿托品加快心率，不适用"},{"q":"患者，女，55岁，慢性充血性心力衰竭，采用地高辛进行治疗。该药治疗的安全范围较小，临床上评价药物安全性的指标如治疗指数是指","o":["ED50/LD50","LD50/ED50","LD5/ED95","ED95/LD5","LD1/ED95"],"a":1,"e":"治疗指数为半数致死量与半数有效量之比，即LD50/ED50，比值越大药物越安全。A项ED50/LD50为其倒数，无安全性评价意义；C项LD5/ED95为可靠安全系数；D项ED95/LD5、E项LD1/ED95均非治疗指数定义"},{"q":"患者，女，54岁，高血压病史20年。3年前患者发生急性前壁心肌梗死，当时血压为145/70mmHg，心率为100次/min，该患者使用了普萘洛尔进行降压，该药物发挥作用源于","o":["激动β受体","阻断β受体","激动α受体","阻断α受体","阻断α和β受体"],"a":1,"e":"普萘洛尔为非选择性β受体阻断药，通过阻断β1受体减慢心率、降低心肌收缩力和心输出量而降压，适合伴心肌梗死者。A项激动β受体为异丙肾上腺素作用；C项激动α受体为去甲肾上腺素；D项阻断α受体为酚妥拉明；E项阻断α和β受体为卡维地洛"},{"q":"患者，男，38岁，诊断为感染中毒性休克，需给予糖皮质激素进行抢救，此时应采用的给药方案是","o":["大剂量肌肉注射","小剂量反复静脉点滴给药","大剂量突击静脉给药","一次负荷剂量肌肉注射给药，然后静脉点滴维持给药","小剂量快速静脉注射"],"a":2,"e":"感染中毒性休克需短时间内达到有效血药浓度，糖皮质激素应大剂量突击静脉给药，利用其抗炎、抗休克作用迅速改善微循环。A项肌注吸收慢；B、E项小剂量不足以抢救；D项负荷量后维持适用于中毒性肝炎等，非休克抢救方案"},{"q":"患者，男，55岁。数小时前右侧腰背部剧烈疼痛，难以忍受，出冷汗，服颠茄片不见好转，急来院就诊。尿常规检查可见红细胞。B型超声波检查肾结石。诊断为肾绞痛。患者宜选用何种药止痛","o":["阿托品＋解磷定","哌替啶＋美沙酮","吗啡＋纳洛酮","阿托品＋哌替啶","阿托品＋吗啡"],"a":3,"e":"肾绞痛为输尿管平滑肌剧烈痉挛，阿托品解痉，哌替啶抑制疼痛中枢，两药合用互补且哌替啶对Oddi括约肌影响较吗啡轻，故首选。A项解磷定为胆碱酯酶复活药，与绞痛无关；B项哌替啶＋美沙酮重复用阿片类；C项吗啡＋纳洛酮作用拮抗；E项吗啡兴奋Oddi括约肌"},{"q":"患者，女，28岁，尿频、尿急、尿痛伴尿血。查体：体温36、8℃，心率80次/min，心肺听诊无异常；双侧肾区叩击痛（+-）；无明显腹痛；舌红，苔微黄不腻。尿常规：红细胞、白细胞满视野。B超：双肾、输尿管、膀胱未见明显异常。考虑诊断为大肠杆菌引起的急性尿路感染。应首选药物","o":["青霉素G","四环素","阿奇霉素","氯霉素","氧氟沙星"],"a":4,"e":"大肠杆菌所致急性尿路感染首选氟喹诺酮类，氧氟沙星抑制细菌DNA回旋酶，抗菌谱广、尿中浓度高。A项青霉素G对革兰阴性杆菌作用弱；B项四环素、D项氯霉素耐药多且毒性大；C项阿奇霉素主要针对呼吸道和性传播病原体，非尿路感染首选"},{"q":"患儿，男，10岁，因包茎入院行包皮环切术，麻醉医生选择氯胺酮进行麻醉，以下最不可能会出现的情况是","o":["表情淡漠，意识模糊，眼睛睁开","肌张力有所增加","体表镇痛效果好","有梦幻现象","给药初期心率减慢、血压下降"],"a":4,"e":"氯胺酮产生分离麻醉，表情淡漠、睁眼、体表镇痛好并可有梦幻和肌张力增加，同时兴奋交感使心率增快、血压升高，故给药初期心率减慢、血压下降不会出现。A、B、C、D均为氯胺酮典型表现，其中梦幻现象为苏醒期常见反应"},{"q":"患者，女，55岁，诊断为绝经后骨质疏松症，给予阿仑膦酸钠。以下说法正确的是","o":["该药口服后主要在小肠吸收，吸收良好","同服抗酸药不影响该药的吸收","患者如果合并有十二指肠溃疡，仍然可以继续使用本药","药物主要集中于骨","在骨内的半衰期较短"],"a":3,"e":"阿仑膦酸钠属双膦酸盐，与骨羟基磷灰石亲和力高，口服后主要浓集于骨并长期滞留，抑制破骨细胞而抗骨吸收。A项其口服吸收差，不足1%；B项抗酸药和食物显著降低吸收；C项食管刺激明显，十二指肠溃疡者禁用；E项在骨内半衰期很长，可达数年"},{"q":"患者，男，38岁。因反复尿频、尿急、尿痛3天来院就诊。患者5天前有不洁性交史，2天前出现上述症状，自服诺氟沙星胶囊未见效。查体：四肢和心肺正常。给予0.9%氯化钠注射液20ml内加小诺米星注射液120mg静脉注射，以及其他口服药治疗。静脉注射完毕，患者突然感到浑身无力、呼吸困难，随即晕倒在地，呼之不应。急查：呼吸11次/min，肌力Ⅲ级，肌张力减弱。下列说法中不正确的是","o":["小诺米星属于氨基糖苷类抗生素","小诺米星可引起神经肌肉阻滞作用","小诺米星不应静脉注射给药","小诺米星容易引起过敏反应","新斯的明和钙剂可用于对抗此类反应"],"a":3,"e":"小诺米星为氨基糖苷类，可阻滞神经肌肉接头致呼吸抑制，本例静注后肌无力、呼吸困难即属此反应，新斯的明和钙剂可对抗，但它并不以过敏反应多见。B项所述阻滞作用确为其毒性；C项氨基糖苷类不宜静推；A项分类正确；E项解救措施正确"},{"q":"患者，女，55岁。因门静脉高压、呕血、黑便入院治疗，可用的药物是","o":["去甲肾上腺素","肾上腺素","多巴胺","异丙肾上腺素","酚妥拉明"],"a":0,"e":"去甲肾上腺素激动α受体使血管强烈收缩，口服或局部用于上消化道出血可止血，故门静脉高压呕血、黑便可用。B项肾上腺素、D项异丙肾上腺素扩血管或加快心率，不利于止血；C项多巴胺扩肾血管；E项酚妥拉明阻断α受体，扩张血管反可加重出血"},{"q":"患者，女，35岁，因右上腹痛1小时就诊，初步诊断为胆绞痛，不宜选用吗啡镇痛的原因是","o":["抑制呼吸","引起恶心","兴奋Oddi括约肌","抑制咳嗽","引起体位性低血压"],"a":2,"e":"吗啡兴奋Oddi括约肌致痉挛，使胆汁和胰液排出受阻、胆道内压升高，加重胆绞痛，故不宜单用。A项抑制呼吸、B项恶心、E项体位性低血压为其常见不良反应但非胆绞痛禁忌主因；D项抑制咳嗽是镇咳机制，与胆道无关"},{"q":"某肠绞痛患者，遵医嘱肌内注射阿托品治疗，患者出现口干，该现象属于","o":["治疗作用","后遗效应","变态反应","毒性反应","副作用"],"a":4,"e":"阿托品阻断M受体解痉的同时必然抑制唾液腺分泌，引起口干，属治疗剂量下与治疗目的无关的作用，即副作用。B项后遗效应为停药后残留作用；C项变态反应为免疫反应；D项毒性反应由过量引起；A项治疗作用指解痉止痛，口干并非治疗目的"},{"q":"患者，女，66岁。患支气管哮喘30余年，2天前哮喘再发，给予氨茶碱、倍氯米松和沙丁胺醇等药物进行治疗。关于氨茶碱的描述，以下哪项是错误的","o":["为控制急性哮喘应快速静脉注射","可松弛支气管和其他平滑肌","可兴奋心脏","可兴奋中枢","有一定的利尿作用"],"a":0,"e":"氨茶碱静脉给药须缓慢推注或稀释滴注，快速注射可致心律失常、血压骤降甚至猝死，故应快速静脉注射的说法错误。B项松弛支气管平滑肌、C项兴奋心肌、D项兴奋中枢、E项利尿均为氨茶碱已知作用，叙述正确"},{"q":"患者，女，28岁，大面积烧伤并铜绿假单胞菌感染，选用下列何组药物治疗","o":["青霉素＋氯霉素","青霉素＋四环素","头孢菌素＋红霉素","羧苄西林＋庆大霉素","头孢菌素＋氯霉素"],"a":3,"e":"大面积烧伤并铜绿假单胞菌感染，羧苄西林为抗假单胞菌青霉素，庆大霉素为氨基糖苷类，两者协同杀菌，故首选。B项青霉素＋四环素、C项头孢菌素＋红霉素、E项头孢菌素＋氯霉素对铜绿假单胞菌覆盖不足；A项青霉素对耐药假单胞菌无效"},{"q":"患者，男，40岁，4个月前因股骨头坏死行手术治疗。右下肢肿胀、疼痛3天入院，B超显示股深至胫后静脉广泛血栓形成，医生决定进行抗凝和溶栓治疗。下列药物中，不属于抗凝药物的是","o":["普通肝素","低分子肝素","尿激酶","华法林","阿加曲班"],"a":2,"e":"尿激酶直接激活纤溶酶原，溶解已形成的纤维蛋白血栓，属纤维蛋白溶解药，不属于抗凝药。A项普通肝素、B项低分子肝素通过抗凝血酶Ⅲ抗凝；D项华法林抑制维生素K依赖凝血因子；E项阿加曲班直接抑制凝血酶，均为抗凝药"},{"q":"患儿，男，6岁。昨晚进食海鲜，今晨开始畏寒、发热、腹痛，以左下腹甚，腹泻伴明显里急后重，大便8次，初为稀便，继之为黏液脓血便，诊断为急性细菌性痢疾。对该病例首先采用的抗菌药物是","o":["口服四环素","静脉注射氧氟沙星","肌内注射氯霉素","静脉注射庆大霉素","口服呋喃唑酮"],"a":4,"e":"呋喃唑酮口服吸收少、在肠道浓度高，对志贺菌等肠道致病菌有较好抗菌作用，为细菌性痢疾常用药。B项氧氟沙星静脉给药并非首选途径；A项四环素、C项氯霉素耐药及不良反应多；D项庆大霉素肌注对肠道感染局部浓度低"},{"q":"患者，男，45岁，外伤失血性休克，输入大量血液一周后，全身皮下散在紫癜，血小板低于100×109/L。治疗用药应是","o":["氨甲苯酸","肾上腺素","阿司匹林","地塞米松","麻黄碱"],"a":3,"e":"大量输血后血小板低于正常并出现紫癜，属免疫性血小板破坏，糖皮质激素地塞米松可抑制免疫反应、降低毛细血管脆性而止血。A项氨甲苯酸为抗纤溶药，用于纤溶亢进；B项肾上腺素、E项麻黄碱为升压药；C项阿司匹林抑制血小板聚集，可加重出血"},{"q":"患者，男，30岁，上腹部疼痛3年，服药后短时间缓解。近来因工作劳累疼痛又发作，进食后缓解。经X线钡餐检查：诊断为十二指肠溃疡。该患者首选下列哪个药物进行治疗","o":["氢氧化铝","复方氢氧化铝片","阿托品","雷尼替丁","米索前列醇"],"a":3,"e":"十二指肠溃疡与胃酸分泌过多相关，雷尼替丁阻断胃壁细胞H2受体，抑制基础及刺激性胃酸分泌，促进溃疡愈合，为首选。A项氢氧化铝、B项复方氢氧化铝片为抗酸药，仅中和已分泌胃酸；C项阿托品解痉但抗酸弱；E项米索前列醇主要用于NSAID相关溃疡"},{"q":"患者，男，18岁。放学回家口渴误服装在饮料瓶中的敌敌畏，入院时患者已处于昏迷状态，全身湿冷，呼吸微弱，抽搐，嘴角有分泌物，小便失禁。查体：颜面青紫，针尖样瞳孔，肺部听诊湿啰音，全血胆碱酯酶活性降低。根据患者症状和体征，治疗可选用","o":["毒扁豆碱","毛果芸香碱","去甲肾上腺素","阿托品","糖皮质激素"],"a":3,"e":"敌敌畏为有机磷酸酯类，抑制胆碱酯酶致乙酰胆碱蓄积，出现针尖样瞳孔、大汗、肌颤、肺湿啰音，阿托品阻断M受体可迅速解除毒蕈碱样症状。A项毒扁豆碱、B项毛果芸香碱为胆碱能药，加重中毒；C项去甲肾上腺素、E项糖皮质激素非解毒药"},{"q":"患者，47岁，患2型糖尿病10年，现因头晕、心悸，前往医院诊治，医生诊断为糖尿病伴发高血压和窦性心动过速。医生给予格列本脲和普萘洛尔治疗。请问格列本脲的作用是","o":["刺激胰岛β细胞释放胰岛素而降低血糖","属于α葡萄糖苷酶抑制剂","新型胰岛素类似物","可以阻止胰岛的衰退","促进乳酸释放"],"a":0,"e":"格列本脲为磺酰脲类，与胰岛β细胞膜受体结合，关闭钾通道、去极化后开放钙通道，触发胰岛素释放而降血糖。B项α葡萄糖苷酶抑制剂为阿卡波糖；C项胰岛素类似物为注射给药；D项延缓β细胞衰退非磺脲类作用；E项促进乳酸释放为双胍类不良反应"},{"q":"患者，女，65岁。患慢性心功能不全，用地高辛进行治疗，引起室性心动过速的毒性反应。药物的毒性反应是指","o":["一种过敏反应","在使用治疗用量时所产生的与治疗目的无关的反应","因用量过大或药物在机体内蓄积所致的反应","一种遗传性生化机制异常所产生的特异反应","指剧毒药所产生的毒性作用"],"a":2,"e":"毒性反应指用量过大或药物在体内蓄积过多引起的严重功能紊乱或器质性损害，地高辛蓄积致室性心动过速即属此。A项过敏反应为免疫反应；B项治疗量下与治疗目的无关的反应是副作用；D项遗传性生化异常为特异质反应；E项剧毒药作用非毒性反应定义"},{"q":"患者，男，50岁。间断头晕10年，曾诊断为高血压，间断服用抗高血压药物。近一周头晕加重伴头痛，无胸痛胸闷。体格检查：血压170/105mmHg，余正常。该患需紧急降压应选择哪种药物","o":["氢氯噻嗪","呋塞米","维拉帕米","可乐定","硝苯地平"],"a":4,"e":"硝苯地平为二氢吡啶类钙通道阻滞药，扩张外周动脉起效快，舌下含服可迅速降压，适合紧急降压。A项氢氯噻嗪、B项呋塞米为利尿药，起效较慢；C项维拉帕米抑制心肌，降压同时减慢心率；D项可乐定起效较慢，不适于紧急降压"},{"q":"患者，女，55岁。体检血压为150/100mmHg，拟采用β受体阻断药A药或B药进行降压治疗。已知A药比B药的pD2值大。下述说法正确的是","o":["B药疗效比A药差","B药内在活性比A药高","A药毒性比B药小","A药与受体的亲和力比B药高","A药作用持续时间比B药短"],"a":3,"e":"pD2为激动药产生最大效应50%时浓度的负对数，与药物和受体的亲和力成正比，A药pD2大于B药说明A药与受体亲和力更高。A项疗效还受内在活性等影响；B项内在活性与效能相关，非pD2；C项毒性、E项作用持续时间与pD2无直接对应"},{"q":"患者，男，70岁。吸烟史40年，高血压病史20余年，左室肥厚伴血管壁增厚。下列可防止和逆转高血压者血管壁增厚和心肌细胞肥大的抗高血压药是","o":["钾通道开放药","β受体阻断剂","α1受体阻断剂","血管紧张素转化酶抑制剂","利尿剂"],"a":3,"e":"ACE抑制药抑制血管紧张素Ⅱ生成，减少醛固酮分泌及交感活性，防止并逆转心血管重构，减轻血管壁增厚和心肌肥厚。A项钾通道开放药、C项α1阻断药、E项利尿药无逆转重构作用；B项β阻断剂虽改善预后，但逆转肥厚作用不如ACEI明确"},{"q":"患者，女，32岁，结核病使用异烟肼治疗，医生又同时给予维生素B6，请问给予维生素B6的原因是","o":["促进异烟肼肾排泄，减轻毒性","抑制异烟肼代谢，增加异烟肼血浆浓度","是异烟肼起作用的辅助因子","增强异烟肼的作用","减轻异烟肼毒性反应"],"a":4,"e":"异烟肼结构与维生素B6相似，可促进其排泄并抑制其活性，导致周围神经炎，补充维生素B6可减轻此毒性反应。A项维生素B6不促进异烟肼排泄；B项不影响异烟肼代谢和血药浓度；C项维生素B6非异烟肼抗菌的辅助因子；D项不增强其抗结核作用"},{"q":"患者，女，18岁。患有重症肌无力2年，一直使用新斯的明治疗。今天患者突然出现恶心、呕吐、心悸汗出、血压下降、肌肉震颤及肌无力加重等症状，考虑为“胆碱能危象”。应选择的治疗药物是","o":["毛果芸香碱","肾上腺素","多巴胺","阿托品","毒扁豆碱"],"a":3,"e":"新斯的明过量致胆碱能危象，乙酰胆碱蓄积既有M样也有N样症状，阿托品阻断M受体可解除流涎、心悸、血压下降等毒蕈碱样症状。A项毛果芸香碱、E项毒扁豆碱增强胆碱能，加重危象；B项肾上腺素、C项多巴胺不能对抗M样症状"},{"q":"患儿，男，6岁，因流感发热，宜选用下列哪种药物退热","o":["阿司匹林","对乙酰氨基酚","地塞米松","青霉素","氯丙嗪"],"a":1,"e":"儿童病毒感染发热宜用对乙酰氨基酚，其抑制中枢前列腺素合成而退热，胃肠刺激小。A项阿司匹林在儿童病毒感染时易致Reye综合征；C项地塞米松不用于普通退热且抑制免疫；D项青霉素为抗菌药，无退热作用；E项氯丙嗪用于人工冬眠，非退热首选"},{"q":"患者，男，51岁。近年来出现尿频、尿急、尿不尽，诊断为良性前列腺增生。遵医嘱服用哌唑嗪进行治疗后排尿困难改善，这种效应是基于哌唑嗪可阻断前列腺和膀胱颈部的","o":["β1受体","β2受体","M受体","α1受体","α2受体"],"a":3,"e":"哌唑嗪选择性阻断前列腺和膀胱颈部平滑肌的α1受体，解除尿道阻力，改善良性前列腺增生所致排尿困难。A项β1、B项β2受体阻断与排尿无关；C项M受体阻断反而抑制逼尿肌收缩，加重尿潴留；E项α2受体阻断主要影响中枢交感反馈"},{"q":"患者，男，25岁，因交通事故发生大量失血，出现低血容量性休克合并少尿，此时为改善微循环缓解症状可使用","o":["低分子量右旋糖酐","促红素","枸橼酸铁铵","呋塞米","氢氯噻嗪"],"a":0,"e":"低分子量右旋糖酐可扩充血容量、降低血液黏稠度并抑制血小板聚集，改善微循环，适用于低血容量性休克伴少尿。B项促红素、C项枸橼酸铁铵用于贫血；D项呋塞米、E项氢氯噻嗪利尿，可进一步减少血容量，加重休克"},{"q":"患者，男，69岁，高血压病史14年，伴慢性心力衰竭1年，每日使用地高辛日维持量治疗。近日突然出现窦性心动过缓，宜选用的治疗药物是","o":["苯妥英钠","利多卡因","阿托品","维拉帕米","胺碘酮"],"a":2,"e":"地高辛中毒致窦性心动过缓属缓慢型心律失常，阿托品阻断M受体、解除迷走神经对窦房结的抑制，使心率加快。A项苯妥英钠、B项利多卡因用于室性心律失常；D项维拉帕米、E项胺碘酮均减慢心率，可加重心动过缓"},{"q":"患者，女，45岁，反复发作性气喘、呼吸困难、胸闷1年，再发20天。可以选用对支气管平滑肌上的β2受体具有选择性兴奋作用的药物是","o":["异丙肾上腺素","肾上腺素","特布他林","多巴胺","氨茶碱"],"a":2,"e":"特布他林为选择性β2受体激动药，激动支气管平滑肌β2受体，激活腺苷酸环化酶使cAMP增加，舒张支气管而平喘。A项异丙肾上腺素、B项肾上腺素对β1、β2选择性低，心脏兴奋明显；D项多巴胺主要作用于多巴胺及α、β受体；E项氨茶碱属黄嘌呤类，非β2激动药"},{"q":"患者，男，60岁，因“头晕、手麻木、乏力1月”入院。化验检查显示维生素B1230、0ng/ml（正常值100～300ng/ml），叶酸10、0ng/ml（正常值1、9～14ng/ml），铁蛋白90ng/ml（正常值80～130ng/ml）。治疗药物可以选择","o":["维生素K","右旋糖酐","维生素C","甲钴胺","鱼精蛋白"],"a":3,"e":"维生素B12低于正常而叶酸、铁蛋白正常，提示维生素B12缺乏所致巨幼细胞贫血，甲钴胺为维生素B12辅酶制剂，可直接补充。A项维生素K用于凝血障碍；B项右旋糖酐扩充血容量；C项维生素C促进铁吸收；E项鱼精蛋白为肝素拮抗剂"},{"q":"患者，男，28岁，腹痛腹泻，大便带血和黏液，呈暗红色，糊状，有腥臭味，留取粪便作阿米巴原虫检查，结果阳性，诊断为阿米巴痢疾，应首选药物","o":["青霉素G","克拉霉素","多黏菌素E","甲硝唑","四环素"],"a":3,"e":"阿米巴痢疾由溶组织内阿米巴引起，甲硝唑在肠腔和组织的浓度高，杀灭滋养体，为首选且对肠道菌群影响小。A项青霉素G、B项克拉霉素、E项四环素对阿米巴无效；C项多黏菌素E针对革兰阴性杆菌，仅肠道局部作用"},{"q":"患者，女，20岁，有支气管哮喘病史10年。1天前，患者于夜间突然出现呼吸困难、无法平卧、喘息、可闻及哮鸣音，下列哪种药物对该患症状无缓解作用","o":["异丙肾上腺素","肾上腺素","色甘酸钠","氨茶碱","氢化可的松"],"a":2,"e":"色甘酸钠稳定肥大细胞膜，阻止过敏介质释放，仅用于哮喘预防，对已发作的急性症状无缓解作用。A项异丙肾上腺素、B项肾上腺素激动β2受体可舒张支气管；D项氨茶碱舒张平滑肌；E项氢化可的松抗炎，均能缓解急性发作"},{"q":"患者，男，32岁，从事IT专业，长期处于熬夜状态，近期经常感觉心悸、无力、头晕，发作时心电图显示心率 200次/min，QRS波呈室上形、且后无P波。患者可选用的治疗药物是","o":["硝苯地平","地尔硫䓬","维拉帕米","普萘洛尔","毒毛花苷K"],"a":2,"e":"阵发性室上性心动过速首选维拉帕米，阻断房室结钙通道、延长不应期，终止折返并减慢心室率。A项硝苯地平主要扩张动脉，对房室结作用弱；B项地尔硫䓬虽有效但非首选；D项普萘洛尔、E项毒毛花苷K起效较慢或减慢传导需警惕"},{"q":"患者，女，47岁，患有Graves病，行放射治疗半年，出现乏力、怕冷、记忆力减退；特殊面容，眼睑水肿，毛发稀疏而干脆、声音嘶哑，食欲缺乏，T3水平明显下降。应选用的药物是","o":["卡比马唑","泼尼松龙","胰岛素","甲状腺素","地塞米松"],"a":3,"e":"放射治疗后T3明显下降、怕冷、乏力、黏液性水肿，提示甲状腺功能减退，应补充甲状腺素替代治疗。A项卡比马唑为抗甲状腺药，可加重甲减；B项泼尼松龙、E项地塞米松为糖皮质激素；C项胰岛素用于糖尿病"},{"q":"患者，女，20岁。因神经源性休克给予去甲肾上腺素治疗，在滴注过程中发现局部皮肤变得苍白，皮温下降。此时除更换注射部位，局部热敷以外，还应给予","o":["多巴胺","麻黄碱","酚妥拉明","普萘洛尔","阿托品"],"a":2,"e":"去甲肾上腺素强激动α受体，外渗可致局部血管强烈收缩、组织缺血坏死，酚妥拉明阻断α受体扩张血管，是外渗时的局部解救药。A项多巴胺、B项麻黄碱拟交感，可加重缺血；D项普萘洛尔阻断β受体；E项阿托品阻断M受体，均不能对抗α缩血管"},{"q":"患者，女，53岁，应用格列本脲治疗2型糖尿病，根据糖化血红蛋白数值发现饮食、锻炼和二甲双胍未产生有效效果。格列本脲的作用机制是","o":["通过降低体重减少胰岛素耐药","增加葡萄糖肾排泄","增加胰岛素合成","促进葡萄糖的胰岛素非依赖的肝、肌肉和脂肪组织的吸收","促进胰腺释放胰岛素"],"a":4,"e":"格列本脲为第二代磺酰脲类，刺激胰岛β细胞释放胰岛素而降血糖，需残存β细胞功能。B项α葡萄糖苷酶抑制剂为阿卡波糖；C项胰岛素类似物需注射；D项阻止胰岛衰退非其作用；E项促进乳酸释放为双胍类特点，可致乳酸酸中毒"},{"q":"患者，女，58岁。因“胸闷、气短”入院，在检查心电图时发现其出现三度房室传导阻滞（心室率32次/min）。为了治疗这种房室传导阻滞，可以选用","o":["去甲肾上腺素","甲氧明","多巴胺","异丙肾上腺素","麻黄碱"],"a":3,"e":"三度房室传导阻滞心室率仅32次/分，异丙肾上腺素激动β1受体，加快心率、促进房室传导，为紧急提升心率的首选。A项去甲肾上腺素、B项甲氧明激动α受体，可反射性减慢心率；C项多巴胺、E项麻黄碱升压强于增心率，非房室传导阻滞首选"},{"q":"患者，男，65岁，患有慢性支气管炎，反复发作。1周前出现剧烈干咳，医生给予镇咳药进行治疗，治疗后期患者咳嗽减轻却伴有明显的成瘾现象，则该药物可能是","o":["喷托维林","可待因","苯佐那酯","右美沙芬","甘草片"],"a":1,"e":"可待因为阿片类中枢性镇咳药，直接抑制延髓咳嗽中枢，镇咳作用强，但反复应用可产生药物依赖和成瘾，故后期出现成瘾现象提示可待因。A项喷托维林、C项苯佐那酯、D项右美沙芬均无明显成瘾性；E项甘草片镇咳作用弱且不成瘾"},{"q":"患者，女，68岁，以“急性心肌梗死”入院，在以尿激酶进行溶栓后12小时皮下注射普通肝素7500U，共3～5天。其中，肝素属于","o":["凝血酶间接抑制药","纤维蛋白溶解药","抑制血小板花生四烯酸代谢的药物","增加血小板内cAMP的药物","抑制ADP活化血小板的药物"],"a":0,"e":"肝素与抗凝血酶Ⅲ结合，增强其对凝血酶及Ⅹa等因子的抑制，属凝血酶间接抑制药。B项纤维蛋白溶解药为链激酶、尿激酶；C项阿司匹林抑制花生四烯酸代谢；D项双嘧达莫增加血小板内cAMP；E项氯吡格雷抑制ADP活化血小板"},{"q":"患者，男，32岁。患风湿性关节炎4年，因受凉感冒，医生为该患者开处方醋酸泼尼松片＋阿司匹林片，该处方最易引起的不良反应为","o":["诱发、加重溃疡","诱发、加重感染","糖尿病","骨质疏松","高血压"],"a":0,"e":"糖皮质激素抑制胃黏膜前列腺素合成、减少黏液碳酸氢盐屏障，阿司匹林直接损伤胃黏膜并抑制前列腺素，两者合用诱发和加重消化性溃疡风险最高。B项加重感染、C项糖尿病、D项骨质疏松、E项高血压虽也可出现，但两药协同以胃肠道溃疡最突出"},{"q":"患者，女，27岁。孕38周行剖宫产，因呼吸循环衰竭怀疑发生羊水栓塞，紧急抢救时为防止出现DIC。首先需要使用的药物是","o":["肝素","链激酶","华法林","水蛭素","阿司匹林"],"a":0,"e":"羊水栓塞易并发弥散性血管内凝血，早期高凝阶段需用肝素抗凝，抑制凝血酶和微血栓形成，防止病情进展。B项链激酶、E项阿司匹林非DIC早期首选；C项华法林起效慢，不适于急救；D项水蛭素为直接凝血酶抑制剂，非本例常规首选"},{"q":"患者，男，25岁，车祸骨折手术，用吗啡镇痛。患者不会出现下列哪种不良反应","o":["颅内压增高","胆囊内压力明显增高","抑制消化液的分泌","腹泻","恶心、呕吐"],"a":3,"e":"吗啡抑制胃肠蠕动和消化液分泌，导致便秘，不会出现腹泻。A项抑制血管运动中枢，扩张脑血管致颅内压升高；B项兴奋Oddi括约肌使胆囊内压升高；C项抑制消化液分泌；E项兴奋催吐区致恶心呕吐"},{"q":"一位男性HIV感染并有AIDS临床症状的患者，需要接受联合用药，其中之一为齐多夫定。该药的主要靶点是下列哪一种酶或复制过程","o":["病毒蛋白酶","病毒颗粒包装或融合","RNA合成","核苷反转录酶","非核苷反转录酶"],"a":3,"e":"齐多夫定为核苷类反转录酶抑制剂，竞争性抑制HIV反转录酶并终止病毒DNA链延长，靶点为核苷反转录酶。A项病毒蛋白酶抑制剂为沙奎那韦等；B项融合或包装抑制药如恩夫韦肽；C项RNA合成不是其主要靶点；E项非核苷类反转录酶抑制剂为奈韦拉平等"},{"q":"患者，女，44岁。最近感觉疲劳，皮肤发干。血压和脉搏正常，甲状腺肿大，无触痛、无结节。血细胞计数正常，血糖和电解质含量正常，TSH水平增高，T4水平降低。诊断为甲状腺功能减退。体内T3是如何产生的","o":["2分子DIT偶联而成","2分子MIT偶联而成","1分子MIT和1分子DIT偶联而成","由TSH降解而来","由垂体分泌而来"],"a":2,"e":"甲状腺过氧化物酶催化MIT和DIT偶联，1分子MIT与1分子DIT偶联生成T3，2分子DIT偶联生成T4。A项2分子DIT生成T4而非T3；B项2分子MIT不生成T3；D项T3由甲状腺球蛋白水解产生，非TSH降解；E项垂体分泌TSH而非T3"},{"q":"患者，老年女性，双眼视物模糊，有异物感数日。眼科检查：视力双眼0、5～0、8；矫正后视力提高不显著；眼压正常；双眼外观正常，眼球向各方向活动自如；角膜上皮见条片状棕褐色微粒沉着；晶状体皮质浑浊。高血压病史15年，冠心病合并房颤3年，2年前曾在当地医师建议下开始口服某种抗心律失常药至今。该药可能是","o":["利多卡因","胺碘酮","奎尼丁","氟卡尼","维拉帕米"],"a":1,"e":"长期服用胺碘酮可致角膜棕色微粒沉着、甲状腺功能异常、肺纤维化及心率减慢等，本例角膜改变和房颤用药史符合。A项利多卡因、C项奎尼丁、D项氟卡尼、E项维拉帕米均无角膜色素沉着的典型不良反应"},{"q":"患者，女，50岁，有心肌缺血病史。近日突然出现心慌，气短，数分钟后能自然缓解，每日可发作数次，发作时常伴有心绞痛的症状。经心电图检查认为阵发性室上性心动过速，此时最好选用","o":["地高辛","硝苯地平","普萘洛尔","硝酸甘油","维拉帕米"],"a":4,"e":"阵发性室上性心动过速伴心绞痛，维拉帕米阻断房室结钙通道，减慢心室率并降低心肌耗氧，可同时缓解心悸和心绞痛。A项地高辛起效慢；B项硝苯地平反射性加快心率；C项普萘洛尔可缓解，D项硝酸甘油主要扩静脉降前负荷"},{"q":"患者，女，47岁，患高血压5年，一直服用缬沙坦治疗。近日因家庭纠纷连续焦虑、睡眠不足，突然出现剧烈头痛、眩晕。入院检查血压为210/110mmHg，应该立即使用的药物是","o":["可乐定","美托洛尔","氨氯地平","胍乙啶","硝普钠"],"a":4,"e":"血压210/110mmHg属高血压急症，硝普钠直接扩张动静脉、起效快、作用强，需静脉滴注迅速控压。A项可乐定、B项美托洛尔、C项氨氯地平起效较慢，不适合立即降压；D项胍乙啶不良反应多，已少用"},{"q":"患者，女，30岁，卵巢癌化疗后出现听力下降和肾功能受损。下列哪个药物最可能造成上述不良反应","o":["博来霉素","顺铂","多柔比星","5-氟尿嘧啶","紫杉醇"],"a":1,"e":"顺铂为铂类抗肿瘤药，主要不良反应为肾毒性和耳毒性，可致听力下降、耳鸣及肾功能损害，用药需充分水化。A项博来霉素主致肺纤维化；C项多柔比星致心脏毒性；D项5-氟尿嘧啶致骨髓抑制和黏膜炎；E项紫杉醇致神经毒性和过敏反应"},{"q":"患者，女，68岁，高血压病史20年，慢性心力衰竭1年，常规给予地高辛日维持量治疗。近期突然出现窦性心动过缓，宜选用的治疗药物是","o":["阿托品","普萘洛尔","胺碘酮","苯妥英钠","维拉帕米"],"a":0,"e":"地高辛中毒致窦性心动过缓，阿托品解除迷走神经对窦房结的抑制，提升心率。B项普萘洛尔、C项胺碘酮、E项维拉帕米均减慢心率或传导，可加重病情；D项苯妥英钠用于地高辛中毒的室性心律失常，对窦缓无效"},{"q":"患者，男，40岁，有抑郁症病史，近期因肺炎链球菌感染引起肺炎，采用某抗菌药物治疗，每次0.4g，2次/天，连续服用3天，肺炎症状缓解，但是出现失眠。该患者可能服用的抗菌药物是","o":["诺氟沙星","多西环素","氯霉素","头孢拉定","克拉霉素"],"a":0,"e":"诺氟沙星属氟喹诺酮类，可透过血脑屏障并抑制GABA受体，引起失眠、头痛等中枢兴奋症状，抑郁病史者更易出现。B项多西环素、C项氯霉素、D项头孢拉定、E项克拉霉素中枢不良反应少见，一般不引起明显失眠"},{"q":"一位肿瘤患者在接受大剂量抗肿瘤药物治疗后出现严重的、不可逆的心肌退行性病变。下列哪个药物最可能造成上述患者的症状","o":["L-门冬酰胺酶","顺铂","多柔比星","博来霉素","环磷酰胺"],"a":2,"e":"多柔比星属蒽环类抗肿瘤药，其代谢产物可产生氧自由基，损伤心肌细胞，导致剂量依赖且不可逆的心肌退行性变和心力衰竭。A项L-门冬酰胺酶主要致过敏和胰腺炎；B项顺铂致肾耳毒性；D项博来霉素致肺纤维化；E项环磷酰胺致出血性膀胱炎"},{"q":"患者，女，56岁，高血压10年，长期服用阿司匹林100mg/d，阿司匹林的pKa是3、5，在pH为7.5肠液中，按解离情况计算，阿司匹林可吸收约","o":["0.01%","0.1%","1%","10%","99%"],"a":0,"e":"阿司匹林为弱酸，pKa3.5，在pH7.5肠液中离子化型与非离子化型之比为10的4次方，非离子化型约占0.01%，故可吸收约0.01%。B项0.1%、C项1%、D项10%均高估了非离子化比例；E项99%为离子化型比例，不能跨膜吸收"},{"q":"患者，男，48岁。双下肢水肿半年余，反复全身水肿3月，进行性加重，尿量减少，含较多泡沫，自觉眼干眼涩，眼睑粘连感，视物渐模糊，当地医院拟诊为“慢性肾炎”，予以中药治疗7天，无好转。自服白糖、黄糖后皮肤瘙痒，搔抓起皮疹，以四肢和胸腹部为主。因反复发热、感冒，水肿加重并波及全身，皮肤瘙痒、皮疹严重而就诊于县人民医院，止痒有效，皮疹消退，查尿蛋白＋＋，血白蛋白22g，胆固醇13.7mmol/L，诊为“肾病综合征”。给予糖皮质激素及其他药物治疗。长期应用糖皮质激素，可引起","o":["高血钙","高血磷","低血钾","高血钾","低血压"],"a":2,"e":"长期应用糖皮质激素促进蛋白分解并抑制醛固酮、增加肾排泄，致低血钾，还可引起高血糖、向心性肥胖。A项高血钙、B项高血磷不符合，糖皮质激素减少肠道钙吸收、增加排泄，可致低血钙；D项高血钾相反；E项低血压错误，糖皮质激素可致高血压"},{"q":"患者，女，45岁，近期经常有头痛、头晕症状，偶尔伴有恶心。查体：BP 160/85mmHg，P 140次/min，诊断为高血压，该患者宜服用的降压药是","o":["硝苯地平","地尔硫䓬","维拉帕米","福辛普利","氢氯噻嗪"],"a":2,"e":"血压160/85mmHg伴心率140次/分，维拉帕米为非二氢吡啶类钙拮抗药，抑制窦房结和房室结，降压同时明显减慢心率。A项硝苯地平反射性加快心率；B项地尔硫䓬亦减慢心率；D项福辛普利、E项氢氯噻嗪对心率影响小"},{"q":"患者，男，28岁，大面积烧伤后铜绿假单胞菌感染，同时伴肾功能严重损害，应选用药物是","o":["庆大霉素","氨苄西林","氯霉素","羧苄西林","林可霉素"],"a":3,"e":"羧苄西林为抗假单胞菌青霉素，主要经肾排泄但肾毒性小，适合烧伤后铜绿假单胞菌感染伴肾功能损害者。A项庆大霉素为氨基糖苷类，耳肾毒性大；B项氨苄西林对铜绿假单胞菌无效；C项氯霉素抑制骨髓；E项林可霉素针对革兰阳性菌和厌氧菌"},{"q":"患者，男，26岁，1型糖尿病10年。现背部皮肤感染，诊断为背痈，使用抗生素治疗，该药的消除半衰期（t1/2）为12小时，停药后多长时间药物基本从体内消除","o":["30小时","40小时","50小时","60小时","90小时以上"],"a":3,"e":"药物基本从体内消除通常需5个半衰期，t1/2为12小时，5乘12为60小时，停药后60小时基本消除。A项30小时仅2.5个半衰期；B项40小时、C项50小时不足5个半衰期；E项90小时以上远超基本消除所需时间"},{"q":"患者，男，18岁，腹泻5天，腹泻物为水样便，量较多，每天5～6次，1小时前出现便血，量多，色鲜红呈块状。入院查体：T 40.5℃，P 116次/min，R 30次/min，BP 70/50mmHg，神志模糊，全身皮肤无黄染出血点及瘀斑，周身淋巴结无肿大，双肺呼吸音粗无啰音，余无异常。血常规示：血红蛋白8g，白细胞 24、1X109/L，出血时间1min，凝血时间6min，大便隐血是4＋以上。该患者宜使用的药物是","o":["山莨菪碱","东莨菪碱","毒扁豆碱","筒箭毒碱","琥珀胆碱"],"a":0,"e":"中毒性细菌性痢疾出现休克、微循环障碍，山莨菪碱阻断M受体、解除血管痉挛、改善微循环，为抢救用药。B项东莨菪碱中枢镇静强；C项毒扁豆碱为胆碱酯酶抑制剂；D项筒箭毒碱、E项琥珀胆碱为肌松药，均不适用"},{"q":"患者，男，45岁，右腿骨折手术治疗后出现肿胀和疼痛，B超显示有深静脉血栓形成，给予链激酶进行溶栓，患者出现黑便，此时需要下列何种药物治疗","o":["鱼精蛋白","维生素K","维生素C","氨甲苯酸","右旋糖酐"],"a":3,"e":"链激酶溶栓激活纤溶酶原，过量致纤维蛋白溶解引起黑便等出血，氨甲苯酸抑制纤溶酶原激活，为对抗药。A项鱼精蛋白拮抗肝素；B项维生素K拮抗香豆素类；C项维生素C非止血特效药；E项右旋糖酐抑制血小板聚集，可加重出血"},{"q":"患者，女，30岁，月经量多已2年，近3个月来感乏力、头晕、心悸，检查血红蛋白60g/L，白细胞6.0×109/L，血小板140×109/L，镜下可见红细胞体积缩小，中央淡染区扩大，治疗该患者首选","o":["肌内注射维生素B12","口服铁剂","输血","脾切除","口服叶酸"],"a":1,"e":"月经量多、血红蛋白60g/L、红细胞体积小且中央淡染区扩大，符合缺铁性贫血，首选口服铁剂补铁。A项维生素B12、E项叶酸用于巨幼细胞贫血；C项输血仅用于严重贫血或休克；D项脾切除用于溶血性贫血等，非本例适应证"},{"q":"患者，女，40岁，近1月出现入睡困难，睡眠易醒、早醒，近2周于每晚睡前服用异戊巴比妥2片（0、1g/片）后，自觉睡眠时间延长，但于昨日停药后出现夜梦增多，这主要是因为","o":["后遗效应","中枢抑制作用","“反跳性”缩短NREMS","“反跳性”延长REMS","过量中毒"],"a":3,"e":"异戊巴比妥为巴比妥类，长期服用抑制快波睡眠，停药后快波睡眠反跳性延长，出现夜梦增多。A项后遗效应为宿醉现象；B项中枢抑制为用药时作用；C项反跳性缩短NREMS不符；E项过量中毒表现为呼吸抑制，非停药后梦多的原因"},{"q":"患者，男，68岁。患有肺源性心脏病10余年，本次因呼吸道感染入院治疗。入院后，医生给予妥布霉素进行抗感染治疗，同时给予呋塞米消除水肿以减轻心脏负担。当晚，患者出现耳鸣。下列说法中不正确的是","o":["患者耳鸣症状的出现与妥布霉素的耳毒性有关","停用呋塞米，改为氨茶碱利尿可以减少耳毒性","妥布霉素的耳毒性因呋塞米的使用而得到增强","停用妥布霉素，改为阿米卡星可以减少耳毒性","停用妥布霉素，改为阿奇霉素可以减少耳毒性"],"a":3,"e":"妥布霉素与阿米卡星同为氨基糖苷类，耳毒性机制相同、可交叉加重，改用阿米卡星不能减少耳毒性，该说法不正确。A项耳鸣确与妥布霉素耳毒性有关；B项呋塞米有耳毒性，改用氨茶碱可减风险；C项两药合用耳毒性增强；E项阿奇霉素耳毒性小，替换合理"},{"q":"患者，男，36岁，反复发作性上腹部疼痛5年，近一周出现疼痛、反酸、烧灼感、恶心等症状。给予抗酸、保护胃黏膜等治疗，大量口服可能引起碱血症的药物是","o":["氢氧化铝","碳酸钙","三硅酸镁","氧化镁","碳酸氢钠"],"a":4,"e":"碳酸氢钠为可吸收性抗酸药，大量口服后吸收入血可碱化血液，引起碱血症。A项氢氧化铝、C项三硅酸镁、D项氧化镁为难吸收抗酸药，不易致碱血症；B项碳酸钙吸收少，引起碱血症风险低于碳酸氢钠"},{"q":"患者，男，30岁。入院前2小时进中餐，进食后约半小时，患者出现头晕、头痛、恶心、呕吐、腹痛、腹泻、面色及指甲发绀。查体：急性危重病容，全身严重青紫，皮肤湿冷，心率118次/min，血压45/30mmHg，余未见异常。血常规Hb 145g/L，白细胞15.4×109/L；大便检验发现脓血便黏液（＋＋），白细胞（＋），脓细胞（＋＋），红细胞（＋）。该患者治疗可给予","o":["哌替啶","东莨菪碱","地西泮","山莨菪碱","毛果芸香碱"],"a":3,"e":"本例为中毒性菌痢休克型，山莨菪碱解除微血管痉挛、改善微循环并抑制腺体分泌，可用于抗休克。B项东莨菪碱中枢抑制强；C项毒扁豆碱增强胆碱能；D项筒箭毒碱、E项琥珀胆碱为骨骼肌松弛药，无抗休克作用"},{"q":"患者，男，26岁，因鼻塞、流涕、咳嗽就诊。体温正常，查体无异常，诊断为感冒，给予按一级动力学消除的抗感冒药治疗。为了迅速达到稳态浓度，可将首次剂量","o":["增加半倍","增加一倍","增加二倍","增加三倍","增加四倍"],"a":1,"e":"按一级动力学消除的药物，首剂给予负荷剂量加倍可迅速达到稳态血药浓度，之后按维持量给药以保持稳态，即负荷剂量原则。A项增加半倍、C项增加二倍、D项三倍、E项四倍均不能恰好快速达稳态，且剂量过大易致中毒"},{"q":"患者，男，56岁。股关节手术，术后给予静脉滴注依替米星预防感染，骨科病区医生目前应用剂量为：术后第1天，0.4g，qd；第2天，0.3g，bid，连续3天。上述药物使用中，合理的用药方式是","o":["使用依替米星预防感染","术后第1天使用剂量过高","术后第2天使用剂量过高","清洁型手术无需预防性使用抗菌药物","术后用药天数不足"],"a":4,"e":"骨科关节手术预防用抗菌药应术前0.5～2小时开始并覆盖术后24～48小时，本例仅术后给药且疗程安排不合理，术后用药天数不足；依替米星为氨基糖苷类，耳肾毒性明显，不宜作预防用药，应选头孢唑林。B、C项剂量判断非核心；D项植入物手术仍需预防用药"},{"q":"某胆绞痛患者，在乡镇医院仅使用哌替啶止痛，发现未能缓解，其原因是","o":["引起便秘","引起胆道括约肌痉挛","镇痛作用弱","抑制胆汁分泌","易成瘾"],"a":1,"e":"哌替啶虽为阿片类镇痛药，但可兴奋胆道平滑肌、引起Oddi括约肌痉挛，使胆道内压升高而加重胆绞痛，故单用不能缓解。A项便秘、E项成瘾为其一般不良反应；C项哌替啶镇痛作用并不弱；D项抑制胆汁分泌不是绞痛不缓解的主要原因"},{"q":"患者，女，45岁。有轻度甲状腺功能亢进病史2年，并患有支气管哮喘，合用下列药物半年，出现皮肤变薄、多毛、糖尿。引起该不良反应的药物应是","o":["卡比马唑","曲安西龙","沙丁胺醇","甲硫氧嘧啶","氨茶碱"],"a":1,"e":"曲安西龙为糖皮质激素，长期应用致皮肤变薄、多毛、血糖升高及伤口愈合延迟，符合本例表现。A项卡比马唑、D项甲硫氧嘧啶为抗甲状腺药；C项沙丁胺醇为β2激动药；E项氨茶碱为平喘药，均无上述糖皮质激素样代谢不良反应"},{"q":"某心源性水肿患者，用地高辛和氢氯噻嗪治疗，2周后患者出现多源性室性期前收缩，其主要原因是","o":["低钠血症","低钾血症","低镁血症","高钙血症","低氯性碱中毒"],"a":1,"e":"氢氯噻嗪抑制髓袢升支粗段皮质部Na＋-K＋-2Cl－共转运，使K＋排出增多，低血钾可诱发地高辛中毒致多源性室性期前收缩。A项低钠血症、C项低镁血症虽可由利尿药引起，但诱发洋地黄心律失常以低钾最关键；D项高钙、E项低氯性碱中毒非主因"},{"q":"患者，女，因发热伴意识丧失3天入院。查体：皮肤黄染，囟门饱满，双侧病理反射阳性，脑脊液提示大量中性粒细胞。首选下列哪个药物治疗","o":["红霉素","青霉素G","阿米卡星","氯霉素","庆大霉素"],"a":1,"e":"发热、意识丧失、囟门饱满、脑脊液大量中性粒细胞提示化脓性脑膜炎，青霉素G对脑膜炎奈瑟菌等敏感菌杀菌力强，易透过炎症脑膜，为首选。A项红霉素、C项阿米卡星、D项氯霉素、E项庆大霉素脑脊液浓度低或抗菌谱不符，非首选"},{"q":"患者，女，40岁，因患扁桃体炎肌注青霉素G进行治疗时，引起局部疼痛的副作用。副作用是指","o":["与治疗目的无关的作用","用药量过大或用药时间过久引起的","用药后给病人带来的不舒适的反应","在治疗剂量出现与治疗目的无关的作用","停药后，残存药物引起的反应"],"a":3,"e":"副作用指在治疗剂量下出现的与治疗目的无关的作用，如肌注青霉素G的局部疼痛，源于药物作用选择性低。A项仅强调与治疗目的无关，未限定治疗剂量；B项用量过大为毒性反应；C项表述笼统；E项停药后残存反应为后遗效应"},{"q":"患者，男，65岁。患高血压22年，一直服用缬沙坦进行治疗。一周前患感冒。昨日夜间突然出现头晕、胸闷、口唇发绀、喘息、咳粉红色泡沫样痰。查体：BP 180/95mmHg，P 100次/min。急诊入院后应给予治疗的利尿药是","o":["静脉注射呋塞米","静脉注射甘露醇","静脉注射乙酰唑胺","口服螺内酯","口服氢氯噻嗪"],"a":0,"e":"急性左心衰竭肺水肿需快速利尿、减轻前负荷，呋塞米静脉注射起效快、作用强，并扩张静脉缓解肺淤血，为首选。B项甘露醇为渗透性利尿药，可增加血容量；C项乙酰唑胺、D项螺内酯、E项氢氯噻嗪起效慢或利尿弱，不适于急性肺水肿"},{"q":"患者，男，49岁，嗜酒。近期晨醒时出现不明原因胸骨后闷痛，起床后消失。住院后每天早晨均有胸痛发作，含硝酸甘油后有效。心绞痛发作时进行心电图记录，记录到损伤电流型的ECG改变伴有多源期前收缩，发作后左胸联R波增高、伴有缺血性ST-T改变。平板运动试验阴性。诊断为变异型心绞痛。该患者最宜使用的治疗药物是","o":["地尔硫䓬","普萘洛尔","硝苯地平","卡托普利","缬沙坦"],"a":2,"e":"变异型心绞痛由冠脉痉挛引起，硝苯地平阻滞钙通道、扩张冠状动脉，解除痉挛效果最好。B项普萘洛尔阻断β2受体后α缩血管占优势，可加重痉挛，禁用；A项地尔硫䓬、D项卡托普利、E项缬沙坦对急性冠脉痉挛缓解不如硝苯地平直接"},{"q":"患者，男，54岁。近日服用洋地黄类药物后，患者将白大衣看成是绿色，可能是","o":["血钾过高","血钠过高","洋地黄中毒","心力衰竭症状好转","精神症状"],"a":2,"e":"服用洋地黄类后视物发绿即绿视，是洋地黄中毒的经典中枢神经系统表现，常伴恶心、黄视和心律失常。A项高血钾、B项高钠血症不产生绿视；D项心衰好转无此色觉改变；E项精神症状非特异性，绿视对中毒有提示意义"},{"q":"患者，女，52岁，患支气管哮喘20余年。依赖糖皮质激素10余年。长期应用糖皮质激素，其对代谢的影响，叙述错误的是","o":["高血糖","高血钾","脂肪重新分布","低血钙","负氮平衡"],"a":1,"e":"糖皮质激素促进蛋白分解、抑制合成，致负氮平衡；使脂肪重新分布、血糖升高、血钙降低，并促进排钾致低血钾，故高血钾错误。A项高血糖、C项脂肪重新分布、D项低血钙、E项负氮平衡均为其真实代谢影响"},{"q":"患者，男，56岁，因胸部有环形红斑就诊。查体见胸部红斑略高起，皮面光滑，边缘不清。温觉迟钝、痛、触觉存在。背部、大腿内侧也见相似皮损，查抗酸杆菌（+++），临床诊断为麻风。患者过去服用伯氨喹后出现溶血性贫血。请问需选择下列哪个药物治疗","o":["异烟肼","氨苯砜","乙胺丁醇","链霉素","氯法齐明"],"a":4,"e":"麻风患者曾用伯氨喹出现溶血性贫血，提示可能存在G6PD缺乏，应禁用可致溶血的氨苯砜，选用氯法齐明。A项异烟肼、C项乙胺丁醇为抗结核药；B项氨苯砜为砜类，可致溶血，属禁忌；D项链霉素为氨基糖苷类，非麻风首选"},{"q":"某心衰患者长期口服地高辛，疗效较好，后因三叉神经痛应用苯妥英钠，结果出现心衰症状，这是因为","o":["苯妥英钠有致心衰的不良反应","苯妥英钠与地高辛竞争血浆蛋白","苯妥英钠减少地高辛的吸收","苯妥英钠促进地高辛排泄","苯妥英钠诱导肝药酶加速地高辛代谢"],"a":4,"e":"苯妥英钠为肝药酶诱导剂，加速地高辛在肝内代谢并促进其清除，使血药浓度下降、心衰症状重现。A项苯妥英钠本身无致心衰作用；B项竞争血浆蛋白结合可短暂增加游离药物，但地高辛主要经肾排；C项不影响吸收；E项表述不确切，主要通过酶诱导加速代谢"},{"q":"患者，女，53岁，患高血压和慢性肾小球肾炎3年，一直规律服用福辛普利和螺内酯进行治疗。1周前“上呼吸道感染”后出现尿量减少，近2日尿量约每天100ml。该患者最可能出现的电解质紊乱是","o":["血钠升高","血钙升高","血镁降低","血钾升高","血钾降低"],"a":3,"e":"福辛普利抑制醛固酮生成，螺内酯拮抗醛固酮受体，两药合用并遇感染、少尿致肾功能减退，钾排出减少，最易出现血钾升高。A项血钠升高、B项血钙升高、C项血镁降低均非该组合典型表现；E项血钾降低与两药保钾作用相反"},{"q":"患者，女，40岁。2小时前服用50%敌敌畏60ml，10分钟后出现呕吐、大汗，随后昏迷，急送入院。检查：呼吸急促，32次/min，血压140/100mmHg，心律失常，肠鸣音亢进，双侧瞳孔约2mm，有肌颤，全血AChE活力为30%。患者最佳的抢救原则是洗胃的同时给予","o":["口服阿托品＋静脉滴注解磷定","口服新斯的明＋静脉注射阿托品","静脉滴注解磷定＋静脉注射阿托品","静脉注射新斯的明+静脉注射阿托品","口服毒扁豆碱+静脉注射新斯的明"],"a":2,"e":"有机磷酸酯中毒抢救以洗胃清除毒物，同时静脉注射阿托品阻断M样症状、静脉滴注解磷定复活胆碱酯酶，两药合用标本兼治。A、B、D、E项口服新斯的明或毒扁豆碱会加重乙酰胆碱蓄积；阿托品口服吸收慢且呕吐时不宜，须静脉给药"},{"q":"患者，男，40岁，因头疼就医，自述患有糖尿病且一直服用口服降糖药。两次血压测定结果为163/102mmHg和165/100mmHg，初步诊断为高血压。该患者的最佳的初始治疗方案是","o":["非洛地平+普萘洛尔","呋塞米+氢氯噻嗪","普萘洛尔+呋塞米","赖诺普利+缬沙坦","赖诺普利+吲达帕胺"],"a":4,"e":"糖尿病合并高血压初始治疗宜选ACEI联合噻嗪类利尿药，赖诺普利加吲达帕胺降压协同且对糖代谢影响小。B项呋塞米加氢氯噻嗪均为利尿药，机制重复；C项普萘洛尔掩盖低血糖症状；D项赖诺普利加缬沙坦同属RAAS阻断，不推荐联用；A项非洛地平加普萘洛尔对糖尿病非最优"},{"q":"患者，女，35岁，有哮喘病史，近期诊断为甲亢，不宜使用下列哪种药物","o":["丙硫氧嘧啶","甲硫氧嘧啶","普萘洛尔","卡比马唑","甲巯咪唑"],"a":2,"e":"普萘洛尔为非选择性β受体阻断药，阻断支气管β2受体可诱发痉挛，哮喘患者禁用，甲亢治疗不宜使用。A项丙硫氧嘧啶、B项甲硫氧嘧啶、D项卡比马唑、E项甲巯咪唑均通过抑制甲状腺激素合成治疗甲亢，不加重哮喘"},{"q":"患者，男，50岁，因工作强度大而经常熬夜，近来出现前胸阵发性、压榨性疼痛，每日发作数次，每次发作持续3～5分钟，治疗时不可使用以下哪种药物","o":["喷他佐辛","硝酸甘油","美托洛尔","丁丙诺啡","硝苯地平"],"a":0,"e":"喷他佐辛为阿片类部分激动药，可增加心率和血压、提高心肌耗氧量，加重心绞痛，不宜使用。B项硝酸甘油、C项美托洛尔、E项硝苯地平为抗心绞痛药；D项丁丙诺啡亦为部分激动药，但本题以喷他佐辛增心率作用最不宜"},{"q":"患者，45岁。行肝脏移植术后使用他克莫司抑制移植排斥反应。以下选项中最容易发生的不良反应是","o":["高血压","高血钾","肾毒性","低血压","出血性膀胱炎"],"a":2,"e":"他克莫司为钙调磷酸酶抑制剂，最主要不良反应是肾毒性，表现为血肌酐升高、肾小球滤过率下降，需监测血药浓度。A项高血压、B项高血钾也可发生但不如肾毒性突出；D项低血压少见；E项出血性膀胱炎为环磷酰胺典型毒性"},{"q":"患者，女，71岁，以反复心前区不适1年、加重3小时入院，心电图检查示“急性下壁心肌梗死”，立即给予阿司匹林300mg、氯吡格雷300mg嚼服，为溶栓做准备。其中，阿司匹林属于","o":["凝血酶间接抑制药","纤维蛋白溶解药","抑制血小板花生四烯酸代谢的药物","增加血小板内cAMP的药物","抑制ADP活化血小板的药物"],"a":2,"e":"阿司匹林不可逆抑制血小板环氧合酶，减少血栓素A2生成，属抑制血小板花生四烯酸代谢的药物。A项凝血酶间接抑制药为肝素；B项纤维蛋白溶解药为尿激酶；D项增加cAMP为双嘧达莫；E项抑制ADP活化为氯吡格雷"},{"q":"患者，男，15岁，近日有乏力、头痛、咽痛、发冷、发热、肌肉酸痛等，体温达39℃。于发病第三天出现明显的阵发性刺激性咳嗽，咳少量黏痰。检查X线胸片：肺纹理增多，肺下叶呈斑点状模糊阴影。青霉素类药物治疗效果不好，考虑为支原体肺炎，血清学检查也给予支持，应首选","o":["氯霉素","氨苄西林","多西环素","青霉素","庆大霉素"],"a":2,"e":"支原体无细胞壁，青霉素、头孢类无效，多西环素为四环素类，抑制蛋白质合成，是支原体肺炎首选。A项氯霉素、E项庆大霉素非首选且毒性大；B项氨苄西林、D项青霉素作用于细胞壁，对支原体无效"},{"q":"患者，女，40岁，近半年常感心慌、气短、眩晕，结合心电图检查诊断为阵发性室上性心动过速，可选用的治疗药物是","o":["阿托品","醋甲胆碱","新斯的明","去甲肾上腺素","肾上腺素"],"a":2,"e":"新斯的明抑制胆碱酯酶、增强迷走神经张力，可减慢房室传导，用于阵发性室上性心动过速的终止。A项阿托品阻断迷走神经，加快心率；B项醋甲胆碱为M激动药但作用广泛；D项去甲肾上腺素、E项肾上腺素兴奋心脏，可加快心率"},{"q":"患者，女，49岁，因右侧乳房发现肿块2个月就诊。检测发现右侧乳房皮肤出现橘皮样改变，触诊可触及质地硬且表面不光滑肿块，与周围组织分解不清，活动性差，无压痛。取活检病理报告为乳腺癌。行乳腺癌根治术后给予化疗药物联合治疗。其中使用的药物有抗雄激素的作用，主要临床应用为治疗乳腺癌和卵巢癌。以下哪个药物最符合此案例描述","o":["紫杉醇","氟尿嘧啶","多柔比星","他莫昔芬","阿糖胞苷"],"a":3,"e":"他莫昔芬为选择性雌激素受体调节剂，在乳腺组织竞争性阻断雌激素受体，抑制乳腺癌细胞生长，临床用于乳腺癌和卵巢癌。A项紫杉醇、B项氟尿嘧啶、C项多柔比星为细胞毒类化疗药；E项阿糖胞苷主要用于白血病，均无抗雌激素受体作用"},{"q":"患者，男，40岁，患有胃消化性溃疡10余年。近日病情加重，给予奥美拉唑治疗1个月，症状好转。为了促进溃疡愈合和保护胃黏膜，可给予的前列腺素类药物口服制剂是","o":["双嘧达莫","前列环素","米索前列醇","地诺前列酮","奥美拉唑"],"a":2,"e":"米索前列醇为人工合成前列腺素E1衍生物，抑制胃酸分泌并促进胃黏液和碳酸氢盐分泌、增加胃黏膜血流，保护胃黏膜，口服用于消化性溃疡。A项双嘧达莫为抗血小板药；B项前列环素、D项地诺前列酮主要用于产科或静脉；E项奥美拉唑为质子泵抑制剂，非前列腺素类"},{"q":"患者，女，45岁，因体检时B超发现左侧卵巢4cm×4cm大小肿物就诊，CT证实肿物存在，考虑是卵巢癌。拟手术治疗，行蛛网膜下腔麻醉，术中血压下降，最宜选用以下哪种药物","o":["肾上腺素","去甲肾上腺素","阿托品","麻黄碱","多巴胺"],"a":3,"e":"蛛网膜下腔麻醉阻滞交感神经致血管扩张、血压下降，麻黄碱激动α、β受体，收缩血管并兴奋心脏，升压作用温和持久，为首选。A项肾上腺素、B项去甲肾上腺素升压剧烈；C项阿托品用于心率减慢；E项多巴胺主要用于休克，非椎管内麻醉低血压首选"},{"q":"患者，女，61岁。高血压病史10余年，合并慢性心功能不全，遵医嘱一直服用卡维地洛。卡维地洛对肾上腺素受体的作用是","o":["选择性阻断α1受体","选择性阻断α2受体","非选择性阻断α受体","可同时阻断α和β受体","非选择性阻断β受体"],"a":3,"e":"卡维地洛为第三代β受体阻断药，可同时阻断α1和β受体，兼有扩血管和减慢心率作用，用于心衰和高血压。A项选择性α1阻断药为哌唑嗪；B项选择性α2阻断药少用；C项非选择性α阻断药为酚妥拉明；E项非选择性β阻断药为普萘洛尔"},{"q":"某患，56岁，诊断为高血压型充血性心力衰竭，遵医嘱服用地高辛。地高辛半衰期为33h，按每日给予治疗量，问血药浓度何时达到稳态","o":["3日","6日","9日","12日","15日"],"a":1,"e":"按一级动力学消除的药物，血药浓度达稳态约需4～5个半衰期，地高辛t1/2为33小时，5个半衰期约165小时，即约6日可达稳。A项3日仅约2个半衰期，浓度不足；C项9日、D项12日、E项15日均远超达稳态所需时间"},{"q":"患者，女，43岁，在其子婚礼上由于兴奋而突发心绞痛，请问可用哪种药","o":["硫酸奎尼丁口服","盐酸普鲁卡因胺口服","硝酸甘油舌下含服","盐酸利多卡因注射","苯妥英钠注射"],"a":2,"e":"情绪激动诱发的心绞痛宜舌下含服硝酸甘油，扩张静脉降低前负荷、扩张冠脉增加供血，起效快。A项奎尼丁、B项普鲁卡因胺为抗心律失常药；D项利多卡因、E项苯妥英钠用于室性心律失常和洋地黄中毒，均无抗心绞痛作用"},{"q":"对于接受冠状动脉介入治疗术（PCI）的患者，术后为防止血栓栓塞事件的发生，现已证明，可以与阿司匹林合用，组成双联抗血小板治疗的药物是","o":["达比加群","华法林","氯吡格雷","肝素","水蛭素"],"a":2,"e":"PCI术后双联抗血小板治疗为阿司匹林联合氯吡格雷，氯吡格雷不可逆抑制血小板ADP受体，阻断聚集，预防支架内血栓。A项达比加群、B项华法林、D项肝素、E项水蛭素均为抗凝药，不属于抗血小板治疗组合"},{"q":"患者，女，48岁，结核病服用异烟肼和乙胺丁醇后5天在上网时忽然感到手麻木，其后逐渐加重，出现双手麻木，请问这是什么原因","o":["结核病加重，侵犯手部","乙胺丁醇所致的肝脏毒性累及神经系统","异烟肼所致周围神经炎","乙胺丁醇所致周围神经炎","异烟肼与乙胺丁醇相互作用所致副作用"],"a":2,"e":"异烟肼结构与维生素B6相似，竞争性抑制其利用，引起周围神经炎，表现为手足麻木，加用维生素B6可预防。B项乙胺丁醇主要致球后视神经炎；D项乙胺丁醇虽抑结核但非本题原因；A项结核侵犯手部少见；E项两药无此相互作用"},{"q":"患者，女，59岁，被诊断为结核病，服用下列一种药物后使原来服用的口服降糖药效果下降，请问是下列哪个抗结核病药","o":["异烟肼","吡嗪酰胺","利福平","链霉素","对氨基水杨酸"],"a":2,"e":"利福平为强效肝药酶诱导剂，加速口服降糖药在肝内代谢，使其血药浓度降低、降糖效果下降。A项异烟肼、B项吡嗪酰胺、D项链霉素、E项对氨基水杨酸对肝药酶诱导作用弱，不明显影响口服降糖药疗效"},{"q":"患者，女，54岁。患风湿性二尖瓣关闭不全多年，用地高辛和氢氯噻嗪维持疗效。但近日呼吸困难加重，夜间频繁发作，心慌，两肺满肺野湿性啰音，经检查左室舒张期充盈压明显升高。除上述药物外，该加用哪种药物进行治疗","o":["米力农","多巴胺","卡托普利","氨力农","硝普钠"],"a":4,"e":"风心病二尖瓣关闭不全伴左室舒张期充盈压升高、肺淤血，硝普钠均衡扩张动静脉，降低前后负荷，减轻肺充血。A项米力农、D项氨力农为正性肌力药，可增加耗氧；B项多巴胺兴奋心脏；C项卡托普利虽扩血管，但急性肺淤血时硝普钠起效更快更强"},{"q":"患者，男，52岁，患高血压20年，一直服用卡托普利进行治疗。近日反复出现头晕、胸闷等症状。查体：BP 160/95mmHg，P 88次/min。该患者可以联合应用的利尿药是","o":["氢氯噻嗪","呋塞米","螺内酯","氨苯喋啶","乙酰唑胺"],"a":0,"e":"卡托普利与氢氯噻嗪合用降压协同，噻嗪类排钠缩减血容量，ACEI抑制RAAS并减轻其低钾倾向，为合理联合。B项呋塞米利尿强，多用于心衰或肾功能不全；C项螺内酯、D项氨苯蝶啶为保钾利尿药，与ACEI合用致高钾风险；E项乙酰唑胺非降压常规用药"},{"q":"患者，女，25岁，无明显诱因突然倒地，意识丧失，双眼上翻，牙关紧闭，四肢抽搐，持续2分钟后自行缓解，对之前的症状无记忆，请问该患者最适合使用下列哪种药物进行治疗","o":["苯妥英钠","丙戊酸钠","乙琥胺","地西泮","拉莫三嗪"],"a":0,"e":"突然意识丧失、双眼上翻、四肢抽搐、发作后无记忆，符合癫痫大发作，苯妥英钠阻滞钠通道、稳定神经元膜，为大发作首选。B项丙戊酸钠为广谱药；C项乙琥胺仅用于失神小发作；D项地西泮用于持续状态；E项拉莫三嗪多作辅助治疗"},{"q":"患者，女，58岁。出现腹痛、高热、寒战、黄疸，确诊急性胆囊炎，宜选下列何药治疗","o":["四环素","氨苄西林","氯霉素","庆大霉素","林可霉素"],"a":1,"e":"急性胆囊炎多由革兰阴性菌和厌氧菌感染，氨苄西林抗菌谱较广、胆汁浓度高，为常用药。A项四环素、C项氯霉素耐药多；D项庆大霉素耳肾毒性且胆汁浓度低；E项林可霉素主要针对革兰阳性菌和厌氧菌，覆盖不足"},{"q":"患者，男，65岁，近日出现活动后胸闷、憋气，伴夜间阵发性呼吸困难。经X线检查发现其左心增大、肺淤血；超声心动图检查发现其左心室舒张末期容积增加、每搏输出量和射血分数显著降低、左心室内径和左心房容积扩大；血压175/105mmHg。该患者宜使用的降压药物是","o":["血管紧张素转化酶抑制药","中枢性降压药","α受体阻断药","钙通道阻滞药","钾通道开放药"],"a":0,"e":"高血压伴左心增大、射血分数降低的收缩性心衰，ACEI抑制RAAS、降低前后负荷并逆转心室重构，为首选。B项中枢性降压药、C项α受体阻断药、D项钙通道阻滞药、E项钾通道开放药对心衰重构改善不如ACEI，部分还可加重心衰"},{"q":"患者，女，50岁。主诉上腹部疼痛、食欲缺乏、恶心等症状。诊断为慢性萎缩性胃炎，幽门螺杆菌检查为阳性，给予抗幽门螺杆菌三联治疗。下列无抗幽门螺杆菌作用的药物是","o":["氨苄西林","奥美拉唑","四环素","溴丙胺太林","枸橼酸铋钾"],"a":3,"e":"溴丙胺太林为M受体阻断药，抑制胃肠蠕动和分泌，无抗幽门螺杆菌作用。A项氨苄西林、C项四环素为抗菌药，可抗幽门螺杆菌；B项奥美拉唑抑制胃酸、抑制Hp生长；E项枸橼酸铋钾铋剂可杀灭Hp并保护胃黏膜"},{"q":"患者，男，75岁，高血压史15年，未长期规律用药。近期总感心慌、气短，心律不齐。判断其是否出现心功损害的最主要依据是","o":["早搏","肺部湿啰音","劳力性呼吸困难","下肢水肿","胸骨后疼痛"],"a":2,"e":"劳力性呼吸困难是左心功能不全最早、最常见的表现，反映肺淤血随活动加重，为判断心功能损害的主要依据。A项早搏可见于正常人；B项肺部湿啰音、D项下肢水肿可为其他疾病；E项胸骨后疼痛提示心肌缺血，非心功能损害特异指标"},{"q":"患者，男，25岁，患有十二指肠球部溃疡。近日复发，给予哌仑西平联合雷尼替丁进行治疗，哌仑西平抑制胃酸分泌的机制是","o":["阻断H2受体","阻断H1受体","阻断胃泌素受体","抑制H＋-K＋-ATP酶","阻断M1受体"],"a":4,"e":"哌仑西平为选择性M1受体阻断药，阻断胃壁细胞M1受体，抑制胃酸和胃蛋白酶分泌。A项阻断H2受体为雷尼替丁；B项H1受体阻断药为抗过敏药；C项胃泌素受体阻断药为丙谷胺；D项抑制H＋-K＋-ATP酶为奥美拉唑"},{"q":"患者，男，25岁，打架导致头皮外伤就诊，查体正常，需要局麻下缝合伤口。局麻药对神经纤维的作用是","o":["阻断Na＋内流","阻断K＋外流","阻断Ca2＋内流","阻断ACh释放","降低静息跨膜电位，抑制复极化"],"a":0,"e":"局麻药阻断神经纤维膜上的电压门控Na＋通道，抑制Na＋内流，阻止动作电位产生和传导而镇痛。B项K＋外流、C项Ca2＋内流非局麻药主要靶点；D项ACh释放为神经递质过程；E项描述的是对静息电位和复极的影响，非局麻药机制"},{"q":"患者，女，42岁，会计，因双眼不适2年就诊。双眼矫正视力1、0。眼压：左眼30mmHg，右眼25mmHg（眼压正常值为10～21mmHg）。前房角镜：宽角。可选用的治疗药物是","o":["醋甲胆碱","麻黄碱","烟碱","毛果芸香碱","琥珀胆碱"],"a":3,"e":"眼压升高、前房角为宽角，符合开角型青光眼，毛果芸香碱激动M受体，收缩瞳孔括约肌、拉开房角、促进房水回流而降眼压。A项醋甲胆碱、B项麻黄碱、C项烟碱、E项琥珀胆碱对房水和眼压无治疗作用，部分可升高眼压或致调节痉挛"},{"q":"患者，男，50岁。支气管哮喘10年，高血压病史14年。近日因感冒哮喘发作，除抗感染治疗外，拟选用β受体阻断剂降血压，应选择","o":["普萘洛尔","噻吗洛尔","吲哚洛尔","美托洛尔","纳多洛尔"],"a":3,"e":"哮喘患者需降压宜选β1选择性阻断药美托洛尔，对支气管β2受体影响较小，相对安全。A项普萘洛尔、B项噻吗洛尔、C项吲哚洛尔、E项纳多洛尔均为非选择性β阻断药，可收缩支气管、诱发哮喘发作"},{"q":"患者，男，34岁，因面部红斑、麻木感2个月就诊。查体见面部、胸部、背部、臀部泛发对称性浸润性红斑，边缘不清。查抗酸杆菌阳性，临床诊断为麻风病。请问首选用下列哪个药物治疗","o":["异烟肼","吡嗪酰胺","对乙酰氨基酚","链霉素","氨苯砜"],"a":4,"e":"麻风病首选氨苯砜，其竞争性抑制麻风分枝杆菌的叶酸合成，抗菌作用强、疗效确切且价格低，适合长期服药。A项异烟肼、B项吡嗪酰胺为抗结核药；C项对乙酰氨基酚为解热镇痛药；D项链霉素为氨基糖苷类，非麻风首选"},{"q":"患者，男，23岁。因上肢、后背、臀部及大腿内侧皮肤长疹就诊，诊断为过敏性皮炎。不宜外用的药物为","o":["可的松","氢化可的松","地塞米松","曲安西龙","氟轻松"],"a":0,"e":"可的松需在肝内转化为氢化可的松才具活性，局部外用转化不足、疗效差，故不宜外用。B项氢化可的松、C项地塞米松、D项曲安西龙、E项氟轻松均可直接外用抗炎，其中氟轻松作用强，适合皮肤炎症"},{"q":"患儿，5岁。拟行体表小血管瘤切除术。以下最适用于该患儿麻醉的药物是","o":["氟烷","芬太尼","氧化亚氮","氯胺酮","氯丙嗪"],"a":3,"e":"氯胺酮产生分离麻醉，镇痛确切、对呼吸循环抑制轻，且可肌注，特别适合小儿短小体表手术。A项氟烷、C项氧化亚氮需吸入装置；B项芬太尼为阿片类镇痛药，无麻醉作用；E项氯丙嗪为抗精神病药，不作麻醉药"},{"q":"患者，男，65岁。诊断为睾丸癌，为精原细胞癌，对化疗敏感，遂接受顺铂、长春碱和博来霉素的联合化疗。以下哪项不良反应一般不常发生","o":["肾毒性","骨髓抑制","耳毒性","脱发","心肌退行性变"],"a":4,"e":"顺铂、长春碱、博来霉素组成的PVB方案不含蒽环类，心肌退行性变是多柔比星等蒽环药的剂量限制性毒性，故一般不发生。顺铂主要引起肾毒性和耳毒性，骨髓抑制与脱发多见于长春碱，博来霉素则以肺纤维化为突出毒性。心肌损害并非本方案成分的不良反应，设为干扰项系与其他化疗方案混淆"},{"q":"患者，女，56岁，2年前确诊为冠心病，胸闷胸痛症状发作时服用硝酸甘油，用药后症状有所改善。但最近一个月胸痛症状又开始频繁出现，服用硝酸甘油后效果降低，遵医嘱加服乙酰半胱氨酸，其目的是","o":["祛痰，防止黏痰形成","使硝酸甘油缓慢释放，延长疗效","提供巯基，延缓硝酸甘油耐受性产生","降低硝酸甘油的不良反应","增加硝酸甘油的生物利用度，防止过快降解"],"a":2,"e":"硝酸甘油需经巯基代谢生成一氧化氮而扩血管，长期应用消耗血管壁巯基可产生耐受性，乙酰半胱氨酸提供巯基以延缓耐受。其祛痰作用用于稀释痰液，与本题缓解硝酸甘油失效无关。该药不改变硝酸甘油的释放速度、不良反应或生物利用度，仅通过补充巯基恢复药效"},{"q":"患者，男，咽炎，注射青霉素后1分钟，呼吸急促，面部发绀，心率130次/分，血压8.00/5、33kPa（60/40mmHg）。抢救药物是","o":["地塞米松＋去甲肾上腺素","地塞米松＋多巴胺","曲安西龙＋异丙肾上腺素","地塞米松＋肾上腺素","地塞米松＋山莨菪碱"],"a":3,"e":"青霉素过敏性休克属Ⅰ型变态反应，肾上腺素激动α受体收缩血管升压、激动β受体解除支气管痉挛，为首选抢救药，地塞米松辅助抗炎抗过敏。去甲肾上腺素仅供升压，无解除支气管痉挛之利；异丙肾上腺素扩张血管反可降压；多巴胺升压作用不及肾上腺素，均不宜作首选"},{"q":"患者，男，65岁，因发烧、咳嗽，新型冠状病毒核酸检测阳性收治入院。住院期间发展为急性呼吸窘迫综合征（ARDS），出现肺氧合功能障碍，PaO2＜50mmHg，使用体外膜氧合（ECMO）技术进行治疗，为了预防体外循环管路中的血栓形成，可使用的药物是","o":["华法林","肝素","链激酶","阿司匹林","利多格雷"],"a":1,"e":"ECMO体外循环需体外迅速抗凝，肝素通过激活抗凝血酶Ⅲ灭活多种凝血因子，体内外均起效、作用快且可用鱼精蛋白中和，为首选。华法林仅体内有效、体外无效，不能用于管路抗凝；链激酶为溶栓药，用于溶解已形成血栓而非预防；阿司匹林抗血小板作用弱，不足以维持管路通畅"},{"q":"患者，男，72岁，因胆囊炎反复发作入院行胆囊切除术。术后第二天患者睡眠后大汗惊醒，之后口干渴乏力，入睡差，疲乏等脱水症状。为缓解上述症状，可选用","o":["阿托品","地西泮","毛果芸香碱","哌替啶","山莨菪碱"],"a":0,"e":"术后大汗、口干渴等分泌亢进与脱水表现，阿托品阻断M受体抑制汗腺、唾液腺等外分泌，可减少出汗并缓解口干。毛果芸香碱为M受体激动剂，反促进腺体分泌，作用完全相反；山莨菪碱虽亦阻断M受体，但主要用于感染性休克与胃肠绞痛，抑制腺体分泌较弱；地西泮镇静、哌替啶镇痛均无止汗作用"},{"q":"患者，男，28岁，诊断为家族性混合型高脂血症，使用低脂饮食和考来烯胺治疗，该治疗方案降低哪种脂蛋白最显著","o":["TG","CM","VLDL","LDL","HDL"],"a":3,"e":"考来烯胺为胆汁酸螯合剂，在肠道结合胆汁酸阻断其重吸收，促使胆固醇转化为胆汁酸排出，故降低LDL最显著。甘油三酯（TG）与VLDL主要靠贝特类、烟酸降低，考来烯胺对其作用弱；HDL为保护性脂蛋白，治疗目标是升高而非降低；CM来自食物脂肪，主要靠饮食控制"},{"q":"患者，男，52岁，因无痛血尿就诊。查体正常，膀胱镜检查后尿道有出血点，尿中白细胞（＋＋），诊断为尿道感染。给予口服磺胺甲噁唑，此药生物利用度为100%，表明其","o":["口服吸收迅速","口服吸收完全","首过消除明显","与血浆蛋白结合率高","未经肝门脉吸收"],"a":1,"e":"生物利用度指药物经血管外给药吸收进入体循环的相对量与速度，100%说明口服剂量几乎全部吸收，即吸收完全。吸收迅速强调速度而非程度，生物利用度高不等于吸收快；首过消除明显者生物利用度反而降低；血浆蛋白结合率高、是否经肝门脉吸收均不能由生物利用度100%推出"},{"q":"患儿，男，11岁，因入院前2小时在附近山坡上采食鲜果后，出现口吐白沫，视物模糊，语无伦次，烦躁不安。检查：T 36.8℃，谵妄，皮肤潮红，两侧瞳孔对称散大，对光反应迟钝，心肺无异常。根据表现，该患儿最有可能是采食了","o":["洋地黄","曼陀罗果","罂粟","捕蝇蕈","金鸡纳树"],"a":1,"e":"患儿瞳孔散大、皮肤潮红、谵妄、视物模糊，为典型M受体阻断的阿托品样中毒，曼陀罗果含阿托品与东莨菪碱，采食后即出现上述抗胆碱表现。洋地黄中毒以恶心、黄视及心律失常为主；罂粟含阿片类，表现为瞳孔缩小、呼吸抑制；捕蝇蕈含毒蝇碱，呈流涎、多汗、瞳孔缩小等M样兴奋，均与散大瞳孔相反"},{"q":"患者，女，23岁，转移性右下腹疼痛2天，以“急性阑尾炎”收入院。拟在持续硬膜外麻醉下行阑尾切除术，术前应常规给予","o":["山莨菪碱","阿托品","苯巴比妥","新斯的明","毛果芸香碱"],"a":1,"e":"硬膜外麻醉前常规给阿托品，旨在阻断M受体抑制腺体分泌、防止迷走反射所致心率减慢与血压下降。山莨菪碱作用类似但多用于休克与平滑肌绞痛，非麻醉前常规药；苯巴比妥为镇静催眠药，可辅助麻醉但不解决腺体分泌问题；新斯的明、毛果芸香碱均为拟胆碱药，会增加分泌、加重迷走反射，属禁忌"},{"q":"患者，男，20岁，因急性化脓性阑尾炎在硬膜外麻醉下行阑尾切除术。麻醉前半小时给予阿托品0、5mg，这是因为阿托品可以","o":["解除胃肠痉挛","抑制呼吸道腺体分泌","加强镇痛效果","松弛膀胱平滑肌","扩张血管"],"a":1,"e":"麻醉前给阿托品的主要目的是抑制唾液腺与呼吸道腺体分泌，保持呼吸道通畅、防止误吸与术后肺部并发症。解除胃肠痉挛、松弛膀胱平滑肌虽是其M阻断作用，但并非麻醉前给药意图；扩张血管需较大剂量，可致面部潮红；阿托品无加强镇痛之功，不作镇痛辅助"},{"q":"某青年男患，急诊入院，初诊为吗啡类药物急性中毒，查体可见呼吸频率慢，呼吸无力，可使用哪种药物拮抗呼吸抑制","o":["哌替啶","可待因","芬太尼","曲马多","纳洛酮"],"a":4,"e":"纳洛酮为阿片受体纯拮抗剂，可迅速逆转吗啡引起的呼吸抑制、镇静与降压，是阿片类中毒的特异性解救药。哌替啶、可待因、芬太尼、曲马多均为阿片受体激动剂或部分激动剂，会加重呼吸抑制，中毒时禁用，不能用于拮抗"},{"q":"患者，女，48岁，患有结核病，服用异烟肼和乙胺丁醇5天后在上网时忽然感到手麻木，其后逐渐加重，出现双手麻木，应如何治疗","o":["加大异烟肼用量","加大乙胺丁醇用量","停用乙胺丁醇","加用利福平","加用维生素B6"],"a":4,"e":"异烟肼可竞争性抑制维生素B6，使其缺乏而致周围神经炎，表现为手足麻木，加用维生素B6可防治。加大异烟肼只会加重神经毒性；乙胺丁醇的典型毒性是球后视神经炎、视力下降与红绿色盲，与手麻木无关，故停乙胺丁醇不对应本症；利福平无纠正周围神经炎作用"},{"q":"患者，男，16岁，因向父亲要钱玩电脑游戏遭拒绝，吞服苯巴比妥50片（10g）。次日清晨家人发现患者昏迷不醒，送急诊科抢救。除洗胃等治疗措施外，为加速此药从肾脏排泄，应采取的措施是","o":["静脉滴注5%葡萄糖溶液","静脉滴注20%甘露醇","静脉滴注10%低分子右旋糖酐","静脉滴注5%碳酸氢钠溶液","静脉滴注0、9%氯化钠溶液"],"a":3,"e":"苯巴比妥为弱酸性药物，静滴碳酸氢钠碱化尿液后，药物在肾小管中解离增多、脂溶性下降，重吸收减少而加速排泄，是巴比妥类中毒的重要措施。甘露醇为渗透性利尿剂，仅增加尿量、不碱化尿液；葡萄糖与氯化钠溶液无碱化作用，不能有效促进弱酸性药物排出"},{"q":"患者，男，68岁，发烧、咳嗽、咳黄绿色浓痰、呼吸困难，考虑为铜绿假单胞菌感染导致肺炎。以下药物不宜采用的是","o":["哌拉西林","头孢哌酮","庆大霉素","氟罗沙星","氯霉素"],"a":4,"e":"氯霉素抗菌谱以伤寒沙门菌、立克次体等为主，对铜绿假单胞菌无抗菌活性，故不宜采用。哌拉西林属抗假单胞菌青霉素，头孢哌酮为第三代头孢且对铜绿假单胞菌有效，庆大霉素等氨基糖苷类对其杀灭力强，氟罗沙星属喹诺酮类亦有活性，四者均可用于铜绿假单胞菌感染"},{"q":"患者，女，68岁，因关节痛加重2周就诊。患者10年前诊断为风湿性关节炎和静脉炎，医生给予保泰松与华法林合用，可产生","o":["减少吸收","诱导肝药酶，加速灭活","竞争与血浆蛋白结合","竞争性对抗","药理作用协同"],"a":2,"e":"保泰松与华法林血浆蛋白结合率均很高，合用竞争结合位点，使游离型药物浓度升高、作用与毒性增强，甚至引起出血。诱导肝药酶加速灭活是苯巴比妥等的作用；药理作用协同指两药经不同机制叠加，如阿司匹林与华法林；竞争性对抗指激动剂与拮抗剂争夺受体，均不符合本例"},{"q":"患者，女，24岁。血压150/100mmHg，心率110次/min。建议选用下列哪种药物","o":["硝苯地平","肼屈嗪","可乐定","利血平","普萘洛尔"],"a":4,"e":"患者血压升高且心率达110次/分，普萘洛尔阻断β受体，既减慢心率、降低心肌耗氧，又抑制肾素释放而降压，对心率快者尤为适宜。硝苯地平、肼屈嗪扩张血管可反射性加快心率，不利于本例；可乐定、利血平虽可降压，但无针对性控制心率之效"},{"q":"某老年患者，晚期癌痛使用吗啡治疗，嘱家属注意不良反应。与吗啡使用无关的不良反应是","o":["呼吸抑制","止咳作用","体位性低血压","腹泻稀便症状","支气管收缩"],"a":3,"e":"吗啡兴奋胃肠平滑肌、抑制蠕动并减少分泌，引起便秘而非腹泻，故腹泻稀便与其使用无关。呼吸抑制是吗啡最严重的不良反应，止咳为其镇咳作用的应用，体位性低血压源于扩血管，支气管收缩与释放组胺有关，四者均为吗啡已知作用"},{"q":"患者，男，50岁，因患新型冠状病毒肺炎（COVID-19）收治入院，属于重症感染，使用体外膜氧合（ECMO）技术进行治疗，在插管前给肝素100U/kg，随后持续泵入肝素，经抗病毒与支持治疗后，患者症状好转，PaO2维持在80～120mmHg，PaCO2维持在35～45mmHg，在撤除ECMO拔管前给予负荷量肝素，在拔管后应使用何种药物中和肝素的作用","o":["维生素K","凝血酶","氨甲苯酸","鱼精蛋白","纤维蛋白原"],"a":3,"e":"鱼精蛋白为强碱性蛋白，可与强酸性的肝素结合形成无活性复合物，是中和肝素过量的特异性拮抗剂，用于拔管后对抗肝素。维生素K是华法林的解毒剂，通过促进凝血因子合成起效，对肝素无效；氨甲苯酸为抗纤溶药；凝血酶、纤维蛋白原仅补充凝血成分，均不能中和肝素"},{"q":"患儿，女，5岁。发热，浑身无力，检查发现扁桃体Ⅱ度肿大，准备给予口服抗菌药物。影响牙釉质及骨骼发育、不可以选用的药物是","o":["氯霉素","氨苄西林","四环素","红霉素","庆大霉素"],"a":2,"e":"四环素可与钙形成难溶络合物沉积于牙齿和骨骼，致牙釉质发育不全、牙齿黄染并抑制骨骼生长，故儿童及孕妇禁用。氯霉素主要引起骨髓抑制与灰婴综合征；庆大霉素有耳、肾毒性；氨苄西林、红霉素相对安全，均不影响牙釉质与骨骼发育"},{"q":"患者，男，64岁。高胆固醇血症，近半年来频发心前区疼痛，为高心肌梗死危险人群。选择下列哪一种药作为一线治疗药物","o":["鱼油","考来烯胺","烟酸","普罗布考","洛伐他汀"],"a":4,"e":"他汀类抑制HMG-CoA还原酶，显著降低LDL-C并能稳定斑块、降低心血管事件，是高胆固醇血症合并心梗高危者的一线药物，洛伐他汀即属此类。考来烯胺、烟酸、普罗布考虽可降脂，但疗效或耐受性不及他汀，多作辅助；鱼油主要降甘油三酯，均非首选"},{"q":"患者，女，59岁，发现蛋白尿20年，肌酐升高5年余。患者目前进行血液透析，每周2次。为防止透析器堵塞，应选择的抗凝药物是","o":["水蛭素","链激酶","华法林","肝素","阿司匹林"],"a":3,"e":"血液透析需体外抗凝且要求作用迅速、可控，肝素体内外均有效、起效快、易于监测，为透析抗凝首选。华法林仅在体内依赖维生素K途径起效，体外无抗凝作用；链激酶为溶栓药；阿司匹林抗血小板作用弱且不可逆，均不适合防止透析器凝血"},{"q":"患者，男，45岁，因全身真菌感染服用抗真菌药治疗后出现血白细胞和血小板数目减少，提示骨髓造血功能抑制。该不良反应最常见于哪种药物","o":["氟康唑","氟胞嘧啶","灰黄霉素","特比萘芬","制霉菌素"],"a":1,"e":"氟胞嘧啶在真菌内转化为氟尿嘧啶干扰核酸合成，最常见骨髓抑制，表现为白细胞与血小板减少，还可有肝损害。氟康唑、特比萘芬耐受性较好，骨髓抑制少见；灰黄霉素主要致头痛、胃肠反应；制霉菌素口服不吸收、毒性低，多局部使用，均非骨髓抑制的典型药物"},{"q":"患者，男，60岁，高血压病史及溃疡病史10余年。最近查体发现左心室肥厚，偶发阵发性室上性心律失常，选择下列何种药物降压为宜","o":["肼屈嗪","维拉帕米","利舍平","吗啡","硝苯地平"],"a":1,"e":"维拉帕米为钙通道阻滞剂，能扩张血管降压、减慢心率并延长房室结传导，对阵发性室上性心律失常有效，适合本例。肼屈嗪、硝苯地平扩张血管可反射性增快心率；利血平耗竭儿茶酚胺，会加重溃疡并致抑郁，溃疡病史者不宜；吗啡非降压药"},{"q":"患者，女，37岁。支气管哮喘病史10年，近3年症状逐渐加重。每天需吸入沙丁胺醇气雾剂1～2次，以缓解胸闷症状。1周前患者出现夜间咳嗽、憋醒，医生让患者加服氨茶碱。目前认为氨茶碱平喘的主要机制是","o":["抑制磷酸二酯酶，提高平滑肌内cAMP的含量","激活磷酸二酯酶，降低平滑肌内cAMP的含量","促进肾上腺素的释放","抑制鸟苷酸环化酶","激动支气管平滑肌上的β受体"],"a":0,"e":"氨茶碱抑制磷酸二酯酶，减少cAMP降解，使支气管平滑肌内cAMP升高而松弛平滑肌，并可阻断腺苷受体、强心利尿，为其平喘主要机制。激动β2受体是沙丁胺醇等的作用；激活磷酸二酯酶会降低cAMP、加重痉挛；抑制鸟苷酸环化酶、促进肾上腺素释放均非其机制"},{"q":"患者，男，60岁，患下肢静脉曲张10余年，近2日因右侧下肢肿胀、疼痛入院，诊断为急性深部静脉血栓，此时可用来治疗的药物是","o":["华法林","双香豆素","尿激酶","右旋糖酐","枸橼酸钠"],"a":2,"e":"尿激酶可直接激活纤溶酶原转化为纤溶酶，溶解已形成的纤维蛋白血栓，用于急性深静脉血栓等溶栓治疗。华法林、双香豆素为维生素K拮抗剂，只能抑制新血栓形成与扩展，不能溶解既有血栓；右旋糖酐主要扩容、抑制血小板聚集；枸橼酸钠仅体外抗凝，均非溶栓药"},{"q":"患儿，女，6岁，因误服敌敌畏送急诊抢救，洗胃后给予阿托品、碘解磷定治疗。目前患儿出现皮肤潮红，瞳孔扩大，心率加快，应采取的措施是","o":["加大阿托品用量","加大碘解磷定用量","肌注毛果芸香碱","阿托品逐渐减量至停药","导泻"],"a":3,"e":"皮肤潮红、瞳孔扩大、心率加快是阿托品化的表现，提示阿托品已足量，应逐渐减量维持并停药，防止阿托品中毒。此时加大阿托品可致谵妄、高热甚至中毒；碘解磷定已发挥复能作用，无需加大；毛果芸香碱用于阿托品中毒的对抗，而非阿托品化减量阶段；导泻与该处理无关"}];
